-- Studio moves into the CRM database (generated by scripts/codemods/studio-merge-schema.py,
-- then reviewed). Studio data is keyed by the CRM Location; Prisma manages only `public`.
BEGIN;
SET LOCAL check_function_bodies = false;
CREATE SCHEMA studio;
REVOKE ALL ON SCHEMA studio FROM PUBLIC;

--
-- Name: platform_clear_youtube_connection(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.platform_clear_youtube_connection(p_app text, p_user text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_app is null or p_app not in ('estio','substo') or p_user is null or btrim(p_user)='' then raise exception 'Invalid profile' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||p_app||':'||p_user,0));
  delete from studio.platform_google_youtube_connections where app=p_app and clerk_user_id=p_user;
  delete from studio.platform_google_youtube_oauth_states where app=p_app and clerk_user_id=p_user;
end;
$$;

--
-- Name: platform_delete_profile(text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.platform_delete_profile(p_app text, p_user text, p_event_id text, p_occurred_at timestamp with time zone, p_body_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare prior studio.platform_profile_deletion_events%rowtype; result jsonb;
 already_deleted boolean; credentials integer; consents integer; authorizations integer; recurrences integer;
begin
 if p_app is null or p_app not in ('estio','substo') or p_user is null or p_user !~ '^user_[A-Za-z0-9_-]{1,180}$'
 or not isfinite(p_occurred_at) or p_event_id is null or p_event_id !~ '^[A-Za-z0-9_-]{1,200}$' or p_occurred_at is null
 or p_body_digest is null or p_body_digest !~ '^[0-9a-f]{64}$' then raise exception 'Invalid verified deletion' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||p_app||':'||p_user,0));
 -- Event identities are scoped to their signing realm. Serialize collisions even
 -- when conflicting deliveries name different profile IDs.
 perform pg_advisory_xact_lock(hashtextextended('profile-deletion-event:'||p_app||':'||p_event_id,0));
 select * into prior from studio.platform_profile_deletion_events where app=p_app and event_id=p_event_id;
 if found then
  if prior.clerk_user_id<>p_user or prior.occurred_at<>p_occurred_at or prior.body_digest<>p_body_digest then raise exception 'Deletion event reused' using errcode='23505'; end if;
  return prior.result;
 end if;
 already_deleted:=exists(select 1 from studio.platform_profile_deletions where app=p_app and clerk_user_id=p_user);
 insert into studio.platform_profile_deletions(app,clerk_user_id,first_event_id,occurred_at) values(p_app,p_user,p_event_id,p_occurred_at) on conflict do nothing;
 -- Count before the existing connection trigger removes its private sources.
 credentials:=(select count(*) from studio.platform_google_youtube_connections where app=p_app and clerk_user_id=p_user);
 consents:=(select count(*) from studio.platform_google_youtube_oauth_states where app=p_app and clerk_user_id=p_user);
 authorizations:=(select count(*) from studio.platform_youtube_schedule_authorizations where app=p_app and clerk_user_id=p_user);
 -- Pause all unattended workflows for this exact principal, including text runs.
 update studio.studio_schedule_recurring set enabled=false,next_run_at=null,version=version+1,last_outcome='profile_deleted',updated_at=clock_timestamp()
 where actor_app=p_app and authorized_by=p_user and enabled;
 get diagnostics recurrences=row_count;
 perform studio.platform_clear_youtube_connection(p_app,p_user);
 delete from studio.platform_youtube_schedule_authorizations where app=p_app and clerk_user_id=p_user;
 result:=jsonb_build_object('alreadyDeleted',already_deleted,'credentialsRemoved',credentials,'pendingConsentsRemoved',consents,
 'sourceAuthorizationsRemoved',authorizations,'recurrencesPaused',recurrences);
 insert into studio.platform_profile_deletion_events(app,event_id,clerk_user_id,occurred_at,body_digest,result)
 values(p_app,p_event_id,p_user,p_occurred_at,p_body_digest,result);
 return result;
end; $_$;

--
-- Name: platform_guard_active_google_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.platform_guard_active_google_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform studio.platform_require_active_profile(new.app,new.clerk_user_id);
 return new;
end; $$;

--
-- Name: platform_invalidate_youtube_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.platform_invalidate_youtube_schedules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 update studio.studio_schedule_recurring r set enabled=false,next_run_at=null,version=version+1,last_outcome='profile_grant_changed',updated_at=clock_timestamp()
 from studio.platform_youtube_schedule_authorizations g where r.location_id=g.location_id and r.schedule_id=g.schedule_id and r.activation_token=g.activation_token
 and g.app=old.app and g.clerk_user_id=old.clerk_user_id and r.enabled;
 delete from studio.platform_youtube_schedule_authorizations where app=old.app and clerk_user_id=old.clerk_user_id;
 update studio.studio_youtube_schedule_runs set source_mode=null,channel_id=null,title_prefix=null,connection_version=null,schedule_version=null
 where manual and actor_app=old.app and created_by_clerk_user_id=old.clerk_user_id and connection_version is not null;
 return old;
end; $$;

--
-- Name: platform_require_active_profile(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.platform_require_active_profile(p_app text, p_user text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if p_app is null or p_app not in ('estio','substo') or p_user is null or btrim(p_user)='' then raise exception 'Invalid profile' using errcode='22023'; end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('platform-youtube:'||p_app||':'||btrim(p_user),0));
 if exists(select 1 from studio.platform_profile_deletions where app=p_app and clerk_user_id=btrim(p_user)) then raise exception 'Profile deleted' using errcode='42501'; end if;
end; $$;

--
-- Name: platform_youtube_oauth(text, text, text, text, text, jsonb, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.platform_youtube_oauth(p_action text, p_app text, p_user text, p_session_hash text, p_state_hash text, p_cipher jsonb DEFAULT NULL::jsonb, p_client_id text DEFAULT NULL::text, p_scopes text[] DEFAULT NULL::text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_app is null or p_app not in ('estio','substo') or p_user is null or btrim(p_user)=''
    or p_session_hash is null or p_session_hash !~ '^[0-9a-f]{64}$' or p_state_hash is null or p_state_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid profile OAuth principal' using errcode='22023';
  end if;
  -- Serialize connection replacement/removal for one realm user across callbacks.
  perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||p_app||':'||p_user,0));
  if exists(select 1 from studio.platform_profile_deletions where app=p_app and clerk_user_id=p_user) then return false; end if;
  if p_action='begin' then
    delete from studio.platform_google_youtube_oauth_states where app=p_app and clerk_user_id=p_user;
    insert into studio.platform_google_youtube_oauth_states(app,clerk_user_id,session_hash,state_hash) values(p_app,p_user,p_session_hash,p_state_hash);
    return true;
  elsif p_action='consume' then
    update studio.platform_google_youtube_oauth_states set consumed_at=now()
      where app=p_app and clerk_user_id=p_user and session_hash=p_session_hash and state_hash=p_state_hash and consumed_at is null and expires_at>now();
    return found;
  elsif p_action='commit' then
    if p_client_id is null or btrim(p_client_id)='' or jsonb_typeof(p_cipher) is distinct from 'object'
      or octet_length(p_cipher::text)>20000
      or jsonb_typeof(p_cipher->'ciphertext') is distinct from 'string' or btrim(p_cipher->>'ciphertext')=''
      or jsonb_typeof(p_cipher->'iv') is distinct from 'string' or btrim(p_cipher->>'iv')=''
      or jsonb_typeof(p_cipher->'authTag') is distinct from 'string' or btrim(p_cipher->>'authTag')=''
      or jsonb_typeof(p_cipher->'keyId') is distinct from 'string' or p_cipher->>'keyId' !~ '^[a-z0-9_-]{1,32}$'
      or not (p_cipher ?& array['ciphertext','iv','authTag','keyId']) or p_scopes is null
      or not coalesce('https://www.googleapis.com/auth/youtube.readonly'=any(p_scopes),false) or cardinality(p_scopes)>100 or array_position(p_scopes,null) is not null then raise exception 'Invalid encrypted profile grant' using errcode='22023'; end if;
    delete from studio.platform_google_youtube_oauth_states where app=p_app and clerk_user_id=p_user and session_hash=p_session_hash
      and state_hash=p_state_hash and consumed_at is not null and expires_at>now();
    if not found then return false; end if;
    insert into studio.platform_google_youtube_connections(app,clerk_user_id,client_id,refresh_cipher,granted_scopes)
      values(p_app,p_user,p_client_id,p_cipher,p_scopes)
      on conflict(app,clerk_user_id) do update set client_id=excluded.client_id,refresh_cipher=excluded.refresh_cipher,
        granted_scopes=excluded.granted_scopes,version=gen_random_uuid(),connected_at=now();
    delete from studio.platform_google_youtube_oauth_states where app=p_app and clerk_user_id=p_user;
    return true;
  end if;
  raise exception 'Invalid OAuth action' using errcode='22023';
end;
$_$;

--
-- Name: studio_apply_knowledge_extraction(text, text, text, uuid, uuid, bigint, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_apply_knowledge_extraction(p_location_id text, p_actor_app text, p_clerk_user_id text, p_review_id uuid, p_request_id uuid, p_expected_version bigint, p_finding_indexes jsonb, p_confirm_pending boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare run studio.studio_idea_reviews%rowtype; prior studio.studio_knowledge_extraction_applications%rowtype;
 mapping studio.studio_knowledge_extraction_findings%rowtype; v_source_id uuid; finding jsonb; unit jsonb; idx integer; insight uuid; evidence_id uuid;
 is_reused boolean; request jsonb; result jsonb:='[]'; at_iso text; quote_offset integer; citation jsonb;
begin
 perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
 if p_request_id is null or p_expected_version is null or p_expected_version<1 or p_confirm_pending is distinct from true
  or p_finding_indexes is null or jsonb_typeof(p_finding_indexes)<>'array' then raise exception 'Confirm selected pending findings' using errcode='22023'; end if;
 if jsonb_array_length(p_finding_indexes) not between 1 and 10 or exists(select 1 from jsonb_array_elements(p_finding_indexes) x where jsonb_typeof(x)<>'number' or x::text !~ '^[0-9]$')
  or (select count(distinct x) from jsonb_array_elements(p_finding_indexes) x)<>jsonb_array_length(p_finding_indexes) then raise exception 'Invalid finding selection' using errcode='22023'; end if;
 request:=jsonb_build_object('reviewId',p_review_id,'version',p_expected_version,'indexes',p_finding_indexes,'actor',p_clerk_user_id,'app',p_actor_app,'confirm',p_confirm_pending);
 select * into run from studio.studio_idea_reviews where location_id=p_location_id and id=p_review_id and workflow='knowledge_extract' for update;
 if not found then raise exception 'Extraction not found' using errcode='22023'; end if;
 select * into prior from studio.studio_knowledge_extraction_applications where location_id=p_location_id and request_id=p_request_id;
 if found then
  if prior.request is distinct from request then raise exception 'Finding application request reused' using errcode='23505'; end if;
  return prior.result;
 end if;
 v_source_id:=(run.snapshot#>>'{source,id}')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('knowledge-apply:'||p_location_id::text||':'||v_source_id::text,0));
 if run.result is null or run.stale_at_completion is distinct from false or p_expected_version<>(run.snapshot#>>'{source,version}')::bigint
  or not studio.studio_knowledge_snapshot_current(p_location_id,run.snapshot) then raise exception 'Source changed; keep historical proposals and extract current text' using errcode='40001'; end if;
 perform studio.studio_validate_text_run_result('knowledge_extract',run.result,run.snapshot);
 if exists(select 1 from jsonb_array_elements_text(p_finding_indexes) x where x::integer>=jsonb_array_length(run.result->'findings')) then raise exception 'Unknown proposed finding' using errcode='22023'; end if;
 at_iso:=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 insert into studio.studio_knowledge_sources(location_id,id,payload,total_units,covered_units)
  values(p_location_id,v_source_id,jsonb_build_object('id',v_source_id,'title',run.snapshot#>>'{source,title}','url',run.snapshot#>'{source,url}',
   'origin','hosted_extraction','coverage_origin','extraction_ranges','created_at',at_iso),(run.snapshot#>>'{coverage,totalUnits}')::integer,0) on conflict(location_id,id) do nothing;
 for idx in select x::integer from jsonb_array_elements_text(p_finding_indexes) x order by x::integer loop
  select * into mapping from studio.studio_knowledge_extraction_findings where location_id=p_location_id and review_id=run.id and finding_index=idx;
  if found then
   result:=result||jsonb_build_array(jsonb_build_object('findingIndex',idx,'insightId',mapping.insight_id,'reused',mapping.reused));continue;
  end if;
  finding:=run.result->'findings'->idx;
  select u into unit from jsonb_array_elements(run.snapshot->'units') u where u->>'id'=finding->>'unitId';
  select i.id into insight from studio.studio_knowledge_insights i where i.location_id=p_location_id and i.source_id=v_source_id
   and i.statement=finding->>'statement' and i.payload->>'kind'=finding->>'kind' order by i.id limit 1;
  is_reused:=found;
  if not is_reused then
   insight:=gen_random_uuid();evidence_id:=gen_random_uuid();
   insert into studio.studio_knowledge_insights(location_id,id,source_id,topic_id,status,statement,payload)
    values(p_location_id,insight,v_source_id,null,'pending',finding->>'statement',jsonb_build_object('id',insight,'kind',finding->>'kind',
     'suggested_topic',finding->>'suggestedTopic','origin','hosted_extraction','extraction_id',run.id,'finding_index',idx,'created_at',at_iso));
   quote_offset:=strpos(unit->>'text',finding->>'quote')-1;
   citation:=jsonb_build_object('quote',finding->>'quote','source_url',run.snapshot#>'{source,url}','origin','hosted_extraction','extraction_id',run.id,
    'source_version',p_expected_version,'input_mode',run.snapshot->>'mode','input_id',run.snapshot->>'inputId','unit_id',unit->>'id','unit_index',unit->'unitIndex',
    'unit_char_start',quote_offset,'unit_char_end',quote_offset+char_length(finding->>'quote'),
    'char_start',case when unit->'startChar'<>'null'::jsonb then (unit->>'startChar')::integer+quote_offset else null end,
    'char_end',case when unit->'startChar'<>'null'::jsonb then (unit->>'startChar')::integer+quote_offset+char_length(finding->>'quote') else null end,
    'start_sec',unit->'startSeconds','end_sec',unit->'endSeconds','timing_precision','unit');
   insert into studio.studio_knowledge_evidence(location_id,id,insight_id,source_id,payload) values(p_location_id,evidence_id,insight,v_source_id,citation);
   insert into studio.studio_knowledge_reviews(location_id,id,insight_id,payload) values(p_location_id,gen_random_uuid(),insight,jsonb_build_object(
    'action','extracted','previous_status',null,'new_status','pending','at',at_iso,'actor_app',p_actor_app,'actor_clerk_user_id',p_clerk_user_id,
    'version',1,'origin','hosted_extraction','extraction_id',run.id));
  end if;
  insert into studio.studio_knowledge_extraction_findings(location_id,review_id,finding_index,insight_id,reused) values(p_location_id,run.id,idx,insight,is_reused);
  result:=result||jsonb_build_array(jsonb_build_object('findingIndex',idx,'insightId',insight,'reused',is_reused));
 end loop;
 result:=jsonb_build_object('reviewId',run.id,'findings',result);
 insert into studio.studio_knowledge_extraction_applications(location_id,review_id,request_id,actor_app,actor_clerk_user_id,request,result)
  values(p_location_id,run.id,p_request_id,p_actor_app,p_clerk_user_id,request,result);
 return result;
end; $_$;

--
-- Name: studio_apply_script_brief(text, text, text, uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_apply_script_brief(p_location_id text, p_actor_app text, p_clerk_user_id text, p_review_id uuid, p_request_id uuid, p_expected_version bigint, p_confirm_replace boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run studio.studio_idea_reviews%rowtype; application studio.studio_script_brief_applications%rowtype;
  r studio.studio_records%rowtype; v_request jsonb; v_result jsonb; item jsonb;
begin
  perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
  if p_review_id is null or p_request_id is null or p_expected_version is null or p_expected_version<1 or p_confirm_replace is distinct from true then
    raise exception 'Explicit script replacement confirmation required' using errcode='22023'; end if;
  v_request := jsonb_build_object('reviewId',p_review_id,'version',p_expected_version,'confirm',p_confirm_replace,'app',p_actor_app,'actor',p_clerk_user_id);
  select * into run from studio.studio_idea_reviews where id=p_review_id and location_id=p_location_id and workflow='script_brief' for update;
  if not found then raise exception 'Script brief not found' using errcode='22023'; end if;
  select * into application from studio.studio_script_brief_applications where location_id=p_location_id and request_id=p_request_id;
  if found then
    if application.request is distinct from v_request then raise exception 'Application request already used' using errcode='23505'; end if;
    return application.result;
  end if;
  if exists(select 1 from studio.studio_script_brief_applications where review_id=run.id) then
    raise exception 'This brief was already applied' using errcode='40001'; end if;
  if run.result is null or run.stale_at_completion is distinct from false or run.prompt_version<>'studio.script-brief.v1'
    or jsonb_array_length(run.snapshot->'ideas')<>1 then raise exception 'A current completed brief is required' using errcode='40001'; end if;
  perform studio.studio_validate_text_run_result('script_brief',run.result,run.snapshot);
  -- Lock every input in UUID order; any changed/deleted source blocks application.
  perform 1 from studio.studio_records rec where rec.location_id=p_location_id and rec.id in
    (select (i->>'id')::uuid from jsonb_array_elements(run.snapshot->'ideas') i union
     select (s->>'id')::uuid from jsonb_array_elements(run.snapshot->'ideas') i,jsonb_array_elements(i->'sources') s) order by rec.id for update;
  for item in select i from jsonb_array_elements(run.snapshot->'ideas') i union all
    select s from jsonb_array_elements(run.snapshot->'ideas') i,jsonb_array_elements(i->'sources') s loop
    if not exists(select 1 from studio.studio_records rec where rec.location_id=p_location_id and rec.id=(item->>'id')::uuid
      and rec.version=(item->>'version')::bigint) then raise exception 'An input changed; keep this historical draft and generate a fresh brief before applying' using errcode='40001'; end if;
  end loop;
  select * into r from studio.studio_records where location_id=p_location_id and id=(run.snapshot->'ideas'->0->>'id')::uuid;
  if r.kind<>'content' or r.archived or r.version<>p_expected_version or r.version<>(run.snapshot->'ideas'->0->>'version')::bigint
    or r.payload->>'stage' is distinct from 'idea' then raise exception 'Content changed; reload before applying' using errcode='40001'; end if;
  update studio.studio_records set payload=payload||jsonb_build_object('script',run.result->>'script','stage','script','approved',false),
    version=version+1,updated_at=clock_timestamp() where location_id=p_location_id and id=r.id;
  v_result := jsonb_build_object('reviewId',run.id,'recordId',r.id,'recordVersion',r.version+1);
  insert into studio.studio_script_brief_applications(location_id,review_id,record_id,request_id,actor_app,actor_clerk_user_id,
    previous_version,record_version,previous_script,previous_stage,previous_approved,request,result)
    values(p_location_id,run.id,r.id,p_request_id,p_actor_app,p_clerk_user_id,r.version,r.version+1,r.payload->'script',r.payload->'stage',r.payload->'approved',v_request,v_result);
  return v_result;
end; $$;

--
-- Name: studio_begin_idea_review_attempt(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_begin_idea_review_attempt(p_location_id text, p_review_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform studio.studio_lock_idea_review_lease(p_location_id,p_review_id,p_job_id,p_worker_id,p_lease_token);
  return studio.studio_begin_text_run_attempt(p_location_id,p_review_id,p_job_id,p_worker_id,p_lease_token);
end; $$;

--
-- Name: studio_begin_text_run_attempt(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_begin_text_run_attempt(p_location_id text, p_review_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e studio.studio_schedule_executions%rowtype; r studio.studio_schedule_recurring%rowtype; s studio.studio_schedules%rowtype; fresh jsonb;
  j studio.studio_jobs%rowtype; a uuid; u uuid; billing text; v_workflow text;
begin
  select * into e from studio.studio_schedule_executions where location_id=p_location_id and job_id=p_job_id and activation_token is not null;
  if found then
    begin
      perform studio.studio_lock_location_member(p_location_id,e.actor_app,e.created_by_clerk_user_id);
    exception when insufficient_privilege then return '{"outcome":"schedule_inactive"}'; end;
    select * into s from studio.studio_schedules where location_id=p_location_id and id=e.schedule_id for share;
    select * into r from studio.studio_schedule_recurring where location_id=p_location_id and schedule_id=e.schedule_id for share;
    if not r.enabled or r.activation_token is distinct from e.activation_token or r.schedule_version<>s.version then return '{"outcome":"schedule_inactive"}'; end if;
    begin fresh:=studio.studio_build_selected_text_snapshot(p_location_id,r.selection,s.focus,e.workflow);
      if fresh is distinct from r.snapshot then return '{"outcome":"schedule_inactive"}'; end if;
    exception when serialization_failure or invalid_parameter_value then return '{"outcome":"schedule_inactive"}'; end;
  end if;
  j := studio.studio_lock_text_run_lease(p_location_id,p_review_id,p_job_id,p_worker_id,p_lease_token);
  if exists(select 1 from studio.studio_idea_reviews where id=p_review_id and result is not null) then return '{"outcome":"saved"}'; end if;
  select billing_outcome into billing from studio.studio_ai_attempts where idea_review_id=p_review_id and status<>'rejected' and not replacement_authorized;
  if found then return jsonb_build_object('outcome',case when billing is null then 'uncertain' else 'reconciled' end); end if;
  select workflow into v_workflow from studio.studio_idea_reviews where id=p_review_id;
  u := studio.studio_reserve_ai_spend(p_location_id,'openai',v_workflow,10000);
  if u is null then return '{"outcome":"budget_exhausted"}'; end if;
  insert into studio.studio_ai_attempts(location_id,job_id,lease_token,job_attempt,worker_id,usage_id,status,operation,idea_review_id,model)
    values(p_location_id,p_job_id,p_lease_token,j.attempts,p_worker_id,u,'started',v_workflow,p_review_id,'gpt-6-luna') returning id into a;
  return jsonb_build_object('outcome','started','attempt_id',a);
end; $$;

--
-- Name: studio_begin_transcription_attempt(text, uuid, uuid, text, uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_begin_transcription_attempt(p_location_id text, p_upload_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_chunk_index integer, p_duration_seconds numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j studio.studio_jobs%rowtype; a uuid; u uuid; v_billing text;
begin
  j := studio.studio_lock_transcription_lease(p_location_id,p_upload_id,p_job_id,p_worker_id,p_lease_token);
  if p_chunk_index is null or p_chunk_index not between 0 and 35 or p_duration_seconds is null
    or p_duration_seconds <= 0 or p_duration_seconds > 600 then raise exception 'Invalid chunk' using errcode='22023'; end if;
  if exists(select 1 from studio.studio_transcript_chunks where upload_id=p_upload_id and chunk_index=p_chunk_index) then
    return '{"outcome":"saved"}'::jsonb;
  end if;
  select billing_outcome into v_billing from studio.studio_transcription_attempts where upload_id=p_upload_id
    and chunk_index=p_chunk_index and status <> 'rejected' and not replacement_authorized;
  if found then
    return pg_catalog.jsonb_build_object('outcome',case when v_billing is null then 'uncertain' else 'reconciled' end);
  end if;
  -- Retains the original whisper-1 estimate: 100 micro-USD per audio second.
  u := studio.studio_reserve_ai_spend(p_location_id,'openai','transcribe_upload',pg_catalog.ceil(p_duration_seconds * 100)::bigint);
  if u is null then return '{"outcome":"budget_exhausted"}'::jsonb; end if;
  insert into studio.studio_transcription_attempts(location_id,upload_id,job_id,lease_token,job_attempt,worker_id,chunk_index,duration_seconds,usage_id,status)
    values(p_location_id,p_upload_id,p_job_id,p_lease_token,j.attempts,p_worker_id,p_chunk_index,p_duration_seconds,u,'started') returning id into a;
  return pg_catalog.jsonb_build_object('outcome','started','attempt_id',a);
end;
$$;

--
-- Name: studio_begin_youtube_discovery(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_begin_youtube_discovery(p_location text, p_run uuid, p_job uuid, p_worker text, p_lease uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run studio.studio_youtube_schedule_runs%rowtype; g studio.platform_youtube_schedule_authorizations%rowtype; s studio.studio_schedules%rowtype;
begin
 run:=studio.studio_lock_youtube_run(p_location,p_run,p_job,p_worker,p_lease);
 if run.result is not null then return jsonb_build_object('outcome','saved','result',run.result); end if;
 if run.slot_lease_token is distinct from p_lease then
  if not studio.studio_youtube_request_slot(p_location,run.actor_app,run.created_by_clerk_user_id) then return '{"outcome":"quota"}'; end if;
  update studio.studio_youtube_schedule_runs set slot_lease_token=p_lease where id=p_run;
 end if;
 g:=studio.studio_lock_youtube_source(p_location,p_run);
 select * into s from studio.studio_schedules where location_id=p_location and id=run.schedule_id;
 return jsonb_build_object('outcome','ready','app',g.app,'userId',g.clerk_user_id,'connectionVersion',g.connection_version,
 'source',g.source_mode,'channelId',g.channel_id,'query',s.focus);
end; $$;

--
-- Name: studio_bind_knowledge_media(text, text, text, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_bind_knowledge_media(p_location_id text, p_owner_clerk_user_id text, p_ref_kind text, p_ref_id uuid, p_sha256 text, p_byte_size bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_link studio.studio_knowledge_media_links%rowtype;
  v_media_id uuid;
begin
  if p_ref_kind is null or p_ref_kind not in ('evidence','unit') or p_ref_id is null
    or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' or p_byte_size is null or p_byte_size < 0 then
    raise exception 'Invalid knowledge media binding' using errcode = '22023';
  end if;
  perform studio.studio_lock_legacy_media_owner(p_location_id, p_owner_clerk_user_id);
  select * into v_link from studio.studio_knowledge_media_links
    where location_id=p_location_id and ref_kind=p_ref_kind and ref_id=p_ref_id for update;
  if not found or v_link.sha256 <> p_sha256 or v_link.byte_size <> p_byte_size then
    raise exception 'Knowledge media binding does not match its reservation' using errcode = '22023';
  end if;
  if v_link.status = 'verified' then
    return pg_catalog.jsonb_build_object('refKind',p_ref_kind,'refId',p_ref_id,'mediaObjectId',v_link.media_object_id,
      'bucketId',v_link.bucket_id,'objectKey',v_link.object_key,'replayed',true);
  end if;
  if not studio.studio_knowledge_frame_matches(p_location_id, p_ref_kind, p_ref_id, v_link.frame_file) then
    raise exception 'Imported knowledge row no longer matches its reservation' using errcode = '22023';
  end if;
  insert into studio.studio_media_objects(location_id,storage_provider,bucket_id,object_key,original_filename,content_type,byte_size,sha256,created_by_clerk_user_id)
    values(p_location_id,'cloudflare_r2',v_link.bucket_id,v_link.object_key,v_link.frame_file,v_link.content_type,p_byte_size,p_sha256,p_owner_clerk_user_id)
    returning id into v_media_id;
  update studio.studio_knowledge_media_links set status='verified',media_object_id=v_media_id,
    verified_by_clerk_user_id=p_owner_clerk_user_id,verified_at=pg_catalog.now()
    where location_id=p_location_id and ref_kind=p_ref_kind and ref_id=p_ref_id;
  return pg_catalog.jsonb_build_object('refKind',p_ref_kind,'refId',p_ref_id,'mediaObjectId',v_media_id,
    'bucketId',v_link.bucket_id,'objectKey',v_link.object_key,'replayed',false);
end;
$_$;

--
-- Name: studio_bind_legacy_media(text, text, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_bind_legacy_media(p_location_id text, p_owner_clerk_user_id text, p_file_id uuid, p_sha256 text, p_byte_size bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_transfer studio.studio_legacy_media_transfers%rowtype;
  v_legacy studio.studio_legacy_files%rowtype;
  v_media_id uuid;
begin
  if p_file_id is null or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' or p_byte_size is null or p_byte_size < 0 then
    raise exception 'Invalid media binding' using errcode = '22023';
  end if;
  perform studio.studio_lock_legacy_media_owner(p_location_id, p_owner_clerk_user_id);
  select * into v_transfer from studio.studio_legacy_media_transfers
    where location_id=p_location_id and file_id=p_file_id for update;
  if not found or v_transfer.sha256 <> p_sha256 or v_transfer.byte_size <> p_byte_size then
    raise exception 'Media binding does not match its reservation' using errcode = '22023';
  end if;
  if v_transfer.status = 'verified' then
    return pg_catalog.jsonb_build_object('fileId',p_file_id,'mediaObjectId',v_transfer.media_object_id,'bucketId',v_transfer.bucket_id,'objectKey',v_transfer.object_key,'replayed',true);
  end if;
  select * into v_legacy from studio.studio_legacy_files where location_id=p_location_id and id=p_file_id for update;
  if not found or v_legacy.media_object_id is not null or v_legacy.record_id <> v_transfer.record_id
    or v_legacy.payload->'size' is distinct from pg_catalog.to_jsonb(p_byte_size) then
    raise exception 'Original attachment no longer matches its reservation' using errcode = '22023';
  end if;
  insert into studio.studio_media_objects(location_id,storage_provider,bucket_id,object_key,original_filename,content_type,byte_size,sha256,created_by_clerk_user_id)
    values(p_location_id,'cloudflare_r2',v_transfer.bucket_id,v_transfer.object_key,v_legacy.payload->>'name',v_legacy.payload->>'type',p_byte_size,p_sha256,p_owner_clerk_user_id)
    returning id into v_media_id;
  update studio.studio_legacy_files set media_object_id=v_media_id where location_id=p_location_id and id=p_file_id;
  update studio.studio_legacy_media_transfers set status='verified',media_object_id=v_media_id,
    verified_by_clerk_user_id=p_owner_clerk_user_id,verified_at=pg_catalog.now()
    where location_id=p_location_id and file_id=p_file_id;
  return pg_catalog.jsonb_build_object('fileId',p_file_id,'mediaObjectId',v_media_id,'bucketId',v_transfer.bucket_id,'objectKey',v_transfer.object_key,'replayed',false);
end;
$_$;

--
-- Name: studio_build_knowledge_snapshot(text, uuid, bigint, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_build_knowledge_snapshot(p_location_id text, p_source_id uuid, p_expected_version bigint, p_mode text, p_input_id text, p_start_unit integer, p_unit_count integer, p_focus text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r studio.studio_records%rowtype; full_text text; total integer; text_length integer; units jsonb; fingerprint text; selected integer;
begin
 if p_mode is null or p_mode not in ('record_text','source_units','upload_transcript') or p_input_id is null or length(p_input_id) not between 1 and 200
  or p_start_unit is null or p_start_unit not between 0 and 1000000 or p_unit_count is null or p_unit_count not between 1 and 8
  or p_focus is null or length(p_focus)>300 or p_expected_version is null or p_expected_version<1 then raise exception 'Invalid extraction range' using errcode='22023'; end if;
 select * into r from studio.studio_records where location_id=p_location_id and id=p_source_id for share;
 if not found or r.version<>p_expected_version or r.archived or r.kind not in ('reference','content') then raise exception 'Source changed or unavailable' using errcode='40001'; end if;
 if char_length(r.source_url)>2000 then raise exception 'Source URL exceeds bounds' using errcode='22023'; end if;
 if p_mode='source_units' then
  perform 1 from studio.studio_knowledge_source_units where location_id=p_location_id and source_id=p_source_id and transcription_id=p_input_id
    and unit_index>=p_start_unit and unit_index<p_start_unit+p_unit_count order by unit_index,id for share;
  select coalesce(max(unit_index)+1,0) into total from studio.studio_knowledge_source_units where location_id=p_location_id and source_id=p_source_id and transcription_id=p_input_id;
  if exists(select 1 from studio.studio_knowledge_source_units where location_id=p_location_id and source_id=p_source_id and transcription_id=p_input_id
    and unit_index>=p_start_unit and unit_index<p_start_unit+p_unit_count and (jsonb_typeof(payload#>'{unit,text}') is distinct from 'string' or length(payload#>>'{unit,text}')>16000)) then
    raise exception 'Selected source units require shorter saved text inputs' using errcode='22023'; end if;
  select jsonb_agg(jsonb_build_object('id',id::text,'unitIndex',unit_index,'text',payload#>>'{unit,text}','startChar',null,'endChar',null,
    'startSeconds',case when jsonb_typeof(payload#>'{unit,start}')='number' then payload#>'{unit,start}' else null end,
    'endSeconds',case when jsonb_typeof(payload#>'{unit,end}')='number' then payload#>'{unit,end}' else null end) order by unit_index,id),
    encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'sidecar',sidecar_id,'index',unit_index,'payload',payload) order by unit_index,id)::text,''),'UTF8')),'hex'),count(*)
    into units,fingerprint,selected from studio.studio_knowledge_source_units where location_id=p_location_id and source_id=p_source_id and transcription_id=p_input_id
      and unit_index>=p_start_unit and unit_index<p_start_unit+p_unit_count;
 else
  if p_mode='record_text' then
    if p_input_id not in ('transcript','notes','script') or jsonb_typeof(r.payload->p_input_id) is distinct from 'string' then raise exception 'Choose saved text' using errcode='22023'; end if;
    full_text := r.payload->>p_input_id;
  else
    select t.text into full_text from studio.studio_transcripts t join studio.studio_uploads u on u.id=t.upload_id and u.location_id=t.location_id
      where t.location_id=p_location_id and t.upload_id=p_input_id::uuid and u.record_id=p_source_id and u.status='uploaded' for share of t,u;
    if not found then raise exception 'Completed upload transcript not found for source' using errcode='22023'; end if;
  end if;
  text_length := char_length(full_text); total := ceil(text_length::numeric/2000)::integer;
  select jsonb_agg(jsonb_build_object('id',p_mode||':'||p_input_id||':'||i::text,'unitIndex',i,'text',substring(full_text from i*2000+1 for 2000),
    'startChar',i*2000,'endChar',least(text_length,(i+1)*2000),'startSeconds',null,'endSeconds',null) order by i),count(*) into units,selected
    from generate_series(p_start_unit,least(total-1,p_start_unit+p_unit_count-1)) i;
  fingerprint := encode(sha256(convert_to(full_text,'UTF8')),'hex');
 end if;
 if total<=p_start_unit or selected<>least(p_unit_count,total-p_start_unit) or units is null or not exists
  (select 1 from jsonb_array_elements(units) u where u->>'text' !~ '^[[:space:]]*$') then raise exception 'Select a range containing saved text' using errcode='22023'; end if;
 return jsonb_build_object('source',jsonb_build_object('id',r.id,'version',r.version,'title',left(r.title,180),'url',r.source_url),
  'mode',p_mode,'inputId',p_input_id,'startUnit',p_start_unit,'unitCount',p_unit_count,'focus',p_focus,'fingerprint',fingerprint,
  'coverage',jsonb_build_object('totalUnits',total,'selectedUnits',selected,'totalCharacters',text_length),'units',units);
end; $_$;

--
-- Name: studio_build_selected_text_snapshot(text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_build_selected_text_snapshot(p_location_id text, p_selection jsonb, p_focus text, p_workflow text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare ids uuid[]; v_ideas jsonb; v_snapshot jsonb;
begin
  if p_workflow is null or p_workflow not in ('idea_review','script_brief') or p_focus is null or char_length(p_focus)>300
    or p_selection is null or jsonb_typeof(p_selection)<>'array' or jsonb_array_length(p_selection) not between 1 and 5
    or (p_workflow='script_brief' and jsonb_array_length(p_selection)<>1) then raise exception 'Invalid recurring inputs' using errcode='22023'; end if;
  select array_agg((x->>'id')::uuid order by x->>'id') into ids from jsonb_array_elements(p_selection) x;
  if (select count(distinct id) from unnest(ids) id) <> jsonb_array_length(p_selection)
    or exists(select 1 from jsonb_array_elements(p_selection) x where x->>'version' is null or (x->>'version') !~ '^[1-9][0-9]{0,14}$') then
    raise exception 'Invalid idea selection' using errcode='22023'; end if;
  -- All selected records + their linked sources are locked in UUID order.
  -- Link edits increment/lock their source record version, so stale selection
  -- versions fail below rather than mixing snapshots across an edit.
  perform 1 from studio.studio_records r where r.location_id=p_location_id and (r.id=any(ids) or r.id in
    (select target_id from studio.studio_record_links where location_id=p_location_id and source_id=any(ids))) order by r.id for share;
  if exists(select 1 from jsonb_array_elements(p_selection) x where not exists(select 1 from studio.studio_records r
    where r.location_id=p_location_id and r.id=(x->>'id')::uuid and r.version=(x->>'version')::bigint
      and r.kind='content' and not r.archived and r.payload->>'stage'='idea')) then
    raise exception 'An idea changed or is unavailable; reload' using errcode='40001'; end if;
  if exists(select 1 from studio.studio_record_links where location_id=p_location_id and source_id=any(ids) group by source_id having count(*)>3) then
    raise exception 'Select ideas with at most three linked records for this bounded review' using errcode='22023'; end if;
  if exists(select 1 from studio.studio_record_links l join studio.studio_records s on s.location_id=l.location_id and s.id=l.target_id
    where l.location_id=p_location_id and l.source_id=any(ids) and char_length(s.source_url)>2000) then
    raise exception 'A linked source URL exceeds the review bound' using errcode='22023'; end if;
  select jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'title',left(r.title,180),
    'summary',left(coalesce(r.summary,''),700),'notes',left(coalesce(r.payload->>'notes',''),1000),
    'excerpted',char_length(r.title)>180 or char_length(coalesce(r.summary,''))>700 or char_length(coalesce(r.payload->>'notes',''))>1000,
    'sources',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'version',s.version,'title',left(s.title,180),
      'url',s.source_url,'excerpt',left(coalesce(nullif(s.payload->>'transcript',''),nullif(s.payload->>'notes',''),s.summary,''),600),
      'excerpted',char_length(s.title)>180 or char_length(coalesce(nullif(s.payload->>'transcript',''),nullif(s.payload->>'notes',''),s.summary,''))>600) order by s.id)
      from studio.studio_record_links l join studio.studio_records s on s.location_id=l.location_id and s.id=l.target_id
      where l.location_id=p_location_id and l.source_id=r.id),'[]'::jsonb)) order by r.id) into v_ideas
    from studio.studio_records r where r.location_id=p_location_id and r.id=any(ids);
  v_snapshot := jsonb_build_object('focus',p_focus,'ideas',v_ideas);
  if octet_length(v_snapshot::text)>24000 then raise exception 'Selected research excerpts exceed review size; select fewer ideas' using errcode='22023'; end if;
  if p_workflow='script_brief' and not exists(select 1 from jsonb_array_elements(v_snapshot->'ideas'->0->'sources') s where btrim(s->>'excerpt')<>'') then
    raise exception 'Save supporting research text and link it to this idea before drafting' using errcode='22023'; end if;
  return v_snapshot;
end; $_$;

--
-- Name: studio_change_record_link(text, uuid, uuid, text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_change_record_link(p_location_id text, p_source_id uuid, p_target_id uuid, p_action text, p_expected_version bigint, p_actor_app text, p_clerk_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_app text;
  v_record studio.studio_records%rowtype;
  v_changed boolean;
  v_ids jsonb;
begin
  if p_location_id is null or p_source_id is null or p_target_id is null or p_source_id=p_target_id
    or p_action is null or p_action not in ('add','remove')
    or p_expected_version is null or p_expected_version < 1
    or p_actor_app is null or p_actor_app not in ('estio','substo')
    or p_clerk_user_id is null or btrim(p_clerk_user_id)='' then
    raise exception 'Invalid record link change' using errcode = '22023';
  end if;
  select app into v_app from studio.studio_locations where location_id=p_location_id;
  if v_app is null or v_app <> p_actor_app then raise exception 'Record link location denied' using errcode = '42501'; end if;
  -- The application checks Estio's separate Business authority and impersonation.
  if v_app='substo' then
    perform 1 from studio.studio_location_members where location_id=p_location_id and location_app='substo'
      and clerk_user_id=p_clerk_user_id for share;
    if not found then raise exception 'Record link membership denied' using errcode = '42501'; end if;
  end if;
  -- NO KEY UPDATE serializes field/link edits while allowing FK key-share locks
  -- for independent/reverse link operations on other records.
  select * into v_record from studio.studio_records where location_id=p_location_id and id=p_source_id for no key update;
  if not found then raise exception 'Record not found' using errcode = 'P0002'; end if;
  if v_record.version <> p_expected_version then raise exception 'Record changed; reload before linking' using errcode = '40001'; end if;
  perform 1 from studio.studio_records where location_id=p_location_id and id=p_target_id;
  if not found then raise exception 'Link target not found in location' using errcode = 'P0002'; end if;

  if p_action='add' then
    if not exists(select 1 from studio.studio_record_links where location_id=p_location_id and source_id=p_source_id and target_id=p_target_id)
      and (select count(*) from studio.studio_record_links where location_id=p_location_id and source_id=p_source_id) >= 100 then
      raise exception 'At most 100 outgoing links can be added' using errcode = '22023';
    end if;
    insert into studio.studio_record_links(location_id,source_id,target_id) values(p_location_id,p_source_id,p_target_id) on conflict do nothing;
    v_changed := found;
  else
    delete from studio.studio_record_links where location_id=p_location_id and source_id=p_source_id and target_id=p_target_id;
    v_changed := found;
  end if;
  if v_changed then
    select coalesce(jsonb_agg(target_id::text order by target_id),'[]'::jsonb) into v_ids
      from studio.studio_record_links where location_id=p_location_id and source_id=p_source_id;
    update studio.studio_records set payload=jsonb_set(payload,'{linkedIds}',v_ids),version=version+1,updated_at=clock_timestamp()
      where location_id=p_location_id and id=p_source_id returning * into v_record;
    insert into studio.studio_record_link_events(location_id,source_id,target_id,action,record_version,actor_app,actor_clerk_user_id)
      values(p_location_id,p_source_id,p_target_id,p_action,v_record.version,p_actor_app,p_clerk_user_id);
  end if;
  return jsonb_build_object('sourceId',p_source_id,'targetId',p_target_id,'version',v_record.version,'changed',v_changed);
end;
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: studio_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE studio.studio_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    location_id text NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb,
    idempotency_key text,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    run_after timestamp with time zone DEFAULT now() NOT NULL,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    created_by_clerk_user_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    lease_token uuid,
    execution_target text DEFAULT 'hosted'::text NOT NULL,
    device_id uuid,
    CONSTRAINT studio_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT studio_jobs_check CHECK (((status = 'running'::text) = ((lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT studio_jobs_check1 CHECK (((status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'cancelled'::text])) = (finished_at IS NOT NULL))),
    CONSTRAINT studio_jobs_execution_scope CHECK (((execution_target = 'device'::text) = (device_id IS NOT NULL))),
    CONSTRAINT studio_jobs_execution_target_check CHECK ((execution_target = ANY (ARRAY['hosted'::text, 'device'::text]))),
    CONSTRAINT studio_jobs_idempotency_key_check CHECK (((idempotency_key IS NULL) OR (idempotency_key ~ '^[A-Za-z0-9:._-]{1,200}$'::text))),
    CONSTRAINT studio_jobs_kind_check CHECK ((kind ~ '^[a-z][a-z0-9_.-]{0,63}$'::text)),
    CONSTRAINT studio_jobs_last_error_code_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z][a-z0-9_]{0,63}$'::text))),
    CONSTRAINT studio_jobs_last_error_message_check CHECK (((last_error_message IS NULL) OR (char_length(last_error_message) <= 500))),
    CONSTRAINT studio_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT studio_jobs_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 65536))),
    CONSTRAINT studio_jobs_result_check CHECK (((result IS NULL) OR ((jsonb_typeof(result) = 'object'::text) AND (octet_length((result)::text) <= 65536)))),
    CONSTRAINT studio_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])))
);

--
-- Name: studio_claim_device_jobs(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_claim_device_jobs(p_device_id uuid, p_location_id text, p_worker_id text, p_limit integer, p_lease_seconds integer) RETURNS SETOF studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_job studio.studio_jobs%rowtype;
begin
  if p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9:._-]{1,100}$' or p_limit is null or p_limit not between 1 and 50
    or p_lease_seconds is null or p_lease_seconds not between 10 and 3600 then
    raise exception 'Invalid claim' using errcode = '22023';
  end if;
  perform 1 from studio.studio_devices where id=p_device_id and location_id=p_location_id and revoked_at is null and not paused;
  if not found then return; end if;
  for v_job in select * from studio.studio_jobs where device_id=p_device_id and location_id=p_location_id and kind='studio.diagnostic' and status='running' and lease_expires_at < pg_catalog.clock_timestamp()
      order by lease_expires_at limit 100 for update skip locked loop
    insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id,error_code)
      values(v_job.id,v_job.location_id,v_job.attempts,'lease_expired',v_job.lease_owner,'worker_lease_expired');
    if v_job.attempts >= v_job.max_attempts then
      update studio.studio_jobs set status='failed',lease_owner=null,lease_expires_at=null,last_error_code='worker_lease_expired',
        last_error_message='The worker stopped before finishing this job.',finished_at=pg_catalog.clock_timestamp(),updated_at=pg_catalog.clock_timestamp() where id=v_job.id;
      insert into studio.studio_job_events(job_id,location_id,attempt,event,error_code) values(v_job.id,v_job.location_id,v_job.attempts,'failed','worker_lease_expired');
    else
      update studio.studio_jobs set status='queued',lease_owner=null,lease_expires_at=null,last_error_code='worker_lease_expired',
        last_error_message='The worker stopped before finishing this job; it will be retried.',run_after=pg_catalog.clock_timestamp(),updated_at=pg_catalog.clock_timestamp() where id=v_job.id;
    end if;
  end loop;
  return query
    with due as (
      select id from studio.studio_jobs where device_id=p_device_id and location_id=p_location_id and kind='studio.diagnostic' and status='queued' and run_after <= pg_catalog.clock_timestamp()
        order by run_after, created_at limit p_limit for update skip locked
    ), claimed as (
      update studio.studio_jobs j set status='running', attempts=j.attempts+1, lease_owner=p_worker_id, lease_token=gen_random_uuid(),
        lease_expires_at=pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => p_lease_seconds), updated_at=pg_catalog.clock_timestamp()
      from due where j.id=due.id returning j.*
    ), logged as (
      insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id)
        select id,location_id,attempts,'started',p_worker_id from claimed
    )
    select * from claimed;
end;
$_$;

--
-- Name: studio_claim_jobs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_claim_jobs(p_worker_id text, p_limit integer, p_lease_seconds integer) RETURNS SETOF studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_job studio.studio_jobs%rowtype;
begin
  if p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9:._-]{1,100}$' or p_limit is null or p_limit not between 1 and 50
    or p_lease_seconds is null or p_lease_seconds not between 10 and 3600 then
    raise exception 'Invalid claim' using errcode = '22023';
  end if;
  perform studio.studio_recover_transcription_attempts();
  for v_job in select * from studio.studio_jobs where status='running' and lease_expires_at < pg_catalog.clock_timestamp()
      order by lease_expires_at limit 100 for update skip locked loop
    insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id,error_code)
      values(v_job.id,v_job.location_id,v_job.attempts,'lease_expired',v_job.lease_owner,'worker_lease_expired');
    if v_job.attempts >= v_job.max_attempts then
      update studio.studio_jobs set status='failed',lease_owner=null,lease_expires_at=null,last_error_code='worker_lease_expired',
        last_error_message='The worker stopped before finishing this job.',finished_at=pg_catalog.clock_timestamp(),updated_at=pg_catalog.clock_timestamp() where id=v_job.id;
      insert into studio.studio_job_events(job_id,location_id,attempt,event,error_code) values(v_job.id,v_job.location_id,v_job.attempts,'failed','worker_lease_expired');
    else
      update studio.studio_jobs set status='queued',lease_owner=null,lease_expires_at=null,last_error_code='worker_lease_expired',
        last_error_message='The worker stopped before finishing this job; it will be retried.',run_after=pg_catalog.clock_timestamp(),updated_at=pg_catalog.clock_timestamp() where id=v_job.id;
    end if;
  end loop;
  return query
    with due as (
      select id from studio.studio_jobs where execution_target='hosted' and status='queued' and run_after <= pg_catalog.clock_timestamp()
        order by run_after, created_at limit p_limit for update skip locked
    ), claimed as (
      update studio.studio_jobs j set status='running', attempts=j.attempts+1, lease_owner=p_worker_id, lease_token=gen_random_uuid(),
        lease_expires_at=pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => p_lease_seconds), updated_at=pg_catalog.clock_timestamp()
      from due where j.id=due.id returning j.*
    ), logged as (
      insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id)
        select id,location_id,attempts,'started',p_worker_id from claimed
    )
    select * from claimed;
end;
$_$;

--
-- Name: studio_clear_ai_credential(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_clear_ai_credential(p_location_id text, p_actor_app text, p_clerk_user_id text, p_provider text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform studio.studio_lock_ai_manager(p_location_id, p_actor_app, p_clerk_user_id);
  delete from studio.studio_location_ai_credentials where location_id=p_location_id and provider=p_provider;
  return found;
end;
$$;

--
-- Name: studio_close_ai_attempt(text, uuid, text, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_close_ai_attempt(p_location_id text, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_attempt_id uuid, p_rejected boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j studio.studio_jobs%rowtype; a studio.studio_ai_attempts%rowtype;
begin
  select * into j from studio.studio_jobs where id=p_job_id for update;
  if j.id is null or j.location_id<>p_location_id or j.status<>'running' or j.lease_owner is distinct from p_worker_id
    or j.lease_token is distinct from p_lease_token or j.lease_expires_at<=clock_timestamp() then raise exception 'Current paid-job lease required' using errcode='40001'; end if;
  select * into a from studio.studio_ai_attempts where id=p_attempt_id and location_id=p_location_id and job_id=p_job_id and lease_token=p_lease_token for update;
  if a.id is null then raise exception 'Attempt missing' using errcode='22023'; end if;
  if a.status<>'started' then return; end if;
  if coalesce(p_rejected,false) then perform studio.studio_release_ai_spend(p_location_id,a.usage_id); end if;
  update studio.studio_ai_attempts set status=case when coalesce(p_rejected,false) then 'rejected' else 'uncertain' end,updated_at=clock_timestamp() where id=a.id;
end; $$;

--
-- Name: studio_close_transcription_attempt(text, uuid, uuid, text, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_close_transcription_attempt(p_location_id text, p_upload_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_attempt_id uuid, p_rejected boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform studio.studio_lock_transcription_lease(p_location_id,p_upload_id,p_job_id,p_worker_id,p_lease_token);
  if not exists(select 1 from studio.studio_transcription_attempts where id=p_attempt_id and upload_id=p_upload_id
    and location_id=p_location_id and job_id=p_job_id and lease_token=p_lease_token) then
    raise exception 'Upload attempt mismatch' using errcode='22023'; end if;
  perform studio.studio_close_ai_attempt(p_location_id,p_job_id,p_worker_id,p_lease_token,p_attempt_id,p_rejected);
end; $$;

--
-- Name: studio_complete_job(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_complete_job(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_result jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_job studio.studio_jobs%rowtype;
begin
  update studio.studio_jobs set status='succeeded', result=coalesce(p_result,'{}'::jsonb), lease_owner=null, lease_expires_at=null,
    last_error_code=null, last_error_message=null, finished_at=pg_catalog.clock_timestamp(), updated_at=pg_catalog.clock_timestamp()
    where id=p_job_id and status='running' and lease_owner=p_worker_id and lease_token=p_lease_token and lease_expires_at > pg_catalog.clock_timestamp() returning * into v_job;
  if v_job.id is null then return false; end if;
  insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id) values(v_job.id,v_job.location_id,v_job.attempts,'succeeded',p_worker_id);
  return true;
end;
$$;

--
-- Name: studio_uploads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE studio.studio_uploads (
    id uuid NOT NULL,
    location_id text NOT NULL,
    record_id uuid NOT NULL,
    original_filename text NOT NULL,
    content_type text NOT NULL,
    byte_size bigint NOT NULL,
    bucket_id text NOT NULL,
    object_key text NOT NULL,
    status text DEFAULT 'awaiting_upload'::text NOT NULL,
    media_object_id uuid,
    transcription_job_id uuid,
    created_by_clerk_user_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '01:00:00'::interval) NOT NULL,
    uploaded_at timestamp with time zone,
    CONSTRAINT studio_uploads_bucket_id_check CHECK ((bucket_id ~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$'::text)),
    CONSTRAINT studio_uploads_byte_size_check CHECK (((byte_size >= 1) AND (byte_size <= '5368709120'::bigint))),
    CONSTRAINT studio_uploads_check CHECK ((object_key = (((location_id || '/uploads/'::text) || (id)::text) || '/original'::text))),
    CONSTRAINT studio_uploads_check1 CHECK (((status = 'uploaded'::text) = ((media_object_id IS NOT NULL) AND (uploaded_at IS NOT NULL)))),
    CONSTRAINT studio_uploads_content_type_check CHECK ((content_type = ANY (ARRAY['video/mp4'::text, 'video/quicktime'::text, 'video/webm'::text, 'audio/mpeg'::text, 'audio/mp4'::text, 'audio/x-m4a'::text, 'audio/wav'::text, 'audio/x-wav'::text, 'audio/webm'::text, 'audio/ogg'::text, 'audio/aac'::text]))),
    CONSTRAINT studio_uploads_original_filename_check CHECK ((((char_length(original_filename) >= 1) AND (char_length(original_filename) <= 255)) AND (original_filename !~ '[[:cntrl:]/\\]'::text))),
    CONSTRAINT studio_uploads_status_check CHECK ((status = ANY (ARRAY['awaiting_upload'::text, 'uploaded'::text])))
);

--
-- Name: studio_complete_upload(text, text, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_complete_upload(p_location_id text, p_actor_app text, p_clerk_user_id text, p_upload_id uuid, p_observed_size bigint) RETURNS studio.studio_uploads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row studio.studio_uploads%rowtype;
  v_media uuid;
  v_job studio.studio_jobs%rowtype;
begin
  perform studio.studio_lock_location_member(p_location_id, p_actor_app, p_clerk_user_id);
  select * into v_row from studio.studio_uploads where id=p_upload_id and location_id=p_location_id for update;
  if not found then raise exception 'Upload not found' using errcode = '22023'; end if;
  if v_row.created_by_clerk_user_id <> p_clerk_user_id then raise exception 'Only the uploader can finish this upload' using errcode = '42501'; end if;
  if v_row.status = 'uploaded' then return v_row; end if;
  if pg_catalog.now() >= v_row.expires_at + interval '6 hours' then raise exception 'Upload expired' using errcode = '22023'; end if;
  if p_observed_size is distinct from v_row.byte_size then raise exception 'Stored object size does not match' using errcode = '22023'; end if;
  insert into studio.studio_media_objects(location_id,storage_provider,bucket_id,object_key,original_filename,content_type,byte_size,sha256,created_by_clerk_user_id)
    values(p_location_id,'cloudflare_r2',v_row.bucket_id,v_row.object_key,v_row.original_filename,v_row.content_type,v_row.byte_size,null,p_clerk_user_id)
    returning id into v_media;
  v_job := studio.studio_enqueue_job(p_location_id,'studio.transcribe_upload',pg_catalog.jsonb_build_object('uploadId',p_upload_id),
    'transcribe:' || p_upload_id::text, p_clerk_user_id, 5);
  update studio.studio_uploads set status='uploaded', media_object_id=v_media, uploaded_at=pg_catalog.now(), transcription_job_id=v_job.id
    where id=p_upload_id returning * into v_row;
  return v_row;
end;
$$;

--
-- Name: studio_create_upload(text, text, text, uuid, uuid, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_create_upload(p_location_id text, p_actor_app text, p_clerk_user_id text, p_upload_id uuid, p_record_id uuid, p_original_filename text, p_content_type text, p_byte_size bigint, p_bucket_id text) RETURNS studio.studio_uploads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row studio.studio_uploads%rowtype;
begin
  perform studio.studio_lock_location_member(p_location_id, p_actor_app, p_clerk_user_id);
  if not exists(select 1 from studio.studio_records where location_id=p_location_id and id=p_record_id) then
    raise exception 'Record not found in this location' using errcode = '22023';
  end if;
  insert into studio.studio_uploads(id,location_id,record_id,original_filename,content_type,byte_size,bucket_id,object_key,created_by_clerk_user_id)
    values(p_upload_id,p_location_id,p_record_id,p_original_filename,p_content_type,p_byte_size,p_bucket_id,
      p_location_id::text || '/uploads/' || p_upload_id::text || '/original',p_clerk_user_id)
    on conflict (id) do nothing returning * into v_row;
  if v_row.id is null then
    select * into v_row from studio.studio_uploads where id=p_upload_id;
    if v_row.location_id <> p_location_id or v_row.record_id <> p_record_id or v_row.byte_size <> p_byte_size
      or v_row.content_type <> p_content_type or v_row.created_by_clerk_user_id <> p_clerk_user_id
      or v_row.original_filename <> p_original_filename or v_row.bucket_id <> p_bucket_id then
      raise exception 'Upload id already used' using errcode = '23505';
    end if;
  end if;
  return v_row;
end;
$$;

--
-- Name: studio_device_command(text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_device_command(p_token_hash text, p_app text, p_operation text, p_body jsonb, p_estio_authorized_by text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d studio.studio_devices%rowtype; j studio.studio_jobs%rowtype; c studio.studio_device_commands%rowtype; v_worker text; v_result jsonb; v_status text; v_ack jsonb;
begin
 -- Read identity without locking, then follow the manager's location→membership→device order.
 select * into d from studio.studio_devices where token_hash=p_token_hash and app=p_app and revoked_at is null;
 if not found then raise exception 'Device authentication failed' using errcode='42501'; end if;
 -- Estio authority is checked by the server against Estio's database for this exact approver.
 if d.app='estio' and p_estio_authorized_by is distinct from d.created_by then raise exception 'Device authentication failed' using errcode='42501'; end if;
 perform studio.studio_lock_ai_manager(d.location_id,d.app,d.created_by);
 select * into d from studio.studio_devices where token_hash=p_token_hash and app=p_app and revoked_at is null for update;
 if not found then raise exception 'Device authentication failed' using errcode='42501'; end if;
 if p_body is null or jsonb_typeof(p_body)<>'object' or octet_length(p_body::text)>32768 then raise exception 'Invalid command' using errcode='22023'; end if;
 v_worker:=p_body->>'workerId';
 if v_worker is null or v_worker !~ '^[A-Za-z0-9:._-]{1,100}$' then raise exception 'Invalid worker' using errcode='22023'; end if;
 if p_operation='heartbeat' then
  if length(p_body->>'release')>100 or (p_body->>'startedAt') is null
   or not isfinite((p_body->>'startedAt')::timestamptz)
   or (p_body->>'startedAt')::timestamptz>clock_timestamp()+interval '5 minutes'
   or jsonb_typeof(coalesce(p_body->'report','{}'))<>'object'
   or octet_length(coalesce(p_body->'report','{}')::text)>16384 then raise exception 'Invalid heartbeat' using errcode='22023'; end if;
  update studio.studio_devices set seen_at=clock_timestamp(),release=p_body->>'release',started_at=(p_body->>'startedAt')::timestamptz,
   report=coalesce(p_body->'report','{}') where id=d.id;
  v_ack:=p_body->'configAck';
  -- Only the current desired version can be acknowledged; stale acks are ignored.
  if jsonb_typeof(v_ack)='object' and jsonb_typeof(v_ack->'version')='number' and (v_ack->>'version')::numeric=d.config_version
   and v_ack->>'status' in ('applied','error') and octet_length(v_ack::text)<=8192 then
   update studio.studio_devices set applied_config_version=d.config_version,config_status=v_ack->>'status',
    config_report=jsonb_strip_nulls(jsonb_build_object('unsupported',case when jsonb_typeof(v_ack->'unsupported')='object' then v_ack->'unsupported' end,'error',left(v_ack->>'error',300)))
   where id=d.id;
  end if;
  -- Commands abandoned by an offline or crashed companion stop blocking new requests.
  update studio.studio_device_commands set status='failed',error='Timed out waiting for the computer.',display='{}',finished_at=clock_timestamp(),updated_at=clock_timestamp()
   where device_id=d.id and status in ('pending','running','waiting_for_user') and created_at<clock_timestamp()-interval '20 minutes';
  return jsonb_build_object('processingEnabled',d.processing_enabled,'paused',d.paused,
   'config',jsonb_build_object('version',d.config_version,'value',d.desired_config),
   'commands',coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'provider',provider) order by created_at)
     from studio.studio_device_commands where device_id=d.id and status='pending'),'[]'));
 elsif p_operation='claim' then
  select coalesce(jsonb_agg(to_jsonb(x)),'[]') into v_result from studio.studio_claim_device_jobs(d.id,d.location_id,v_worker,(p_body->>'limit')::integer,(p_body->>'leaseSeconds')::integer) x;
  return v_result;
 elsif p_operation='command' then
  select * into c from studio.studio_device_commands where id=(p_body->>'commandId')::uuid and device_id=d.id and location_id=d.location_id for update;
  if not found then raise exception 'Command unavailable' using errcode='42501'; end if;
  -- Final states (including a manager cancel) are never overwritten; the device stops on 'cancelled'.
  if c.status in ('succeeded','failed','cancelled') then return jsonb_build_object('status',c.status); end if;
  v_status:=p_body->>'status';
  if v_status is null or v_status not in ('running','waiting_for_user','succeeded','failed')
   or p_body ? 'display' and (v_status<>'waiting_for_user' or jsonb_typeof(p_body->'display')<>'object' or octet_length((p_body->'display')::text)>4096
    or exists(select 1 from jsonb_each(p_body->'display') e where e.key not in ('verificationUrl','userCode') or jsonb_typeof(e.value)<>'string'))
   or p_body->'display'->>'verificationUrl' !~ '^https://'
   or length(p_body->>'error')>300 or p_body->>'error' is not null and v_status<>'failed' then raise exception 'Invalid command status' using errcode='22023'; end if;
  update studio.studio_device_commands set status=v_status,
   display=case when v_status='waiting_for_user' then coalesce(p_body->'display',display) when v_status in ('succeeded','failed') then '{}' else display end,
   error=case when v_status='failed' then coalesce(p_body->>'error','Sign-in failed on the computer.') end,
   finished_at=case when v_status in ('succeeded','failed') then clock_timestamp() end,updated_at=clock_timestamp() where id=c.id;
  return jsonb_build_object('status',v_status);
 end if;
 select * into j from studio.studio_jobs where id=(p_body->>'jobId')::uuid and location_id=d.location_id and device_id=d.id
  and execution_target='device' and kind=any(d.allowed_kinds) for update;
 if not found then raise exception 'Job unavailable' using errcode='42501'; end if;
 if p_operation='extend' then
  return to_jsonb(studio.studio_extend_job_lease(j.id,v_worker,(p_body->>'leaseToken')::uuid,(p_body->>'leaseSeconds')::integer));
 elsif p_operation='complete' then
  -- Diagnostic output is data only: bounded scalar fields, no nested credentials.
  if jsonb_typeof(p_body->'result') is distinct from 'object' or octet_length((p_body->'result')::text)>4096
   or exists(select 1 from jsonb_each(p_body->'result') e where e.key not in ('ok','workerId','checkedAt','provider','model','output','summary','durationMs')
    or case when e.key='ok' then jsonb_typeof(e.value)<>'boolean'
     when e.key='durationMs' then jsonb_typeof(e.value)<>'number'
     else jsonb_typeof(e.value)<>'string' or length(e.value#>>'{}')>case when e.key in ('output','summary') then 3000 else 100 end end)
   then raise exception 'Invalid result' using errcode='22023'; end if;
  return to_jsonb(studio.studio_complete_job(j.id,v_worker,(p_body->>'leaseToken')::uuid,p_body->'result'));
 elsif p_operation='fail' then
  return to_jsonb(studio.studio_fail_job(j.id,v_worker,(p_body->>'leaseToken')::uuid,p_body->'failure'->>'code',
   p_body->'failure'->>'message',(p_body->'failure'->>'retryable')::boolean,(p_body->'failure'->>'retryAfterSeconds')::integer));
 end if;
 raise exception 'Invalid device operation' using errcode='22023';
end $_$;

--
-- Name: studio_device_identity(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_device_identity(p_token_hash text, p_app text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('locationId',location_id,'approvedBy',created_by) from studio.studio_devices
 where token_hash=p_token_hash and app=p_app and revoked_at is null
$$;

--
-- Name: studio_device_pair_poll(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_device_pair_poll(p_app text, p_pairing_id uuid, p_device_code_hash text, p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare p studio.studio_device_pairings%rowtype; d studio.studio_devices%rowtype; v_name text;
begin
 if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid pairing' using errcode='22023'; end if;
 select * into p from studio.studio_device_pairings where id=p_pairing_id and app=p_app and device_code_hash=p_device_code_hash for update;
 if not found then raise exception 'Pairing unavailable' using errcode='42501'; end if;
 update studio.studio_device_pairings set poll_count=poll_count+1 where id=p.id;
 if p.consumed_at is not null then return jsonb_build_object('status','consumed'); end if;
 if p.denied_at is not null then return jsonb_build_object('status','denied'); end if;
 if p.expires_at<=clock_timestamp() or p.poll_count>=400 then
  if p.device_id is not null then update studio.studio_devices set revoked_at=coalesce(revoked_at,clock_timestamp()) where id=p.device_id and token_hash is null; end if;
  return jsonb_build_object('status','expired');
 end if;
 if p.approved_at is null then return jsonb_build_object('status','pending'); end if;
 update studio.studio_devices set token_hash=p_token_hash where id=p.device_id and token_hash is null and revoked_at is null returning * into d;
 update studio.studio_device_pairings set consumed_at=clock_timestamp() where id=p.id;
 if d.id is null then return jsonb_build_object('status','denied'); end if;
 select name into v_name from studio.studio_locations where location_id=d.location_id;
 return jsonb_build_object('status','approved','deviceId',d.id,'businessName',v_name);
end $_$;

--
-- Name: studio_device_pair_start(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_device_pair_start(p_app text, p_name text, p_platform text, p_device_code_hash text, p_user_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p studio.studio_device_pairings%rowtype;
begin
 if p_app is null or p_app not in ('estio','substo') then raise exception 'Invalid pairing' using errcode='22023'; end if;
 -- Approved pairings whose token was never collected leave no usable device behind.
 update studio.studio_devices set revoked_at=clock_timestamp() where token_hash is null and revoked_at is null
  and id in (select device_id from studio.studio_device_pairings where consumed_at is null and device_id is not null and expires_at<clock_timestamp());
 delete from studio.studio_device_pairings where id in (select id from studio.studio_device_pairings where expires_at<clock_timestamp()-interval '1 day' limit 200);
 insert into studio.studio_device_pairings(app,user_code,device_code_hash,name,platform,expires_at)
 values(p_app,p_user_code,p_device_code_hash,btrim(p_name),p_platform,clock_timestamp()+interval '10 minutes') returning * into p;
 return jsonb_build_object('pairingId',p.id,'userCode',p.user_code,'expiresAt',p.expires_at);
end $$;

--
-- Name: studio_device_pairing_action(text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_device_pairing_action(p_location_id text, p_actor_app text, p_clerk_user_id text, p_action text, p_user_code text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare p studio.studio_device_pairings%rowtype; d studio.studio_devices%rowtype;
begin
 perform studio.studio_lock_ai_manager(p_location_id,p_actor_app,p_clerk_user_id);
 if p_action is null or p_action not in ('lookup','approve','deny') or p_user_code is null or p_user_code !~ '^[ABCDEFGHJKMNPQRSTUVWXYZ2-9]{8}$'
  or p_action='approve' and p_request_id is null then raise exception 'Invalid pairing action' using errcode='22023'; end if;
 select * into p from studio.studio_device_pairings where app=p_actor_app and user_code=p_user_code
  order by (consumed_at is null and denied_at is null) desc, created_at desc limit 1 for update;
 if not found then raise exception 'Pairing not found' using errcode='P0002'; end if;
 if p_action='lookup' then
  return jsonb_build_object('name',p.name,'platform',p.platform,'expiresAt',p.expires_at,'status',case
   when p.consumed_at is not null then 'consumed' when p.denied_at is not null then 'denied'
   when p.approved_at is not null then 'approved' when p.expires_at<=clock_timestamp() then 'expired' else 'pending' end);
 end if;
 -- Same request retried after a lost response returns the original approval.
 if p_action='approve' and p.approved_at is not null and p.location_id=p_location_id then
  select * into d from studio.studio_devices where id=p.device_id and request_id=p_request_id;
  if found then return jsonb_build_object('deviceId',d.id,'name',d.name); end if;
 end if;
 if p.approved_at is not null or p.denied_at is not null or p.consumed_at is not null or p.expires_at<=clock_timestamp() then
  raise exception 'Pairing no longer valid' using errcode='P0002';
 end if;
 if p_action='deny' then
  update studio.studio_device_pairings set denied_at=clock_timestamp() where id=p.id;
  return jsonb_build_object('status','denied');
 end if;
 insert into studio.studio_devices(location_id,app,name,platform,token_hash,request_id,created_by)
 values(p_location_id,p_actor_app,p.name,p.platform,null,p_request_id,p_clerk_user_id) returning * into d;
 -- Leave time for the device's next poll even when approved just before expiry.
 update studio.studio_device_pairings set approved_at=clock_timestamp(),approved_by=p_clerk_user_id,location_id=p_location_id,device_id=d.id,
  expires_at=greatest(expires_at,clock_timestamp()+interval '2 minutes') where id=p.id;
 return jsonb_build_object('deviceId',d.id,'name',d.name);
end $_$;

--
-- Name: studio_dispatch_schedule(text, uuid, uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_dispatch_schedule(p_location_id text, p_schedule_id uuid, p_activation_token uuid, p_due_at timestamp with time zone, p_estio_authorized boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s studio.studio_schedules%rowtype; r studio.studio_schedule_recurring%rowtype;
  v_snapshot jsonb; outcome text; result jsonb; v_execution uuid; v_authorized boolean:=true; v_workflow text;
begin
  -- Match membership->definition->activation lock order with interactive commands.
  select * into r from studio.studio_schedule_recurring where location_id=p_location_id and schedule_id=p_schedule_id;
  if not found or r.activation_token is distinct from p_activation_token then return '{"outcome":"not_due"}'; end if;
  if r.snapshot->>'workflow'='youtube_discovery' then
    perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||r.actor_app||':'||r.authorized_by,0));
  end if;
  begin
    perform studio.studio_lock_location_member(p_location_id,r.actor_app,r.authorized_by);
  exception when insufficient_privilege then v_authorized:=false;
  end;
  if r.actor_app='estio' and p_estio_authorized is distinct from true then v_authorized:=false; end if;
  select * into s from studio.studio_schedules where location_id=p_location_id and id=p_schedule_id for update;
  select * into r from studio.studio_schedule_recurring where location_id=p_location_id and schedule_id=p_schedule_id for update;
  if not r.enabled or r.activation_token is distinct from p_activation_token or r.next_run_at is distinct from p_due_at
    or r.next_run_at>clock_timestamp() then return '{"outcome":"not_due"}'; end if;
  if not v_authorized then outcome:='authority_revoked';
  elsif s.version<>r.schedule_version then outcome:='inputs_changed';
  elsif exists(select 1 from studio.studio_schedule_executions e join studio.studio_ai_attempts a on a.job_id=e.job_id
    where e.location_id=p_location_id and e.schedule_id=p_schedule_id and a.status in ('started','uncertain') and not a.replacement_authorized
      and not exists(select 1 from studio.studio_jobs j where j.id=e.job_id and j.status in ('queued','running'))) then outcome:='charge_review_required';
  elsif exists(select 1 from studio.studio_schedule_executions e join studio.studio_jobs j on j.id=e.job_id
    where e.location_id=p_location_id and e.schedule_id=p_schedule_id and j.status in ('queued','running')) then outcome:='busy';
  elsif s.preset_id='youtube-discovery' then
    begin
      v_execution:=studio.studio_enqueue_youtube_schedule(p_location_id,p_schedule_id,r.activation_token,p_due_at);
      outcome:='queued';
    exception when insufficient_privilege or invalid_parameter_value then outcome:='inputs_changed'; when serialization_failure then outcome:='busy'; end;
  else
    v_workflow:=case when s.preset_id='idea-review' then 'idea_review' else 'script_brief' end;
    begin
      begin
        v_snapshot:=studio.studio_build_selected_text_snapshot(p_location_id,r.selection,s.focus,v_workflow);
      exception when serialization_failure or invalid_parameter_value then outcome:='inputs_changed'; end;
      if outcome='inputs_changed' or v_snapshot is distinct from r.snapshot then outcome:='inputs_changed';
      else
        result:=studio.studio_run_schedule_now(p_location_id,r.actor_app,r.authorized_by,p_schedule_id,s.version,gen_random_uuid(),r.selection,true);
        v_execution:=(result->>'executionId')::uuid;
        update studio.studio_schedule_executions set activation_token=r.activation_token,due_at=p_due_at where id=v_execution;
        outcome:='queued';
      end if;
    exception when serialization_failure then outcome:='busy'; when invalid_parameter_value then outcome:='inputs_changed';
    end;
  end if;
  update studio.studio_schedule_recurring set
    enabled=outcome in ('queued','busy'),next_run_at=case when outcome in ('queued','busy') then studio.studio_next_schedule_due(clock_timestamp(),s.interval_hours,s.daily_time,s.time_zone) else null end,
    last_outcome=outcome,version=version+case when outcome in ('queued','busy') then 0 else 1 end,updated_at=clock_timestamp()
    where location_id=p_location_id and schedule_id=p_schedule_id;
  insert into studio.studio_schedule_ticks(location_id,schedule_id,activation_token,due_at,outcome,execution_id) values(p_location_id,p_schedule_id,r.activation_token,p_due_at,outcome,v_execution);
  return jsonb_build_object('outcome',outcome,'executionId',v_execution);
end; $$;

--
-- Name: studio_enable_youtube_schedule(text, text, text, uuid, bigint, bigint, uuid, uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enable_youtube_schedule(p_location text, p_app text, p_user text, p_schedule uuid, p_version bigint, p_state_version bigint, p_request uuid, p_connection_version uuid, p_source text, p_channel text, p_title text, p_confirm_share boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s studio.studio_schedules%rowtype; r studio.studio_schedule_recurring%rowtype;
 request jsonb; prior studio.studio_schedule_commands%rowtype; result jsonb; snapshot jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||p_app||':'||p_user,0));
 perform studio.studio_lock_location_member(p_location,p_app,p_user);
 if p_schedule is null or p_version is null or p_version<1 or p_state_version is null or p_state_version<0 or p_request is null
 or p_connection_version is null or p_source is null or p_source not in ('approved_channel','search','subscription')
 or p_channel is null or (p_source='search' and p_channel<>'') or (p_source<>'search' and p_channel !~ '^UC[A-Za-z0-9_-]{22}$')
 or p_title is null or char_length(btrim(p_title)) not between 1 and 100 or p_title ~ '[[:cntrl:]]' or p_confirm_share is distinct from true then
 raise exception 'Explicit profile-bound recurring sharing consent required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('schedule-command:'||p_location::text||':'||p_request::text,0));
 request:=jsonb_build_object('action','enable_youtube','actor',p_user,'app',p_app,'scheduleId',p_schedule,'version',p_version,'stateVersion',p_state_version,
 'connectionVersion',p_connection_version,'sourceDigest',encode(sha256(convert_to(jsonb_build_array(p_source,p_channel,p_title)::text,'UTF8')),'hex'));
 select * into prior from studio.studio_schedule_commands where location_id=p_location and request_id=p_request;
 if found then
  if prior.request is distinct from request then raise exception 'Request reused' using errcode='23505'; end if;
  return prior.result;
 end if;
 if exists(select 1 from studio.studio_schedule_executions where location_id=p_location and request_id=p_request) then raise exception 'Run request reused' using errcode='23505'; end if;
 perform 1 from studio.platform_google_youtube_connections where app=p_app and clerk_user_id=p_user and version=p_connection_version
 and 'https://www.googleapis.com/auth/youtube.readonly'=any(granted_scopes) for share;
 if not found then raise exception 'Current profile grant required' using errcode='42501'; end if;
 select * into s from studio.studio_schedules where location_id=p_location and id=p_schedule for update;
 if s.id is null or s.version<>p_version or s.preset_id<>'youtube-discovery' then raise exception 'YouTube definition changed' using errcode='40001'; end if;
 if p_source='search' and btrim(s.focus)='' then raise exception 'Save a public search focus first' using errcode='22023'; end if;
 if p_source='approved_channel' then
  perform 1 from studio.studio_youtube_channels where location_id=p_location and channel_id=p_channel for share;
  if not found then raise exception 'Channel not approved' using errcode='42501'; end if;
 end if;
 select * into r from studio.studio_schedule_recurring where location_id=p_location and schedule_id=p_schedule for update;
 if coalesce(r.version,0)<>p_state_version then raise exception 'Activation changed' using errcode='40001'; end if;
 snapshot:=jsonb_build_object('workflow','youtube_discovery','maxLinks',10,'rights','research_link_only','titlePrefix',btrim(p_title));
 insert into studio.studio_schedule_recurring(location_id,schedule_id,actor_app,authorized_by,schedule_version,selection,snapshot,enabled,next_run_at,last_outcome)
 values(p_location,p_schedule,p_app,p_user,s.version,'[]',snapshot,true,studio.studio_next_schedule_due(clock_timestamp(),s.interval_hours,s.daily_time,s.time_zone),'enabled')
 on conflict(location_id,schedule_id) do update set version=studio_schedule_recurring.version+1,actor_app=excluded.actor_app,authorized_by=excluded.authorized_by,
 schedule_version=excluded.schedule_version,selection='[]',snapshot=excluded.snapshot,enabled=true,activation_token=gen_random_uuid(),next_run_at=excluded.next_run_at,last_outcome='enabled',updated_at=clock_timestamp() returning * into r;
 insert into studio.platform_youtube_schedule_authorizations(location_id,schedule_id,app,clerk_user_id,connection_version,activation_token,source_mode,channel_id,title_prefix)
 values(p_location,p_schedule,p_app,p_user,p_connection_version,r.activation_token,p_source,p_channel,btrim(p_title))
 on conflict(location_id,schedule_id) do update set app=excluded.app,clerk_user_id=excluded.clerk_user_id,connection_version=excluded.connection_version,
 activation_token=excluded.activation_token,source_mode=excluded.source_mode,channel_id=excluded.channel_id,title_prefix=excluded.title_prefix,expires_at=clock_timestamp()+interval '30 days';
 result:=jsonb_build_object('enabled',true,'stateVersion',r.version,'nextRunAt',r.next_run_at);
 insert into studio.studio_schedule_commands(location_id,request_id,request,result,snapshot) values(p_location,p_request,request,result,snapshot);
 return result;
end; $_$;

--
-- Name: studio_enqueue_idea_review(text, text, text, uuid, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enqueue_idea_review(p_location_id text, p_actor_app text, p_clerk_user_id text, p_request_id uuid, p_selection jsonb, p_focus text, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select studio.studio_enqueue_text_run(p_location_id,p_actor_app,p_clerk_user_id,p_request_id,p_selection,p_focus,p_confirm_paid,'idea_review');
$$;

--
-- Name: studio_enqueue_job(text, text, jsonb, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enqueue_job(p_location_id text, p_kind text, p_payload jsonb, p_idempotency_key text, p_created_by text, p_max_attempts integer DEFAULT 5) RETURNS studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_job studio.studio_jobs%rowtype;
begin
  insert into studio.studio_jobs(location_id,kind,payload,idempotency_key,created_by_clerk_user_id,max_attempts)
    values(p_location_id,p_kind,coalesce(p_payload,'{}'::jsonb),p_idempotency_key,p_created_by,coalesce(p_max_attempts,5))
    on conflict (location_id,idempotency_key) do nothing returning * into v_job;
  if v_job.id is null then
    select * into v_job from studio.studio_jobs where location_id=p_location_id and idempotency_key=p_idempotency_key;
    if v_job.kind <> p_kind or v_job.payload <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'Idempotency key already used for a different job' using errcode = '23505';
    end if;
    return v_job;
  end if;
  insert into studio.studio_job_events(job_id,location_id,attempt,event,actor_clerk_user_id) values(v_job.id,v_job.location_id,0,'queued',p_created_by);
  return v_job;
end;
$$;

--
-- Name: studio_enqueue_knowledge_extraction(text, text, text, uuid, uuid, bigint, text, text, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enqueue_knowledge_extraction(p_location_id text, p_actor_app text, p_clerk_user_id text, p_request_id uuid, p_source_id uuid, p_expected_version bigint, p_mode text, p_input_id text, p_start_unit integer, p_unit_count integer, p_focus text, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare prior studio.studio_idea_reviews%rowtype; v_request jsonb; snapshot jsonb; run_id uuid:=gen_random_uuid(); j studio.studio_jobs%rowtype;
begin
 perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
 if p_request_id is null or p_confirm_paid is distinct from true then raise exception 'Explicit paid extraction authorization required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('idea-review:'||p_location_id::text,0));
 v_request := jsonb_build_object('sourceId',p_source_id,'version',p_expected_version,'mode',p_mode,'inputId',p_input_id,'startUnit',p_start_unit,'unitCount',p_unit_count,'focus',p_focus,'actor',p_clerk_user_id,'app',p_actor_app);
 select * into prior from studio.studio_idea_reviews where location_id=p_location_id and request_id=p_request_id;
 if found then
  if prior.workflow<>'knowledge_extract' or prior.request is distinct from v_request then raise exception 'Extraction request reused' using errcode='23505'; end if;
  return jsonb_build_object('reviewId',prior.id,'jobId',prior.job_id);
 end if;
 if (select count(*) from studio.studio_jobs where location_id=p_location_id and kind in ('studio.idea_review','studio.script_brief','studio.knowledge_extract') and status in ('queued','running'))>=5 then raise exception 'Too many active text runs' using errcode='40001'; end if;
 snapshot := studio.studio_build_knowledge_snapshot(p_location_id,p_source_id,p_expected_version,p_mode,p_input_id,p_start_unit,p_unit_count,p_focus);
 if octet_length(snapshot::text)>24000 then raise exception 'Select fewer source units for this bounded extraction' using errcode='22023'; end if;
 j := studio.studio_enqueue_job(p_location_id,'studio.knowledge_extract',jsonb_build_object('reviewId',run_id),'text-run:'||p_request_id::text,p_clerk_user_id,5);
 insert into studio.studio_idea_reviews(id,location_id,request_id,created_by_clerk_user_id,actor_app,request,snapshot,job_id,workflow,prompt_version)
  values(run_id,p_location_id,p_request_id,p_clerk_user_id,p_actor_app,v_request,snapshot,j.id,'knowledge_extract','studio.knowledge-extract.v1');
 return jsonb_build_object('reviewId',run_id,'jobId',j.id);
end; $$;

--
-- Name: studio_enqueue_script_brief(text, text, text, uuid, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enqueue_script_brief(p_location_id text, p_actor_app text, p_clerk_user_id text, p_request_id uuid, p_selection jsonb, p_focus text, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select studio.studio_enqueue_text_run(p_location_id,p_actor_app,p_clerk_user_id,p_request_id,p_selection,p_focus,p_confirm_paid,'script_brief');
$$;

--
-- Name: studio_enqueue_text_run(text, text, text, uuid, jsonb, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enqueue_text_run(p_location_id text, p_actor_app text, p_clerk_user_id text, p_request_id uuid, p_selection jsonb, p_focus text, p_confirm_paid boolean, p_workflow text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare prior studio.studio_idea_reviews%rowtype; v_request jsonb; v_snapshot jsonb; v_ideas jsonb;
  v_review uuid := gen_random_uuid(); j studio.studio_jobs%rowtype; ids uuid[];
begin
  perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
  if p_workflow is null or p_workflow not in ('idea_review','script_brief') then raise exception 'Invalid text workflow' using errcode='22023'; end if;
  if p_workflow='script_brief' and jsonb_array_length(p_selection)<>1 then raise exception 'Select exactly one idea' using errcode='22023'; end if;
  if p_request_id is null or p_confirm_paid is distinct from true or p_focus is null or char_length(p_focus)>300
    or p_selection is null or jsonb_typeof(p_selection)<>'array' or jsonb_array_length(p_selection) not between 1 and 5 then
    raise exception 'Select one to five ideas and authorize the review' using errcode='22023'; end if;
  -- Serialize per-location enqueue requests without conflicting with FK locks.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('idea-review:'||p_location_id::text,0));
  select array_agg((x->>'id')::uuid order by x->>'id') into ids from jsonb_array_elements(p_selection) x;
  if (select count(distinct id) from unnest(ids) id) <> jsonb_array_length(p_selection)
    or exists(select 1 from jsonb_array_elements(p_selection) x where x->>'version' is null or (x->>'version') !~ '^[1-9][0-9]{0,14}$') then
    raise exception 'Invalid idea selection' using errcode='22023'; end if;
  v_request := jsonb_build_object('selection',p_selection,'focus',p_focus,'actor',p_clerk_user_id,'app',p_actor_app);
  select * into prior from studio.studio_idea_reviews where location_id=p_location_id and request_id=p_request_id;
  if found then
    if prior.workflow is distinct from p_workflow or prior.request is distinct from v_request then raise exception 'Review request reused' using errcode='23505'; end if;
    return jsonb_build_object('reviewId',prior.id,'jobId',prior.job_id);
  end if;
  if (select count(*) from studio.studio_jobs where location_id=p_location_id and kind in ('studio.idea_review','studio.script_brief','studio.knowledge_extract') and status in ('queued','running'))>=5 then
    raise exception 'Too many active idea reviews' using errcode='40001'; end if;
  v_snapshot := studio.studio_build_selected_text_snapshot(p_location_id,p_selection,p_focus,p_workflow);
  j := studio.studio_enqueue_job(p_location_id,'studio.'||p_workflow,jsonb_build_object('reviewId',v_review),'text-run:'||p_request_id::text,p_clerk_user_id,5);
  insert into studio.studio_idea_reviews(id,location_id,request_id,created_by_clerk_user_id,actor_app,request,snapshot,job_id,workflow,prompt_version)
    values(v_review,p_location_id,p_request_id,p_clerk_user_id,p_actor_app,v_request,v_snapshot,j.id,p_workflow,case when p_workflow='script_brief' then 'studio.script-brief.v1' else 'studio.idea-review.v1' end);
  return jsonb_build_object('reviewId',v_review,'jobId',j.id);
end; $_$;

--
-- Name: studio_enqueue_youtube_schedule(text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_enqueue_youtube_schedule(p_location text, p_schedule uuid, p_token uuid, p_due timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare g studio.platform_youtube_schedule_authorizations%rowtype; run uuid:=gen_random_uuid(); execution uuid:=gen_random_uuid(); j studio.studio_jobs%rowtype; s studio.studio_schedules%rowtype;
begin
 g:=studio.studio_lock_youtube_schedule(p_location,p_schedule,p_token);
 select * into s from studio.studio_schedules where location_id=p_location and id=p_schedule;
 perform pg_advisory_xact_lock(hashtextextended('youtube-schedule-enqueue:'||p_location::text,0));
 if (select count(*) from studio.studio_jobs where location_id=p_location and kind='studio.youtube_discovery' and status in ('queued','running'))>=5 then raise exception 'Too many active discovery runs' using errcode='40001'; end if;
 j:=studio.studio_enqueue_job(p_location,'studio.youtube_discovery',jsonb_build_object('discoveryRunId',run),'youtube-discovery:'||run::text,g.clerk_user_id,3);
 insert into studio.studio_youtube_schedule_runs(id,location_id,schedule_id,activation_token,job_id,actor_app,created_by_clerk_user_id)
 values(run,p_location,p_schedule,p_token,j.id,g.app,g.clerk_user_id);
 insert into studio.studio_schedule_executions(id,location_id,schedule_id,request_id,actor_app,created_by_clerk_user_id,request,definition,workflow,youtube_run_id,job_id,activation_token,due_at)
 values(execution,p_location,p_schedule,gen_random_uuid(),g.app,g.clerk_user_id,jsonb_build_object('origin','due_dispatch'),
 jsonb_build_object('version',s.version,'presetId',s.preset_id,'focus',s.focus,'intervalHours',s.interval_hours,'dailyTime',s.daily_time,'timeZone',s.time_zone),'youtube_discovery',run,j.id,p_token,p_due);
 return execution;
end; $$;

--
-- Name: studio_extend_job_lease(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_extend_job_lease(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_lease_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_lease_seconds is null or p_lease_seconds not between 10 and 3600 then raise exception 'Invalid lease' using errcode = '22023'; end if;
  update studio.studio_jobs set lease_expires_at=pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => p_lease_seconds), updated_at=pg_catalog.clock_timestamp()
    where id=p_job_id and status='running' and lease_owner=p_worker_id and lease_token=p_lease_token and lease_expires_at > pg_catalog.clock_timestamp();
  return found;
end;
$$;

--
-- Name: studio_fail_job(uuid, text, uuid, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_fail_job(p_job_id uuid, p_worker_id text, p_lease_token uuid, p_error_code text, p_error_message text, p_retryable boolean, p_retry_after_seconds integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_job studio.studio_jobs%rowtype;
  v_delay integer;
begin
  if p_error_code is null or p_error_code !~ '^[a-z][a-z0-9_]{0,63}$' then raise exception 'Invalid error code' using errcode = '22023'; end if;
  select * into v_job from studio.studio_jobs where id=p_job_id and status='running' and lease_owner=p_worker_id and lease_token=p_lease_token and lease_expires_at > pg_catalog.clock_timestamp() for update;
  if not found or v_job.lease_expires_at <= pg_catalog.clock_timestamp() then return 'lease_lost'; end if;
  if coalesce(p_retryable,false) and v_job.attempts < v_job.max_attempts then
    v_delay := coalesce(p_retry_after_seconds, least(3600, 30 * (2 ^ (v_job.attempts - 1))::integer));
    v_delay := greatest(1, least(v_delay, 2678400));
    update studio.studio_jobs set status='queued', lease_owner=null, lease_expires_at=null, last_error_code=p_error_code,
      last_error_message=pg_catalog.left(p_error_message,500), run_after=pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => v_delay), updated_at=pg_catalog.clock_timestamp()
      where id=p_job_id;
    insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id,error_code) values(v_job.id,v_job.location_id,v_job.attempts,'retry_scheduled',p_worker_id,p_error_code);
    return 'retry_scheduled';
  end if;
  update studio.studio_jobs set status='failed', lease_owner=null, lease_expires_at=null, last_error_code=p_error_code,
    last_error_message=pg_catalog.left(p_error_message,500), finished_at=pg_catalog.clock_timestamp(), updated_at=pg_catalog.clock_timestamp() where id=p_job_id;
  insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id,error_code) values(v_job.id,v_job.location_id,v_job.attempts,'failed',p_worker_id,p_error_code);
  return 'failed';
end;
$_$;

--
-- Name: studio_find_knowledge_topics(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_find_knowledge_topics(p_location text, p_app text, p_user text, p_query text) RETURNS TABLE(id uuid, name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform studio.studio_lock_location_member(p_location,p_app,p_user);
 if p_query is null or char_length(p_query)>120 or p_query ~ '[[:cntrl:]]' then raise exception 'Invalid topic query' using errcode='22023'; end if;
 return query select t.id,t.payload->>'name' from studio.studio_knowledge_topics t where t.location_id=p_location
  and jsonb_typeof(t.payload->'name')='string' and strpos(lower(t.payload->>'name'),lower(p_query))>0
  order by lower(t.payload->>'name'),t.id limit 101;
end; $$;

--
-- Name: studio_finish_idea_review_attempt(text, uuid, uuid, text, uuid, uuid, jsonb, bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_finish_idea_review_attempt(p_location_id text, p_review_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_attempt_id uuid, p_result jsonb, p_input_tokens bigint, p_output_tokens bigint, p_response_id text, p_rate_version text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform studio.studio_lock_idea_review_lease(p_location_id,p_review_id,p_job_id,p_worker_id,p_lease_token);
  return studio.studio_finish_text_run_attempt(p_location_id,p_review_id,p_job_id,p_worker_id,p_lease_token,p_attempt_id,p_result,p_input_tokens,p_output_tokens,p_response_id,p_rate_version);
end; $$;

--
-- Name: studio_finish_text_run_attempt(text, uuid, uuid, text, uuid, uuid, jsonb, bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_finish_text_run_attempt(p_location_id text, p_review_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_attempt_id uuid, p_result jsonb, p_input_tokens bigint, p_output_tokens bigint, p_response_id text, p_rate_version text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a studio.studio_ai_attempts%rowtype; snapshot jsonb; v_workflow text; v_stale boolean;
begin
  perform studio.studio_lock_text_run_lease(p_location_id,p_review_id,p_job_id,p_worker_id,p_lease_token);
  select * into a from studio.studio_ai_attempts where id=p_attempt_id and idea_review_id=p_review_id and location_id=p_location_id
    and job_id=p_job_id and lease_token=p_lease_token for update;
  if a.id is null or a.status not in ('started','succeeded') then raise exception 'Attempt cannot finish' using errcode='40001'; end if;
  if a.status='succeeded' then return true; end if;
  select r.snapshot,r.workflow into snapshot,v_workflow from studio.studio_idea_reviews r where id=p_review_id for update;
  if p_input_tokens is null or p_input_tokens not between 0 and 60000 or p_output_tokens is null
    or p_output_tokens not between 0 and (case when v_workflow in ('script_brief','knowledge_extract') then 6000 else 3000 end)
    or p_response_id is null or length(p_response_id) not between 1 and 200
    or p_rate_version is distinct from 'gpt-6-luna-standard-2026-10-23' then raise exception 'Invalid text usage' using errcode='22023'; end if;
  perform studio.studio_validate_text_run_result(v_workflow,p_result,snapshot);
  if v_workflow='knowledge_extract' then
    v_stale := not studio.studio_knowledge_snapshot_current(p_location_id,snapshot);
  else
  -- Preserve paid results even when content changed; never write back into ideas.
  perform 1 from studio.studio_records r where r.location_id=p_location_id and r.id in
    (select (i->>'id')::uuid from jsonb_array_elements(snapshot->'ideas') i union
     select (s->>'id')::uuid from jsonb_array_elements(snapshot->'ideas') i,jsonb_array_elements(i->'sources') s) order by r.id for share;
  select exists(select 1 from (select i from jsonb_array_elements(snapshot->'ideas') i union all
    select s from jsonb_array_elements(snapshot->'ideas') i,jsonb_array_elements(i->'sources') s) x where not exists
    (select 1 from studio.studio_records r where r.location_id=p_location_id and r.id=(x.i->>'id')::uuid and r.version=(x.i->>'version')::bigint)) into v_stale;
  end if;
  perform studio.studio_settle_ai_spend(p_location_id,a.usage_id,ceil((p_input_tokens::numeric+5*p_output_tokens)/10)::bigint,
    a.model,p_input_tokens,p_output_tokens,null);
  update studio.studio_idea_reviews set result=p_result,stale_at_completion=v_stale,completed_at=clock_timestamp() where id=p_review_id;
  update studio.studio_ai_attempts set status='succeeded',provider_response_id=p_response_id,rate_version=p_rate_version,updated_at=clock_timestamp() where id=a.id;
  return true;
end; $$;

--
-- Name: studio_finish_transcription_attempt(text, uuid, uuid, text, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_finish_transcription_attempt(p_location_id text, p_upload_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_attempt_id uuid, p_text text, p_segments jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a studio.studio_transcription_attempts%rowtype;
begin
  perform studio.studio_lock_transcription_lease(p_location_id,p_upload_id,p_job_id,p_worker_id,p_lease_token);
  select * into a from studio.studio_transcription_attempts where id=p_attempt_id and job_id=p_job_id
    and upload_id=p_upload_id and location_id=p_location_id and lease_token=p_lease_token for update;
  if a.id is null or a.status not in ('started','succeeded') then raise exception 'Attempt cannot finish' using errcode='40001'; end if;
  if a.status='succeeded' then return true; end if;
  perform studio.studio_save_transcript_chunk(p_location_id,p_upload_id,a.chunk_index,a.chunk_index*600,a.duration_seconds,'whisper-1',p_text,p_segments);
  perform studio.studio_settle_ai_spend(p_location_id,a.usage_id,pg_catalog.ceil(a.duration_seconds*100)::bigint,'whisper-1',null,null,a.duration_seconds);
  update studio.studio_transcription_attempts set status='succeeded',updated_at=pg_catalog.clock_timestamp() where id=a.id;
  return true;
end;
$$;

--
-- Name: studio_transcripts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE studio.studio_transcripts (
    upload_id uuid NOT NULL,
    location_id text NOT NULL,
    model text NOT NULL,
    language text,
    duration_seconds numeric NOT NULL,
    text text NOT NULL,
    segments jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT studio_transcripts_duration_seconds_check CHECK ((duration_seconds >= (0)::numeric)),
    CONSTRAINT studio_transcripts_language_check CHECK (((language IS NULL) OR (language ~ '^[a-z]{2,12}$'::text))),
    CONSTRAINT studio_transcripts_segments_check CHECK ((jsonb_typeof(segments) = 'array'::text)),
    CONSTRAINT studio_transcripts_text_check CHECK ((char_length(text) <= 20000000))
);

--
-- Name: studio_finish_upload_transcript(text, uuid, uuid, text, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_finish_upload_transcript(p_location_id text, p_upload_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid, p_model text, p_language text, p_duration_seconds numeric) RETURNS studio.studio_transcripts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
  perform studio.studio_lock_transcription_lease(p_location_id,p_upload_id,p_job_id,p_worker_id,p_lease_token);
  if p_duration_seconds is null or p_duration_seconds <= 0 or p_duration_seconds > 21600 or p_model is distinct from 'whisper-1' then
    raise exception 'Invalid transcript' using errcode='22023'; end if;
  n := pg_catalog.ceil(p_duration_seconds/600)::integer;
  -- Allow sub-millisecond JS subtraction/probe rounding, never missing chunks.
  if (select count(*) from studio.studio_transcript_chunks where upload_id=p_upload_id) <> n
    or exists(select 1 from pg_catalog.generate_series(0,n-1) i where not exists
    (select 1 from studio.studio_transcript_chunks c where c.upload_id=p_upload_id and c.location_id=p_location_id
      and c.chunk_index=i and c.start_seconds=i*600
      and pg_catalog.abs(c.duration_seconds-least(600,p_duration_seconds-i*600)) <= 0.001)) then
    raise exception 'Transcript incomplete' using errcode='22023'; end if;
  return studio.studio_save_transcript(p_location_id,p_upload_id,p_model,p_language,p_duration_seconds);
end;
$$;

--
-- Name: studio_finish_youtube_discovery(text, uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_finish_youtube_discovery(p_location text, p_run uuid, p_job uuid, p_worker text, p_lease uuid, p_videos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare run studio.studio_youtube_schedule_runs%rowtype; g studio.platform_youtube_schedule_authorizations%rowtype; video text; record_id uuid;
 v_result jsonb:='[]'; was_existing boolean; observed timestamptz:=clock_timestamp();
begin
 run:=studio.studio_lock_youtube_run(p_location,p_run,p_job,p_worker,p_lease);
 if run.result is not null then return run.result; end if;
 if run.slot_lease_token is distinct from p_lease or p_videos is null or jsonb_typeof(p_videos)<>'array' or jsonb_array_length(p_videos)>10
 or exists(select 1 from jsonb_array_elements(p_videos) v where jsonb_typeof(v)<>'string' or (v#>>'{}') !~ '^[A-Za-z0-9_-]{11}$')
 or (select count(distinct v) from jsonb_array_elements_text(p_videos) v)<>jsonb_array_length(p_videos) then raise exception 'Bounded public video IDs required' using errcode='22023'; end if;
 g:=studio.studio_lock_youtube_source(p_location,p_run);
 -- The existing bookmark RPC serializes per location and preserves all existing edits.
 perform studio.studio_lock_youtube_member(p_location,g.app,g.clerk_user_id);
 for video in select value from jsonb_array_elements_text(p_videos) loop
  was_existing:=exists(select 1 from studio.studio_youtube_bookmarks where location_id=p_location and video_id=video)
   or exists(select 1 from studio.studio_records where location_id=p_location and kind='reference' and source_url='https://www.youtube.com/watch?v='||video);
  record_id:=studio.studio_save_youtube_bookmark(p_location,g.app,g.clerk_user_id,gen_random_uuid(),video,g.title_prefix||' · '||video,
   jsonb_build_object('kind','saved_url','origin',case when run.manual then 'manual_discovery' else 'scheduled_discovery' end,'runId',p_run,'observedAt',observed,'provider','youtube_data_api','rights','research_link_only'));
  v_result:=v_result||jsonb_build_array(jsonb_build_object('videoId',video,'recordId',record_id,'reused',was_existing));
 end loop;
 v_result:=jsonb_build_object('links',v_result,'observedAt',observed);
 update studio.studio_youtube_schedule_runs set result=v_result,completed_at=clock_timestamp() where id=p_run;
 return v_result;
end; $_$;

--
-- Name: studio_import_knowledge(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_import_knowledge(p_location_id text, p_source_digest text, p_manifest jsonb, p_owner_clerk_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_location studio.studio_locations%rowtype;
  v_run studio.studio_knowledge_import_runs%rowtype;
  v_snapshot jsonb;
  v_library_snapshot jsonb;
  v_source_text text;
  v_library_text text;
  v_row jsonb;
  v_sidecar jsonb;
  v_sidecar_entry record;
  v_unit jsonb;
  v_unit_entry record;
  v_sidecar_payload jsonb;
  v_unit_position integer := 0;
  v_sidecar_index integer;
  v_matching_sidecars integer;
  v_matching_sidecar jsonb;
  v_time_start numeric;
  v_time_end numeric;
  v_signature text;
  v_counts jsonb;
  v_replayed boolean := false;
begin
  if p_location_id is null or p_source_digest is null or p_source_digest !~ '^[0-9a-f]{64}$'
    or p_owner_clerk_user_id is null or pg_catalog.btrim(p_owner_clerk_user_id) = ''
    or pg_catalog.jsonb_typeof(p_manifest) is distinct from 'object'
    or p_manifest->>'schema' is distinct from 'studio.legacy-knowledge.v1'
    or p_manifest->>'sourceDigest' is distinct from p_source_digest
    or p_manifest->'valid' is distinct from 'true'::jsonb
    or p_manifest->>'mode' is distinct from 'dry-run'
    or p_manifest->'snapshotCheckedUnchanged' is distinct from 'true'::jsonb
    or p_manifest->'mediaReconciled' is distinct from 'false'::jsonb
    or pg_catalog.octet_length(pg_catalog.convert_to(p_manifest::text,'UTF8')) > 419430400
    or pg_catalog.jsonb_typeof(p_manifest->'sourceCanonicalJson') is distinct from 'string'
    or pg_catalog.octet_length(pg_catalog.convert_to(p_manifest->>'sourceCanonicalJson','UTF8')) > 104857600
    or pg_catalog.jsonb_typeof(p_manifest->'topics') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'sources') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'insights') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'evidence') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'reviews') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'sourceUnitSidecars') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'sourceUnits') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'issues') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'counts') is distinct from 'object'
    or exists(select 1 from pg_catalog.jsonb_array_elements(p_manifest->'issues') issue where issue->>'severity'='error')
    or pg_catalog.jsonb_typeof(p_manifest->'librarySource') is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_manifest->'librarySource'->'sourceCanonicalJson') is distinct from 'string'
    or p_manifest->'librarySource'->>'sourceDigest' !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid knowledge import manifest' using errcode = '22023';
  end if;

  if pg_catalog.jsonb_array_length(p_manifest->'topics') > 100000
    or pg_catalog.jsonb_array_length(p_manifest->'sources') > 100000
    or pg_catalog.jsonb_array_length(p_manifest->'insights') > 100000
    or pg_catalog.jsonb_array_length(p_manifest->'evidence') > 100000
    or pg_catalog.jsonb_array_length(p_manifest->'reviews') > 100000
    or pg_catalog.jsonb_array_length(p_manifest->'sourceUnitSidecars') > 10000
    or (select coalesce(pg_catalog.sum(case when pg_catalog.jsonb_typeof(envelope->'payload'->'units')='array'
      then pg_catalog.jsonb_array_length(envelope->'payload'->'units') else 0 end),0)
      from pg_catalog.jsonb_array_elements(p_manifest->'sourceUnitSidecars') envelope) > 250000
    or pg_catalog.jsonb_array_length(p_manifest->'topics') + pg_catalog.jsonb_array_length(p_manifest->'sources')
      + pg_catalog.jsonb_array_length(p_manifest->'insights') + pg_catalog.jsonb_array_length(p_manifest->'evidence')
      + pg_catalog.jsonb_array_length(p_manifest->'reviews')
      + (select coalesce(pg_catalog.sum(case when pg_catalog.jsonb_typeof(envelope->'payload'->'units')='array'
        then pg_catalog.jsonb_array_length(envelope->'payload'->'units') else 0 end),0)
        from pg_catalog.jsonb_array_elements(p_manifest->'sourceUnitSidecars') envelope) > 250000 then
    raise exception 'Knowledge import row limit exceeded' using errcode = '22023';
  end if;

  v_source_text := p_manifest->>'sourceCanonicalJson';
  v_library_text := p_manifest->'librarySource'->>'sourceCanonicalJson';
  if pg_catalog.octet_length(pg_catalog.convert_to(v_library_text,'UTF8')) > 104857600 then
    raise exception 'Library source snapshot exceeds limit' using errcode = '22023';
  end if;
  begin
    v_snapshot := v_source_text::jsonb;
    v_library_snapshot := v_library_text::jsonb;
  exception when others then
    raise exception 'Invalid canonical knowledge source snapshot' using errcode = '22023';
  end;
  if pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_source_text,'UTF8')),'hex') <> p_source_digest
    or pg_catalog.jsonb_typeof(v_snapshot) is distinct from 'object'
    or v_snapshot->'version' is distinct from '1'::jsonb
    or pg_catalog.jsonb_typeof(v_snapshot->'topics') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_snapshot->'sources') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_snapshot->'insights') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_snapshot->'evidence') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_snapshot->'reviews') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_snapshot->'sourceUnits') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_library_snapshot) is distinct from 'object'
    or pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_library_text,'UTF8')),'hex') <> p_manifest->'librarySource'->>'sourceDigest'
    or pg_catalog.jsonb_typeof(v_library_snapshot->'records') is distinct from 'array'
    or p_manifest->'topics' is distinct from v_snapshot->'topics'
    or p_manifest->'sources' is distinct from v_snapshot->'sources'
    or p_manifest->'insights' is distinct from v_snapshot->'insights'
    or p_manifest->'evidence' is distinct from v_snapshot->'evidence'
    or p_manifest->'reviews' is distinct from v_snapshot->'reviews'
    or pg_catalog.jsonb_array_length(p_manifest->'sourceUnitSidecars') <> pg_catalog.jsonb_array_length(v_snapshot->'sourceUnits') then
    raise exception 'Knowledge source snapshot did not reconcile' using errcode = '22023';
  end if;

  -- Serialize location import/replay and recheck owner and imported library snapshot.
  select * into v_location from studio.studio_locations where location_id=p_location_id for update;
  if not found or v_location.app <> 'substo'
    or not exists(select 1 from studio.studio_location_members where location_id=p_location_id
      and location_app='substo' and clerk_user_id=p_owner_clerk_user_id and role='owner') then
    raise exception 'Knowledge import requires the target Substo location owner' using errcode = '42501';
  end if;
  if not exists(select 1 from studio.studio_library_import_runs where location_id=p_location_id
    and source_digest=p_manifest->'librarySource'->>'sourceDigest') then
    raise exception 'The matching library snapshot must be imported first' using errcode = '23503';
  end if;

  -- Every knowledge source must belong to both pinned source exports and an
  -- existing same-location library row. Record kind is deliberately preserved.
  for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'sources') loop
    if pg_catalog.jsonb_typeof(v_row) is distinct from 'object'
      or (v_row->>'id') is null or (v_row->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or not exists(select 1 from pg_catalog.jsonb_array_elements(v_library_snapshot->'records') record_row
        where pg_catalog.lower(record_row->>'id')=pg_catalog.lower(v_row->>'id'))
      or not exists(select 1 from studio.studio_records where location_id=p_location_id and id=(v_row->>'id')::uuid) then
      raise exception 'Knowledge source has no matching imported library record' using errcode = '23503';
    end if;
  end loop;

  -- Validate readiness before replay/conflict handling or any inserts, so a
  -- forged but self-consistent manifest cannot bypass sidecar completeness.
  for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'sources') loop
    if pg_catalog.jsonb_typeof(v_row) is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_row->'id') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_row->'title') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_row->'url') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_row->'platform') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_row->'transcription_id') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_row->'observed_at') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_row->'total_units') is distinct from 'number' or (v_row->>'total_units') !~ '^[0-9]+$'
      or pg_catalog.jsonb_typeof(v_row->'covered_units') is distinct from 'number' or (v_row->>'covered_units') !~ '^[0-9]+$' then
      raise exception 'Invalid knowledge source coverage' using errcode = '22023';
    end if;
    perform (v_row->>'observed_at')::timestamptz;
    if (v_row->>'total_units')::numeric > 2147483647 or (v_row->>'covered_units')::numeric > 2147483647
      or (v_row->>'covered_units')::numeric > (v_row->>'total_units')::numeric then
      raise exception 'Invalid knowledge source coverage' using errcode = '22023';
    end if;
    select pg_catalog.count(*), (pg_catalog.array_agg(value))[1]
      into v_matching_sidecars, v_matching_sidecar
      from pg_catalog.jsonb_array_elements(v_snapshot->'sourceUnits') as envelopes(value)
      where pg_catalog.lower(value->>'recordId') = pg_catalog.lower(v_row->>'id');
    if (v_row->>'total_units')::integer > 0 and v_matching_sidecars = 0 then
      raise exception 'Source sidecar required by exported unit coverage' using errcode = '22023';
    end if;
    if v_matching_sidecars > 1 then
      raise exception 'Multiple source sidecars for one exported source' using errcode = '22023';
    end if;
    if v_matching_sidecars = 1 and (
      pg_catalog.jsonb_typeof(v_matching_sidecar->'payload') is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_matching_sidecar->'payload'->'units') is distinct from 'array'
      or pg_catalog.jsonb_array_length(v_matching_sidecar->'payload'->'units') <> (v_row->>'total_units')::integer
      or v_matching_sidecar->'payload'->>'transcriptionId' is distinct from v_row->>'transcription_id') then
      raise exception 'Source sidecar count or transcription did not reconcile' using errcode = '22023';
    end if;
  end loop;

  v_signature := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_manifest::text,'UTF8')),'hex');
  select * into v_run from studio.studio_knowledge_import_runs where location_id=p_location_id and source_digest=p_source_digest;
  if found then
    if v_run.manifest_signature <> v_signature then raise exception 'Snapshot digest belongs to a different manifest' using errcode = '23505'; end if;
    v_replayed := true;
  else
    for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'topics') loop
      if pg_catalog.jsonb_typeof(v_row) is distinct from 'object' or (v_row->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or pg_catalog.jsonb_typeof(v_row->'name') is distinct from 'string' or pg_catalog.btrim(v_row->>'name')=''
        or pg_catalog.jsonb_typeof(v_row->'name_key') is distinct from 'string' or pg_catalog.btrim(v_row->>'name_key')=''
        or pg_catalog.jsonb_typeof(v_row->'summary') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'created_at') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'updated_at') is distinct from 'string' then
        raise exception 'Invalid knowledge topic' using errcode = '22023';
      end if;
      perform (v_row->>'created_at')::timestamptz;
      perform (v_row->>'updated_at')::timestamptz;
      insert into studio.studio_knowledge_topics(location_id,id,payload) values(p_location_id,(v_row->>'id')::uuid,v_row);
    end loop;
    for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'sources') loop
      insert into studio.studio_knowledge_sources(location_id,id,payload,total_units,covered_units)
        values(p_location_id,(v_row->>'id')::uuid,v_row,(v_row->>'total_units')::integer,(v_row->>'covered_units')::integer);
    end loop;
    for v_sidecar_entry in select value,ordinal from pg_catalog.jsonb_array_elements(p_manifest->'sourceUnitSidecars') with ordinality as rows(value,ordinal) order by ordinal loop
      v_sidecar := v_sidecar_entry.value;
      v_sidecar_index := v_sidecar_entry.ordinal::integer;
      v_sidecar_payload := v_snapshot->'sourceUnits'->(v_sidecar_index-1);
      if pg_catalog.jsonb_typeof(v_sidecar) is distinct from 'object'
        or v_sidecar ? 'invalid'
        or pg_catalog.lower(v_sidecar->>'source_id') is distinct from pg_catalog.lower(v_sidecar_payload->>'recordId')
        or v_sidecar->>'transcription_id' is distinct from v_sidecar_payload->'payload'->>'transcriptionId'
        or v_sidecar->'payload' is distinct from v_sidecar_payload then
        raise exception 'Sidecar envelope did not reconcile' using errcode = '22023';
      end if;
      insert into studio.studio_knowledge_source_unit_sidecars(location_id,id,source_id,transcription_id,payload)
        values(p_location_id,(v_sidecar->>'id')::uuid,(v_sidecar->>'source_id')::uuid,v_sidecar->>'transcription_id',v_sidecar->'payload');
      for v_unit_entry in select value,ordinal from pg_catalog.jsonb_array_elements(v_sidecar_payload->'payload'->'units') with ordinality as units(value,ordinal) order by ordinal loop
        v_unit := v_unit_entry.value;
        if pg_catalog.jsonb_typeof(v_unit) is distinct from 'object'
          or pg_catalog.jsonb_typeof(v_unit->'text') is distinct from 'string'
          or (v_unit ? 'start' and pg_catalog.jsonb_typeof(v_unit->'start') is distinct from 'number')
          or (v_unit ? 'end' and pg_catalog.jsonb_typeof(v_unit->'end') is distinct from 'number')
          or (v_unit ? 'frameFile' and pg_catalog.jsonb_typeof(v_unit->'frameFile') is distinct from 'string') then
          raise exception 'Invalid source unit fields' using errcode = '22023';
        end if;
        v_time_start := case when pg_catalog.jsonb_typeof(v_unit->'start')='number' then (v_unit->>'start')::numeric else null end;
        v_time_end := case when pg_catalog.jsonb_typeof(v_unit->'end')='number' then (v_unit->>'end')::numeric else null end;
        if v_time_start < 0 or v_time_end < 0 or (v_time_start is not null and v_time_end is not null and v_time_end < v_time_start) then
          raise exception 'Invalid source unit time range' using errcode = '22023';
        end if;
        v_row := p_manifest->'sourceUnits'->v_unit_position;
        if pg_catalog.jsonb_typeof(v_row) is distinct from 'object'
          or v_row->>'sidecar_id' is distinct from v_sidecar->>'id'
          or pg_catalog.lower(v_row->>'source_id') is distinct from pg_catalog.lower(v_sidecar->>'source_id')
          or v_row->>'transcription_id' is distinct from v_sidecar->>'transcription_id'
          or v_row->>'unit_index' is distinct from (v_unit_entry.ordinal-1)::text
          or v_row->'payload'->'unit' is distinct from v_unit then
          raise exception 'Source unit did not reconcile with its sidecar' using errcode = '22023';
        end if;
        insert into studio.studio_knowledge_source_units(location_id,id,sidecar_id,source_id,transcription_id,unit_index,payload)
          values(p_location_id,(v_row->>'id')::uuid,(v_row->>'sidecar_id')::uuid,(v_row->>'source_id')::uuid,v_row->>'transcription_id',(v_row->>'unit_index')::integer,v_row->'payload');
        v_unit_position := v_unit_position + 1;
      end loop;
    end loop;
    if v_unit_position <> pg_catalog.jsonb_array_length(p_manifest->'sourceUnits') then
      raise exception 'Source unit count did not reconcile' using errcode = '22023';
    end if;
    for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'insights') loop
      if pg_catalog.jsonb_typeof(v_row->'kind') is distinct from 'string'
        or coalesce(v_row->>'kind' not in ('claim','method','example','question','objection','content_pattern'),true)
        or pg_catalog.jsonb_typeof(v_row->'status') is distinct from 'string'
        or coalesce(v_row->>'status' not in ('pending','approved','rejected'),true)
        or pg_catalog.jsonb_typeof(v_row->'statement') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'created_at') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'updated_at') is distinct from 'string' then
        raise exception 'Invalid knowledge insight state' using errcode = '22023';
      end if;
      perform (v_row->>'created_at')::timestamptz;
      perform (v_row->>'updated_at')::timestamptz;
      insert into studio.studio_knowledge_insights(location_id,id,source_id,topic_id,status,statement,payload)
        values(p_location_id,(v_row->>'id')::uuid,(v_row->>'source_id')::uuid,
          case when pg_catalog.jsonb_typeof(v_row->'topic_id')='null' then null else (v_row->>'topic_id')::uuid end,
          v_row->>'status',v_row->>'statement',v_row);
    end loop;
    for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'evidence') loop
      if pg_catalog.jsonb_typeof(v_row) is distinct from 'object'
        or pg_catalog.jsonb_typeof(v_row->'quote') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'frame_file') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'source_url') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'observed_at') is distinct from 'string'
        or (v_row ? 'start_sec' and pg_catalog.jsonb_typeof(v_row->'start_sec') not in ('number','null'))
        or (v_row ? 'end_sec' and pg_catalog.jsonb_typeof(v_row->'end_sec') not in ('number','null')) then
        raise exception 'Invalid knowledge evidence fields' using errcode = '22023';
      end if;
      perform (v_row->>'observed_at')::timestamptz;
      v_time_start := case when pg_catalog.jsonb_typeof(v_row->'start_sec')='number' then (v_row->>'start_sec')::numeric else null end;
      v_time_end := case when pg_catalog.jsonb_typeof(v_row->'end_sec')='number' then (v_row->>'end_sec')::numeric else null end;
      if v_time_start < 0 or v_time_end < 0 or (v_time_start is not null and v_time_end is not null and v_time_end < v_time_start) then
        raise exception 'Invalid knowledge evidence time range' using errcode = '22023';
      end if;
      insert into studio.studio_knowledge_evidence(location_id,id,insight_id,source_id,payload)
        values(p_location_id,(v_row->>'id')::uuid,(v_row->>'insight_id')::uuid,(v_row->>'source_id')::uuid,v_row);
    end loop;
    for v_row in select value from pg_catalog.jsonb_array_elements(v_snapshot->'reviews') loop
      if pg_catalog.jsonb_typeof(v_row) is distinct from 'object'
        or pg_catalog.jsonb_typeof(v_row->'action') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'previous_status') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'new_status') is distinct from 'string'
        or pg_catalog.jsonb_typeof(v_row->'at') is distinct from 'string'
        or coalesce(v_row->>'action' not in ('approve','reject','reopen'),true)
        or coalesce(v_row->>'previous_status' not in ('pending','approved','rejected'),true)
        or coalesce(v_row->>'new_status' not in ('pending','approved','rejected'),true)
        or (v_row->>'action'='approve' and v_row->>'new_status' is distinct from 'approved')
        or (v_row->>'action'='reject' and v_row->>'new_status' is distinct from 'rejected')
        or (v_row->>'action'='reopen' and v_row->>'new_status' is distinct from 'pending') then
        raise exception 'Invalid knowledge review transition' using errcode = '22023';
      end if;
      perform (v_row->>'at')::timestamptz;
      insert into studio.studio_knowledge_reviews(location_id,id,insight_id,payload)
        values(p_location_id,(v_row->>'id')::uuid,(v_row->>'insight_id')::uuid,v_row);
    end loop;

    select pg_catalog.jsonb_build_object(
      'topics',(select pg_catalog.count(*) from studio.studio_knowledge_topics where location_id=p_location_id and id in (select (value->>'id')::uuid from pg_catalog.jsonb_array_elements(v_snapshot->'topics'))),
      'sources',(select pg_catalog.count(*) from studio.studio_knowledge_sources where location_id=p_location_id and id in (select (value->>'id')::uuid from pg_catalog.jsonb_array_elements(v_snapshot->'sources'))),
      'insights',pg_catalog.jsonb_array_length(v_snapshot->'insights'),
      'evidence',pg_catalog.jsonb_array_length(v_snapshot->'evidence'),
      'reviews',pg_catalog.jsonb_array_length(v_snapshot->'reviews'),
      'sourceUnitSidecars',pg_catalog.jsonb_array_length(p_manifest->'sourceUnitSidecars'),
      'sourceUnits',pg_catalog.jsonb_array_length(p_manifest->'sourceUnits'),
      'pending',(select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_snapshot->'insights') x where x->>'status'='pending'),
      'approved',(select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_snapshot->'insights') x where x->>'status'='approved'),
      'rejected',(select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(v_snapshot->'insights') x where x->>'status'='rejected'),
      'uncoveredUnits',(select coalesce(pg_catalog.sum((x->>'total_units')::integer-(x->>'covered_units')::integer),0) from pg_catalog.jsonb_array_elements(v_snapshot->'sources') x)
    ) into v_counts;
    if p_manifest->'counts' is distinct from v_counts then raise exception 'Knowledge import counts did not reconcile' using errcode = '22023'; end if;
    insert into studio.studio_knowledge_import_runs(location_id,source_digest,library_source_digest,manifest_signature,counts,imported_by_clerk_user_id)
      values(p_location_id,p_source_digest,p_manifest->'librarySource'->>'sourceDigest',v_signature,v_counts,p_owner_clerk_user_id)
      returning * into v_run;
  end if;
  return pg_catalog.jsonb_build_object('runId',v_run.id,'locationId',p_location_id,'sourceDigest',p_source_digest,'counts',v_run.counts,'replayed',v_replayed);
end;
$_$;

--
-- Name: studio_import_library(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_import_library(p_location_id text, p_source_digest text, p_manifest jsonb, p_owner_clerk_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_location studio.studio_locations%rowtype;
  v_run studio.studio_library_import_runs%rowtype;
  v_record jsonb;
  v_file jsonb;
  v_link text;
  v_counts jsonb;
  v_signature text;
  v_source_snapshot jsonb;
  v_source_text text;
  v_replayed boolean := false;
begin
  if p_location_id is null or p_source_digest is null or p_source_digest !~ '^[0-9a-f]{64}$'
    or p_owner_clerk_user_id is null or pg_catalog.btrim(p_owner_clerk_user_id) = ''
    or pg_catalog.jsonb_typeof(p_manifest) is distinct from 'object'
    or p_manifest->>'schema' is distinct from 'studio.legacy-library.v1'
    or p_manifest->>'sourceDigest' is distinct from p_source_digest
    or pg_catalog.jsonb_typeof(p_manifest->'sourceCanonicalJson') is distinct from 'string'
    or pg_catalog.octet_length(pg_catalog.convert_to(p_manifest->>'sourceCanonicalJson','UTF8')) > 104857600
    or p_manifest->'valid' is distinct from 'true'::jsonb
    or p_manifest->'mediaReady' is distinct from 'true'::jsonb
    or p_manifest->>'mode' is distinct from 'dry-run'
    or pg_catalog.jsonb_typeof(p_manifest->'records') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest->'files') is distinct from 'array' then
    raise exception 'Invalid library import manifest' using errcode = '22023';
  end if;

  v_source_text := p_manifest->>'sourceCanonicalJson';
  begin
    v_source_snapshot := v_source_text::jsonb;
  exception when others then
    raise exception 'Invalid canonical source snapshot' using errcode = '22023';
  end;
  if pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_source_text,'UTF8')),'hex') <> p_source_digest
    or pg_catalog.jsonb_typeof(v_source_snapshot) is distinct from 'object'
    or v_source_snapshot->'version' is distinct from '1'::jsonb
    or pg_catalog.jsonb_typeof(v_source_snapshot->'records') is distinct from 'array'
    or pg_catalog.jsonb_typeof(v_source_snapshot->'files') is distinct from 'array'
    or pg_catalog.jsonb_array_length(v_source_snapshot->'records') <> pg_catalog.jsonb_array_length(p_manifest->'records')
    or pg_catalog.jsonb_array_length(v_source_snapshot->'files') <> pg_catalog.jsonb_array_length(p_manifest->'files') then
    raise exception 'Source digest or snapshot shape did not reconcile' using errcode = '22023';
  end if;
  -- Validate snapshot-to-wrapper fidelity before the idempotent replay branch
  -- too; a retry must not make a tampered wrapper look like the old import.
  for v_record in select value from pg_catalog.jsonb_array_elements(p_manifest->'records') loop
    if pg_catalog.jsonb_typeof(v_record) is distinct from 'object'
      or (v_record->>'id') is null or (v_record->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_record->>'kind') is null or (v_record->>'kind') not in ('reference','channel','content')
      or pg_catalog.jsonb_typeof(v_record->'title') is distinct from 'string' or pg_catalog.btrim(v_record->>'title') = ''
      or pg_catalog.jsonb_typeof(v_record->'payload') is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_record->'linkedIds') is distinct from 'array'
      or pg_catalog.lower(v_record->'payload'->>'id') is distinct from v_record->>'id'
      or v_record->'payload'->>'kind' is distinct from v_record->>'kind'
      or v_record->'payload'->>'title' is distinct from v_record->>'title'
      or pg_catalog.jsonb_typeof(coalesce(v_record->'payload'->'linkedIds','[]'::jsonb)) is distinct from 'array'
      or v_record->'linkedIds' is distinct from (
        select coalesce(pg_catalog.jsonb_agg(pg_catalog.lower(value) order by ordinal),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements_text(coalesce(v_record->'payload'->'linkedIds','[]'::jsonb)) with ordinality as links(value,ordinal)
      )
      or not exists(select 1 from pg_catalog.jsonb_array_elements(v_source_snapshot->'records') source_row
        where pg_catalog.lower(source_row->>'id')=v_record->>'id' and source_row=v_record->'payload') then
      raise exception 'Normalized record does not match canonical source snapshot' using errcode = '22023';
    end if;
  end loop;
  for v_file in select value from pg_catalog.jsonb_array_elements(p_manifest->'files') loop
    if pg_catalog.jsonb_typeof(v_file) is distinct from 'object'
      or (v_file->>'id') is null or (v_file->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_file->>'recordId') is null or (v_file->>'recordId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or pg_catalog.jsonb_typeof(v_file->'payload') is distinct from 'object'
      or pg_catalog.lower(v_file->'payload'->>'id') is distinct from v_file->>'id'
      or pg_catalog.lower(v_file->'payload'->>'recordId') is distinct from v_file->>'recordId'
      or not exists(select 1 from pg_catalog.jsonb_array_elements(v_source_snapshot->'files') source_row
        where pg_catalog.lower(source_row->>'id')=v_file->>'id' and source_row=v_file->'payload') then
      raise exception 'Normalized attachment does not match canonical source snapshot' using errcode = '22023';
    end if;
  end loop;

  -- Serialize imports within this location, then recheck the explicit owner.
  select * into v_location from studio.studio_locations where location_id=p_location_id for update;
  if not found or v_location.app <> 'substo'
    or not exists(select 1 from studio.studio_location_members where location_id=p_location_id
      and location_app='substo' and clerk_user_id=p_owner_clerk_user_id and role='owner') then
    raise exception 'Import requires the target Substo location owner' using errcode = '42501';
  end if;

  v_signature := pg_catalog.md5(p_manifest::text);
  select * into v_run from studio.studio_library_import_runs
    where location_id=p_location_id and source_digest=p_source_digest;
  if found then
    if v_run.manifest_signature <> v_signature then
      raise exception 'Snapshot digest already belongs to a different manifest' using errcode = '23505';
    end if;
    -- Never reapply original payload over edits made after a successful import.
    v_replayed := true;
  else
    for v_record in select value from pg_catalog.jsonb_array_elements(p_manifest->'records') loop
      if pg_catalog.jsonb_typeof(v_record) is distinct from 'object'
        or (v_record->>'id') is null or (v_record->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or (v_record->>'kind') is null or (v_record->>'kind') not in ('reference','channel','content')
        or pg_catalog.jsonb_typeof(v_record->'title') is distinct from 'string' or pg_catalog.btrim(v_record->>'title') = ''
        or pg_catalog.jsonb_typeof(v_record->'payload') is distinct from 'object'
        or pg_catalog.jsonb_typeof(v_record->'linkedIds') is distinct from 'array'
        or pg_catalog.lower(v_record->'payload'->>'id') is distinct from v_record->>'id'
        or v_record->'payload'->>'kind' is distinct from v_record->>'kind'
        or v_record->'payload'->>'title' is distinct from v_record->>'title' then
        raise exception 'Invalid normalized library record' using errcode = '22023';
      end if;
      if not exists(select 1 from pg_catalog.jsonb_array_elements(v_source_snapshot->'records') source_row
        where pg_catalog.lower(source_row->>'id')=v_record->>'id' and source_row=v_record->'payload') then
        raise exception 'Normalized record does not match canonical source snapshot' using errcode = '22023';
      end if;
      if pg_catalog.jsonb_typeof(coalesce(v_record->'payload'->'linkedIds','[]'::jsonb)) is distinct from 'array' then
        raise exception 'Invalid source relationships' using errcode = '22023';
      end if;
      if v_record->'linkedIds' is distinct from (
        select coalesce(pg_catalog.jsonb_agg(pg_catalog.lower(value) order by ordinal),'[]'::jsonb)
        from pg_catalog.jsonb_array_elements_text(coalesce(v_record->'payload'->'linkedIds','[]'::jsonb)) with ordinality as links(value,ordinal)
      ) then
        raise exception 'Normalized relationships do not match source payload' using errcode = '22023';
      end if;
      insert into studio.studio_records(location_id,id,kind,title,payload,legacy_payload,created_by_clerk_user_id)
        values(p_location_id,(v_record->>'id')::uuid,v_record->>'kind',v_record->>'title',v_record->'payload',v_record->'payload',p_owner_clerk_user_id);
    end loop;

    for v_record in select value from pg_catalog.jsonb_array_elements(p_manifest->'records') loop
      for v_link in select value from pg_catalog.jsonb_array_elements_text(v_record->'linkedIds') loop
        if v_link is null or v_link !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or not exists(select 1 from pg_catalog.jsonb_array_elements(p_manifest->'records') r where r->>'id'=v_link) then
          raise exception 'Link target is outside the import snapshot' using errcode = '22023';
        end if;
        insert into studio.studio_record_links(location_id,source_id,target_id)
          values(p_location_id,(v_record->>'id')::uuid,v_link::uuid);
      end loop;
    end loop;

    for v_file in select value from pg_catalog.jsonb_array_elements(p_manifest->'files') loop
      if pg_catalog.jsonb_typeof(v_file) is distinct from 'object'
        or (v_file->>'id') is null or (v_file->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or (v_file->>'recordId') is null or (v_file->>'recordId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or pg_catalog.jsonb_typeof(v_file->'payload') is distinct from 'object'
        or pg_catalog.lower(v_file->'payload'->>'id') is distinct from v_file->>'id'
        or pg_catalog.lower(v_file->'payload'->>'recordId') is distinct from v_file->>'recordId'
        or not exists(select 1 from pg_catalog.jsonb_array_elements(p_manifest->'records') r where r->>'id'=v_file->>'recordId') then
        raise exception 'Invalid normalized attachment metadata' using errcode = '22023';
      end if;
      if not exists(select 1 from pg_catalog.jsonb_array_elements(v_source_snapshot->'files') source_row
        where pg_catalog.lower(source_row->>'id')=v_file->>'id' and source_row=v_file->'payload') then
        raise exception 'Normalized attachment does not match canonical source snapshot' using errcode = '22023';
      end if;
      insert into studio.studio_legacy_files(location_id,id,record_id,payload)
        values(p_location_id,(v_file->>'id')::uuid,(v_file->>'recordId')::uuid,v_file->'payload');
    end loop;

    select pg_catalog.jsonb_build_object(
      'records',pg_catalog.count(*),
      'library',pg_catalog.count(*) filter(where r->>'kind'='reference'),
      'channels',pg_catalog.count(*) filter(where r->>'kind'='channel'),
      'content',pg_catalog.count(*) filter(where r->>'kind'='content'),
      'files',pg_catalog.jsonb_array_length(p_manifest->'files'),
      'links',coalesce(pg_catalog.sum(pg_catalog.jsonb_array_length(r->'linkedIds')),0)
    ) into v_counts from pg_catalog.jsonb_array_elements(p_manifest->'records') r;
    if p_manifest->'counts' is distinct from v_counts then
      raise exception 'Import counts did not reconcile' using errcode = '22023';
    end if;
    insert into studio.studio_library_import_runs(location_id,source_digest,manifest_signature,counts,media_pending,imported_by_clerk_user_id)
      values(p_location_id,p_source_digest,v_signature,v_counts,pg_catalog.jsonb_array_length(p_manifest->'files'),p_owner_clerk_user_id)
      returning * into v_run;
  end if;

  return pg_catalog.jsonb_build_object('runId',v_run.id,'locationId',p_location_id,'sourceDigest',p_source_digest,
    'counts',v_run.counts,'mediaPending',v_run.media_pending,'replayed',v_replayed);
end;
$_$;

--
-- Name: studio_import_schedules(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_import_schedules(p_location_id text, p_source_digest text, p_manifest jsonb, p_owner_clerk_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_location studio.studio_locations%rowtype;
  v_import studio.studio_schedule_import_runs%rowtype;
  v_snapshot jsonb;
  v_text text;
  v_signature text;
  v_entry record;
  v_row jsonb;
  v_expected jsonb;
  v_counts jsonb;
  v_replayed boolean := false;
begin
  if p_location_id is null or p_source_digest is null or p_source_digest !~ '^[0-9a-f]{64}$'
    or p_owner_clerk_user_id is null or btrim(p_owner_clerk_user_id) = ''
    or jsonb_typeof(p_manifest) is distinct from 'object'
    or p_manifest->>'schema' is distinct from 'studio.legacy-schedules.v1'
    or p_manifest->>'sourceDigest' is distinct from p_source_digest
    or p_manifest->>'mode' is distinct from 'dry-run'
    or p_manifest->'valid' is distinct from 'true'::jsonb
    or p_manifest->'snapshotCheckedUnchanged' is distinct from 'true'::jsonb
    or p_manifest->'executionEnabled' is distinct from 'false'::jsonb
    or p_manifest->'applySupported' is distinct from 'false'::jsonb
    or jsonb_typeof(p_manifest->'sourceCanonicalJson') is distinct from 'string'
    or jsonb_typeof(p_manifest->'schedules') is distinct from 'array'
    or jsonb_typeof(p_manifest->'runs') is distinct from 'array'
    or jsonb_typeof(p_manifest->'issues') is distinct from 'array'
    or jsonb_typeof(p_manifest->'counts') is distinct from 'object'
    or jsonb_typeof(p_manifest->'sourceFiles') is distinct from 'array'
    or octet_length(convert_to(p_manifest::text,'UTF8')) > 104857600 then
    raise exception 'Invalid schedule import manifest' using errcode = '22023';
  end if;
  if exists(select 1 from jsonb_array_elements(p_manifest->'issues') i where i->>'severity'='error') then
    raise exception 'Schedule manifest has unresolved errors' using errcode = '22023';
  end if;
  if jsonb_array_length(p_manifest->'sourceFiles') <> 1
    or p_manifest->'sourceFiles'->0->>'relativePath' is distinct from 'schedules.json'
    or jsonb_typeof(p_manifest->'sourceFiles'->0->'sha256') is distinct from 'string'
    or p_manifest->'sourceFiles'->0->>'sha256' !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(p_manifest->'sourceFiles'->0->'bytes') is distinct from 'number' then
    raise exception 'Invalid schedule preview evidence' using errcode = '22023';
  end if;
  if (p_manifest->'sourceFiles'->0->>'bytes')::numeric < 1
    or (p_manifest->'sourceFiles'->0->>'bytes')::numeric > 20971520
    or trunc((p_manifest->'sourceFiles'->0->>'bytes')::numeric) <> (p_manifest->'sourceFiles'->0->>'bytes')::numeric then
    raise exception 'Invalid schedule source byte count' using errcode = '22023';
  end if;
  v_text := p_manifest->>'sourceCanonicalJson';
  if octet_length(convert_to(v_text,'UTF8')) > 20971520 or encode(sha256(convert_to(v_text,'UTF8')),'hex') <> p_source_digest then
    raise exception 'Schedule source digest or size mismatch' using errcode = '22023';
  end if;
  begin v_snapshot := v_text::jsonb;
  exception when others then raise exception 'Invalid schedule source JSON' using errcode = '22023'; end;
  if jsonb_typeof(v_snapshot) is distinct from 'object' or v_snapshot->'version' is distinct from '1'::jsonb
    or jsonb_typeof(v_snapshot->'schedules') is distinct from 'array' or jsonb_typeof(v_snapshot->'runs') is distinct from 'array' then
    raise exception 'Unsupported schedule source shape' using errcode = '22023';
  end if;
  if jsonb_array_length(v_snapshot->'schedules') > 10000 or jsonb_array_length(v_snapshot->'runs') > 50000
    or jsonb_array_length(v_snapshot->'schedules') <> jsonb_array_length(p_manifest->'schedules')
    or jsonb_array_length(v_snapshot->'runs') <> jsonb_array_length(p_manifest->'runs') then
    raise exception 'Schedule row counts do not reconcile' using errcode = '22023';
  end if;

  -- Serialize imports and hold exact owner membership through the transaction.
  select * into v_location from studio.studio_locations where location_id=p_location_id for update;
  if not found or v_location.app <> 'substo' then
    raise exception 'Import requires a standalone Substo location' using errcode = '42501';
  end if;
  perform 1 from studio.studio_location_members where location_id=p_location_id
    and location_app='substo' and clerk_user_id=p_owner_clerk_user_id and role='owner' for share;
  if not found then raise exception 'Import requires exact location owner' using errcode = '42501'; end if;

  v_signature := encode(sha256(convert_to(p_manifest::text,'UTF8')),'hex');
  select * into v_import from studio.studio_schedule_import_runs where location_id=p_location_id and source_digest=p_source_digest;
  if found then
    if v_import.manifest_signature <> v_signature then
      raise exception 'Source digest belongs to a different manifest' using errcode = '23505';
    end if;
    v_replayed := true;
  else
    select jsonb_build_object('schedules',jsonb_array_length(v_snapshot->'schedules'),'runs',jsonb_array_length(v_snapshot->'runs'),
      'legacyEnabled',(select count(*) from jsonb_array_elements(v_snapshot->'schedules') r where r->'enabled'='true'::jsonb),
      'discovery',(select count(*) from jsonb_array_elements(v_snapshot->'schedules') r where r->>'presetId'='youtube-discovery'),
      'inFlightRuns',(select count(*) from jsonb_array_elements(v_snapshot->'runs') r where r->>'status' in ('running','queued')))
      into v_counts;
    if p_manifest->'counts' is distinct from v_counts then raise exception 'Schedule counts mismatch' using errcode = '22023'; end if;
    insert into studio.studio_schedule_import_runs(location_id,source_digest,manifest_signature,source_canonical_json,preview_evidence,counts,imported_by_clerk_user_id)
      values(p_location_id,p_source_digest,v_signature,v_text,jsonb_build_object('sourceFiles',p_manifest->'sourceFiles','issues',p_manifest->'issues','snapshotCheckedUnchanged',true),v_counts,p_owner_clerk_user_id) returning * into v_import;

    for v_entry in select value,ordinality from jsonb_array_elements(v_snapshot->'schedules') with ordinality loop
      v_row := v_entry.value;
      if jsonb_typeof(v_row) is distinct from 'object'
        or jsonb_typeof(v_row->'id') is distinct from 'string' or lower(v_row->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(v_row->'presetId') is distinct from 'string' or v_row->>'presetId' not in ('youtube-discovery','idea-review','script-brief')
        or jsonb_typeof(v_row->'query') is distinct from 'string'
        or jsonb_typeof(v_row->'intervalHours') is distinct from 'number' or v_row->'intervalHours' not in ('24'::jsonb,'168'::jsonb)
        or jsonb_typeof(v_row->'dailyTime') is distinct from 'string'
        or v_row->>'timeZone' is distinct from 'Asia/Nicosia'
        or jsonb_typeof(v_row->'enabled') is distinct from 'boolean'
        or (v_row ? 'autoKnowledgeScan' and jsonb_typeof(v_row->'autoKnowledgeScan') is distinct from 'boolean')
        or not studio.studio_schedule_import_timestamp_valid(v_row->'createdAt')
        or not studio.studio_schedule_import_timestamp_valid(v_row->'updatedAt')
        or not studio.studio_schedule_import_timestamp_valid(v_row->'nextRunAt')
        or (v_row ? 'lastRunAt' and not studio.studio_schedule_import_timestamp_valid(v_row->'lastRunAt')) then
        raise exception 'Invalid legacy schedule definition' using errcode = '22023';
      end if;
      if (v_row->>'updatedAt')::timestamptz < (v_row->>'createdAt')::timestamptz then
        raise exception 'Invalid schedule timestamp order' using errcode = '22023';
      end if;
      v_expected := jsonb_build_object('sourceIndex',v_entry.ordinality-1,'id',lower(v_row->>'id'),'payload',v_row,
        'draft',jsonb_build_object('presetId',v_row->'presetId','query',v_row->'query','intervalHours',v_row->'intervalHours','dailyTime',v_row->'dailyTime'));
      if p_manifest->'schedules'->(v_entry.ordinality::integer-1) is distinct from v_expected then
        raise exception 'Schedule projection differs from source' using errcode = '22023';
      end if;
      insert into studio.studio_schedules(location_id,id,preset_id,focus,interval_hours,daily_time,created_at,updated_at,updated_by)
        values(p_location_id,(v_row->>'id')::uuid,v_row->>'presetId',v_row->>'query',(v_row->>'intervalHours')::integer,v_row->>'dailyTime',
          (v_row->>'createdAt')::timestamptz,(v_row->>'updatedAt')::timestamptz,p_owner_clerk_user_id);
      insert into studio.studio_schedule_legacy_definitions(location_id,id,import_run_id,source_index,payload)
        values(p_location_id,(v_row->>'id')::uuid,v_import.id,v_entry.ordinality-1,v_row);
    end loop;
    for v_entry in select value,ordinality from jsonb_array_elements(v_snapshot->'runs') with ordinality loop
      v_row := v_entry.value;
      if jsonb_typeof(v_row) is distinct from 'object'
        or jsonb_typeof(v_row->'id') is distinct from 'string' or lower(v_row->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(v_row->'scheduleId') is distinct from 'string' or lower(v_row->>'scheduleId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or jsonb_typeof(v_row->'presetId') is distinct from 'string' or v_row->>'presetId' not in ('youtube-discovery','idea-review','script-brief')
        or jsonb_typeof(v_row->'status') is distinct from 'string' or v_row->>'status' not in ('running','queued','completed','failed','timeout','interrupted')
        or jsonb_typeof(v_row->'output') is distinct from 'string' or jsonb_typeof(v_row->'error') is distinct from 'string'
        or (v_row ? 'jobId' and jsonb_typeof(v_row->'jobId') is distinct from 'string')
        or not studio.studio_schedule_import_timestamp_valid(v_row->'startedAt')
        or (v_row->'completedAt' is distinct from 'null'::jsonb and not studio.studio_schedule_import_timestamp_valid(v_row->'completedAt'))
        or (v_row->>'status' not in ('running','queued') and v_row->'completedAt'='null'::jsonb) then
        raise exception 'Invalid legacy schedule history' using errcode = '22023';
      end if;
      if v_row->'completedAt' <> 'null'::jsonb and (v_row->>'completedAt')::timestamptz < (v_row->>'startedAt')::timestamptz then
        raise exception 'Invalid run timestamp order' using errcode = '22023';
      end if;
      v_expected := jsonb_build_object('sourceIndex',v_entry.ordinality-1,'id',lower(v_row->>'id'),'scheduleId',lower(v_row->>'scheduleId'),'payload',v_row);
      if p_manifest->'runs'->(v_entry.ordinality::integer-1) is distinct from v_expected then
        raise exception 'Run projection differs from source' using errcode = '22023';
      end if;
      insert into studio.studio_schedule_legacy_runs(location_id,id,schedule_id,import_run_id,source_index,payload)
        values(p_location_id,(v_row->>'id')::uuid,(v_row->>'scheduleId')::uuid,v_import.id,v_entry.ordinality-1,v_row);
    end loop;
    if (select count(*) from studio.studio_schedule_legacy_definitions where location_id=p_location_id and import_run_id=v_import.id) <> (v_counts->>'schedules')::integer
      or (select count(*) from studio.studio_schedule_legacy_runs where location_id=p_location_id and import_run_id=v_import.id) <> (v_counts->>'runs')::integer then
      raise exception 'Stored schedule counts mismatch' using errcode = '22023';
    end if;
  end if;
  return jsonb_build_object('runId',v_import.id,'locationId',p_location_id,'sourceDigest',p_source_digest,
    'counts',v_import.counts,'replayed',v_replayed,'executionEnabled',false);
end;
$_$;

--
-- Name: studio_knowledge_extraction_inputs(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_knowledge_extraction_inputs(p_location_id text, p_actor_app text, p_clerk_user_id text, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r studio.studio_records%rowtype; inputs jsonb:='[]'; field text; item record;
begin
 perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
 select * into r from studio.studio_records where location_id=p_location_id and id=p_source_id;
 if not found or r.archived or r.kind not in ('reference','content') then raise exception 'Source unavailable' using errcode='22023'; end if;
 foreach field in array array['transcript','notes','script'] loop
  if jsonb_typeof(r.payload->field)='string' and r.payload->>field !~ '^[[:space:]]*$' then
   inputs:=inputs||jsonb_build_array(jsonb_build_object('mode','record_text','inputId',field,'label','Saved '||field,'totalUnits',ceil(char_length(r.payload->>field)::numeric/2000)::integer));
  end if;
 end loop;
 for item in select transcription_id,max(unit_index)+1 as n from studio.studio_knowledge_source_units where location_id=p_location_id and source_id=p_source_id group by transcription_id order by transcription_id limit 20 loop
  inputs:=inputs||jsonb_build_array(jsonb_build_object('mode','source_units','inputId',item.transcription_id,'label','Imported units: '||item.transcription_id,'totalUnits',item.n));
 end loop;
 for item in select t.upload_id,ceil(char_length(t.text)::numeric/2000)::integer as n,u.original_filename from studio.studio_transcripts t join studio.studio_uploads u on u.id=t.upload_id and u.location_id=t.location_id
  where t.location_id=p_location_id and u.record_id=p_source_id and u.status='uploaded' and char_length(t.text)>0 order by t.created_at desc limit 20 loop
  inputs:=inputs||jsonb_build_array(jsonb_build_object('mode','upload_transcript','inputId',item.upload_id,'label','Upload transcript: '||item.original_filename,'totalUnits',item.n));
 end loop;
 return jsonb_build_object('source',jsonb_build_object('id',r.id,'version',r.version,'title',r.title),'inputs',inputs);
end; $_$;

--
-- Name: studio_knowledge_extraction_state(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_knowledge_extraction_state(p_location_id text, p_actor_app text, p_clerk_user_id text, p_review_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare snapshot jsonb; stale boolean;
begin
 perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
 select r.snapshot,r.stale_at_completion into snapshot,stale from studio.studio_idea_reviews r where r.id=p_review_id and r.location_id=p_location_id and r.workflow='knowledge_extract';
 if not found then raise exception 'Extraction not found' using errcode='22023'; end if;
 return jsonb_build_object('stale',coalesce(stale,false) or not studio.studio_knowledge_snapshot_current(p_location_id,snapshot),
  'findings',coalesce((select jsonb_agg(jsonb_build_object('findingIndex',f.finding_index,'insightId',f.insight_id,'reused',f.reused,'status',i.status) order by f.finding_index)
   from studio.studio_knowledge_extraction_findings f join studio.studio_knowledge_insights i on i.location_id=f.location_id and i.id=f.insight_id
   where f.location_id=p_location_id and f.review_id=p_review_id),'[]'::jsonb));
end; $$;

--
-- Name: studio_knowledge_frame_matches(text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_knowledge_frame_matches(p_location_id text, p_ref_kind text, p_ref_id uuid, p_frame_file text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_ref_kind
    when 'evidence' then exists(select 1 from studio.studio_knowledge_evidence
      where location_id=p_location_id and id=p_ref_id and payload->>'frame_file' = p_frame_file)
    when 'unit' then exists(select 1 from studio.studio_knowledge_source_units
      where location_id=p_location_id and id=p_ref_id and payload->'unit'->>'frameFile' = p_frame_file)
    else false end;
$$;

--
-- Name: studio_knowledge_snapshot_current(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_knowledge_snapshot_current(p_location_id text, p_snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 return studio.studio_build_knowledge_snapshot(p_location_id,(p_snapshot#>>'{source,id}')::uuid,(p_snapshot#>>'{source,version}')::bigint,
  p_snapshot->>'mode',p_snapshot->>'inputId',(p_snapshot->>'startUnit')::integer,(p_snapshot->>'unitCount')::integer,p_snapshot->>'focus')=p_snapshot;
exception when sqlstate '40001' or sqlstate '22023' or sqlstate '22P02' then return false;
end; $$;

--
-- Name: studio_knowledge_topic_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_knowledge_topic_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select translate(btrim(regexp_replace(p_name,' +',' ','g')),'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz');
$$;

--
-- Name: studio_lock_ai_manager(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_ai_manager(p_location_id text, p_actor_app text, p_clerk_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_app text;
begin
  perform studio.platform_require_active_profile(p_actor_app,p_clerk_user_id);
  if p_location_id is null or p_actor_app is null or p_actor_app not in ('estio','substo')
    or p_clerk_user_id is null or pg_catalog.btrim(p_clerk_user_id) = '' then
    raise exception 'Invalid AI settings actor' using errcode = '22023';
  end if;
  select app into v_app from studio.studio_locations where location_id = p_location_id for update;
  if v_app is null or v_app <> p_actor_app then
    raise exception 'AI settings access denied' using errcode = '42501';
  end if;
  if v_app = 'substo' then
    perform 1 from studio.studio_location_members where location_id = p_location_id and location_app = 'substo'
      and clerk_user_id = p_clerk_user_id and role in ('owner','admin') for share;
    if not found then raise exception 'AI settings require a location owner or admin' using errcode = '42501'; end if;
  end if;
end;
$$;

--
-- Name: studio_lock_idea_review_lease(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_idea_review_lease(p_location_id text, p_review_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid) RETURNS studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j studio.studio_jobs%rowtype;
begin
  select * into j from studio.studio_jobs where id=p_job_id for update;
  if j.id is null or j.location_id<>p_location_id or j.kind<>'studio.idea_review' or j.payload->>'reviewId' is distinct from p_review_id::text
    or j.status<>'running' or j.lease_owner is distinct from p_worker_id or j.lease_token is distinct from p_lease_token
    or j.lease_expires_at<=clock_timestamp() then raise exception 'Current idea-review lease required' using errcode='40001'; end if;
  if not exists(select 1 from studio.studio_idea_reviews where id=p_review_id and location_id=p_location_id and job_id=p_job_id) then
    raise exception 'Review job mismatch' using errcode='22023'; end if;
  return j;
end; $$;

--
-- Name: studio_lock_legacy_media_owner(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_legacy_media_owner(p_location_id text, p_owner_clerk_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_location studio.studio_locations%rowtype;
begin
  if p_location_id is null or p_owner_clerk_user_id is null or pg_catalog.btrim(p_owner_clerk_user_id) = '' then
    raise exception 'Invalid media reconciliation target' using errcode = '22023';
  end if;
  select * into v_location from studio.studio_locations where location_id=p_location_id for update;
  if not found or v_location.app <> 'substo' then
    raise exception 'Media reconciliation requires the target Substo location owner' using errcode = '42501';
  end if;
  perform 1 from studio.studio_location_members where location_id=p_location_id
    and location_app='substo' and clerk_user_id=p_owner_clerk_user_id and role='owner' for share;
  if not found then
    raise exception 'Media reconciliation requires the target Substo location owner' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: studio_lock_location_member(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_location_member(p_location_id text, p_actor_app text, p_clerk_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_app text;
begin
  perform studio.platform_require_active_profile(p_actor_app,p_clerk_user_id);
  if p_actor_app is null or p_actor_app not in ('estio','substo') or p_clerk_user_id is null or pg_catalog.btrim(p_clerk_user_id) = '' then
    raise exception 'Invalid actor' using errcode = '22023';
  end if;
  select app into v_app from studio.studio_locations where location_id=p_location_id;
  if v_app is null or v_app <> p_actor_app then raise exception 'Location access denied' using errcode = '42501'; end if;
  if v_app = 'substo' then
    perform 1 from studio.studio_location_members where location_id=p_location_id and location_app='substo' and clerk_user_id=p_clerk_user_id for share;
    if not found then raise exception 'Location access denied' using errcode = '42501'; end if;
  end if;
end;
$$;

--
-- Name: studio_lock_text_run_lease(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_text_run_lease(p_location_id text, p_review_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid) RETURNS studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j studio.studio_jobs%rowtype;
begin
  select * into j from studio.studio_jobs where id=p_job_id for update;
  if j.id is null or j.location_id<>p_location_id or j.kind not in ('studio.idea_review','studio.script_brief','studio.knowledge_extract') or j.payload->>'reviewId' is distinct from p_review_id::text
    or j.status<>'running' or j.lease_owner is distinct from p_worker_id or j.lease_token is distinct from p_lease_token
    or j.lease_expires_at<=clock_timestamp() then raise exception 'Current idea-review lease required' using errcode='40001'; end if;
  if not exists(select 1 from studio.studio_idea_reviews where id=p_review_id and location_id=p_location_id and job_id=p_job_id and 'studio.'||workflow=j.kind) then
    raise exception 'Review job mismatch' using errcode='22023'; end if;
  return j;
end; $$;

--
-- Name: studio_lock_transcription_lease(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_transcription_lease(p_location_id text, p_upload_id uuid, p_job_id uuid, p_worker_id text, p_lease_token uuid) RETURNS studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j studio.studio_jobs%rowtype;
begin
  select * into j from studio.studio_jobs where id=p_job_id for update;
  if j.id is null or j.location_id <> p_location_id or j.kind <> 'studio.transcribe_upload'
    or j.payload->>'uploadId' is distinct from p_upload_id::text or j.status <> 'running'
    or j.lease_owner is distinct from p_worker_id or j.lease_token is distinct from p_lease_token
    or j.lease_expires_at <= pg_catalog.clock_timestamp() then
    raise exception 'Current transcription lease required' using errcode='40001';
  end if;
  if not exists(select 1 from studio.studio_uploads where id=p_upload_id and location_id=p_location_id
    and status='uploaded' and transcription_job_id=p_job_id) then
    raise exception 'Upload job mismatch' using errcode='22023';
  end if;
  return j;
end;
$$;

--
-- Name: studio_lock_youtube_member(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_youtube_member(p_location text, p_app text, p_user text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_app text;
begin
  perform studio.platform_require_active_profile(p_app,p_user);
  select app into v_app from studio.studio_locations where location_id=p_location for update;
  if p_user is null or btrim(p_user)='' or p_app is null or v_app is null or v_app<>p_app then raise exception 'Location denied' using errcode='42501'; end if;
  if v_app='substo' then
    perform 1 from studio.studio_location_members where location_id=p_location and location_app='substo' and clerk_user_id=p_user for share;
    if not found then raise exception 'Membership denied' using errcode='42501'; end if;
  end if;
end;
$$;

--
-- Name: studio_youtube_schedule_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE studio.studio_youtube_schedule_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    location_id text NOT NULL,
    schedule_id uuid NOT NULL,
    activation_token uuid NOT NULL,
    job_id uuid NOT NULL,
    actor_app text NOT NULL,
    created_by_clerk_user_id text NOT NULL,
    result jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    slot_lease_token uuid,
    manual boolean DEFAULT false NOT NULL,
    source_mode text,
    channel_id text,
    title_prefix text,
    connection_version uuid,
    schedule_version bigint,
    CONSTRAINT studio_youtube_run_manual_source CHECK (((NOT manual) OR ((source_mode IS NULL) AND (channel_id IS NULL) AND (title_prefix IS NULL) AND (connection_version IS NULL) AND (schedule_version IS NULL)) OR ((source_mode IS NOT NULL) AND (channel_id IS NOT NULL) AND (title_prefix IS NOT NULL) AND (connection_version IS NOT NULL) AND (schedule_version IS NOT NULL) AND (((source_mode = 'search'::text) AND (channel_id = ''::text)) OR ((source_mode <> 'search'::text) AND (channel_id ~ '^UC[A-Za-z0-9_-]{22}$'::text)))))),
    CONSTRAINT studio_youtube_schedule_runs_source_mode_check CHECK ((source_mode = ANY (ARRAY['approved_channel'::text, 'search'::text, 'subscription'::text]))),
    CONSTRAINT studio_youtube_schedule_runs_title_prefix_check CHECK (((title_prefix IS NULL) OR ((char_length(title_prefix) >= 1) AND (char_length(title_prefix) <= 100))))
);

--
-- Name: studio_lock_youtube_run(text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_youtube_run(p_location text, p_run uuid, p_job uuid, p_worker text, p_lease uuid) RETURNS studio.studio_youtube_schedule_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run studio.studio_youtube_schedule_runs%rowtype; j studio.studio_jobs%rowtype;
begin
 select * into run from studio.studio_youtube_schedule_runs where location_id=p_location and id=p_run and job_id=p_job;
 if run.id is null then raise exception 'Discovery run missing' using errcode='22023'; end if;
 perform studio.studio_lock_youtube_source(p_location,p_run);
 select * into j from studio.studio_jobs where location_id=p_location and id=p_job for update;
 if j.kind<>'studio.youtube_discovery' or j.payload->>'discoveryRunId' is distinct from p_run::text or j.status<>'running'
 or j.lease_owner is distinct from p_worker or j.lease_token is distinct from p_lease or j.lease_expires_at<=clock_timestamp() then
 raise exception 'Current discovery lease required' using errcode='40001'; end if;
 return run;
end; $$;

--
-- Name: platform_youtube_schedule_authorizations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE studio.platform_youtube_schedule_authorizations (
    location_id text NOT NULL,
    schedule_id uuid NOT NULL,
    app text NOT NULL,
    clerk_user_id text NOT NULL,
    connection_version uuid NOT NULL,
    activation_token uuid NOT NULL,
    source_mode text NOT NULL,
    channel_id text NOT NULL,
    title_prefix text NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '30 days'::interval) NOT NULL,
    CONSTRAINT platform_youtube_schedule_authorizations_check CHECK ((((source_mode = 'search'::text) AND (channel_id = ''::text)) OR ((source_mode <> 'search'::text) AND (channel_id ~ '^UC[A-Za-z0-9_-]{22}$'::text)))),
    CONSTRAINT platform_youtube_schedule_authorizations_source_mode_check CHECK ((source_mode = ANY (ARRAY['approved_channel'::text, 'search'::text, 'subscription'::text]))),
    CONSTRAINT platform_youtube_schedule_authorizations_title_prefix_check CHECK (((char_length(title_prefix) >= 1) AND (char_length(title_prefix) <= 100)))
);

--
-- Name: studio_lock_youtube_schedule(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_youtube_schedule(p_location text, p_schedule uuid, p_token uuid) RETURNS studio.platform_youtube_schedule_authorizations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare g studio.platform_youtube_schedule_authorizations%rowtype; r studio.studio_schedule_recurring%rowtype; s studio.studio_schedules%rowtype;
begin
 select * into g from studio.platform_youtube_schedule_authorizations where location_id=p_location and schedule_id=p_schedule;
 if g.schedule_id is null or g.activation_token is distinct from p_token then raise exception 'Profile authorization unavailable' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||g.app||':'||g.clerk_user_id,0));
 perform studio.studio_lock_location_member(p_location,g.app,g.clerk_user_id);
 select * into s from studio.studio_schedules where location_id=p_location and id=p_schedule for share;
 select * into r from studio.studio_schedule_recurring where location_id=p_location and schedule_id=p_schedule for share;
 select * into g from studio.platform_youtube_schedule_authorizations where location_id=p_location and schedule_id=p_schedule for share;
 if g.schedule_id is null or not r.enabled or r.activation_token is distinct from p_token or g.activation_token is distinct from p_token
 or g.app is distinct from r.actor_app or g.clerk_user_id is distinct from r.authorized_by or g.expires_at<=clock_timestamp()
 or r.schedule_version<>s.version or s.preset_id<>'youtube-discovery' then raise exception 'Discovery consent changed' using errcode='42501'; end if;
 perform 1 from studio.platform_google_youtube_connections where app=g.app and clerk_user_id=g.clerk_user_id and version=g.connection_version
 and 'https://www.googleapis.com/auth/youtube.readonly'=any(granted_scopes) for share;
 if not found then raise exception 'Profile grant changed' using errcode='42501'; end if;
 if g.source_mode='approved_channel' then
  perform 1 from studio.studio_youtube_channels where location_id=p_location and channel_id=g.channel_id for share;
  if not found then raise exception 'Channel approval removed' using errcode='42501'; end if;
 end if;
 return g;
end; $$;

--
-- Name: studio_lock_youtube_source(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_lock_youtube_source(p_location text, p_run uuid) RETURNS studio.platform_youtube_schedule_authorizations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run studio.studio_youtube_schedule_runs%rowtype; g studio.platform_youtube_schedule_authorizations%rowtype; s studio.studio_schedules%rowtype;
begin
 select * into run from studio.studio_youtube_schedule_runs where location_id=p_location and id=p_run;
 if run.id is null then raise exception 'Discovery run missing' using errcode='22023'; end if;
 if not run.manual then return studio.studio_lock_youtube_schedule(p_location,run.schedule_id,run.activation_token); end if;
 if run.connection_version is null then raise exception 'Manual source authorization removed' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||run.actor_app||':'||run.created_by_clerk_user_id,0));
 select * into run from studio.studio_youtube_schedule_runs where location_id=p_location and id=p_run;
 if run.connection_version is null then raise exception 'Manual source authorization removed' using errcode='42501'; end if;
 perform studio.studio_lock_location_member(p_location,run.actor_app,run.created_by_clerk_user_id);
 select * into s from studio.studio_schedules where location_id=p_location and id=run.schedule_id for share;
 if s.id is null or s.version<>run.schedule_version or s.preset_id<>'youtube-discovery' then raise exception 'Discovery definition changed' using errcode='42501'; end if;
 perform 1 from studio.platform_google_youtube_connections where app=run.actor_app and clerk_user_id=run.created_by_clerk_user_id
 and version=run.connection_version and 'https://www.googleapis.com/auth/youtube.readonly'=any(granted_scopes) for share;
 if not found then raise exception 'Profile grant changed' using errcode='42501'; end if;
 if run.source_mode='approved_channel' then
  perform 1 from studio.studio_youtube_channels where location_id=p_location and channel_id=run.channel_id for share;
  if not found then raise exception 'Channel approval removed' using errcode='42501'; end if;
 end if;
 g.location_id:=p_location; g.schedule_id:=run.schedule_id; g.app:=run.actor_app; g.clerk_user_id:=run.created_by_clerk_user_id;
 g.connection_version:=run.connection_version; g.activation_token:=run.activation_token; g.source_mode:=run.source_mode;
 g.channel_id:=run.channel_id; g.title_prefix:=run.title_prefix; g.expires_at:=run.created_at+interval '1 day';
 return g;
end; $$;

--
-- Name: studio_manage_device(text, text, text, text, uuid, uuid, text, text, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_manage_device(p_location_id text, p_actor_app text, p_clerk_user_id text, p_action text, p_request_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_provider text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_value jsonb DEFAULT NULL::jsonb, p_expected_version integer DEFAULT NULL::integer, p_command_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d studio.studio_devices%rowtype; j studio.studio_jobs%rowtype; c studio.studio_device_commands%rowtype; v_device uuid;
begin
 perform studio.studio_lock_ai_manager(p_location_id,p_actor_app,p_clerk_user_id);
 if p_action is null or p_action not in ('revoke','diagnostic','set_processing','set_paused','save_config','provider_login','provider_logout','cancel_command')
  or p_provider is not null and (p_action not in ('diagnostic','provider_login','provider_logout') or p_provider not in ('codex','claude'))
  or p_model is not null and (p_action<>'diagnostic' or p_provider is null or p_model !~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{0,99}$')
  or p_action in ('diagnostic','provider_login','provider_logout') and p_request_id is null
  or p_action in ('provider_login','provider_logout') and p_provider is null then raise exception 'Invalid device action' using errcode='22023'; end if;
 if p_action='cancel_command' then
  -- Lock order: location (above) -> device -> command.
  select device_id into v_device from studio.studio_device_commands where id=p_command_id and location_id=p_location_id;
  if v_device is null then raise exception 'Command unavailable' using errcode='42501'; end if;
  perform 1 from studio.studio_devices where id=v_device and location_id=p_location_id and app=p_actor_app for update;
  if not found then raise exception 'Command unavailable' using errcode='42501'; end if;
  select * into c from studio.studio_device_commands where id=p_command_id for update;
  if c.status in ('pending','running','waiting_for_user') then
   update studio.studio_device_commands set status='cancelled',display='{}',finished_at=clock_timestamp(),updated_at=clock_timestamp() where id=c.id;
  end if;
  return jsonb_build_object('commandId',c.id);
 end if;
 select * into d from studio.studio_devices where id=p_device_id and location_id=p_location_id and app=p_actor_app for update;
 if not found then raise exception 'Device unavailable' using errcode='42501'; end if;
 if p_action='revoke' then
  update studio.studio_devices set revoked_at=coalesce(revoked_at,clock_timestamp()) where id=d.id;
  update studio.studio_device_commands set status='cancelled',display='{}',finished_at=clock_timestamp(),updated_at=clock_timestamp()
   where device_id=d.id and status in ('pending','running','waiting_for_user');
  return jsonb_build_object('deviceId',d.id);
 end if;
 if d.revoked_at is not null then raise exception 'Device revoked' using errcode='42501'; end if;
 if p_action='diagnostic' then
  j:=studio.studio_enqueue_job(p_location_id,'studio.diagnostic',jsonb_strip_nulls(jsonb_build_object('provider',p_provider,'model',p_model)),'device:'||d.id||':'||p_request_id,p_clerk_user_id,3);
  update studio.studio_jobs set execution_target='device',device_id=d.id where id=j.id;
  return jsonb_build_object('jobId',j.id);
 elsif p_action in ('set_processing','set_paused') then
  if jsonb_typeof(p_value) is distinct from 'boolean' then raise exception 'Invalid device action' using errcode='22023'; end if;
  if p_action='set_processing' then update studio.studio_devices set processing_enabled=(p_value#>>'{}')::boolean where id=d.id;
  else update studio.studio_devices set paused=(p_value#>>'{}')::boolean where id=d.id; end if;
  return jsonb_build_object('deviceId',d.id);
 elsif p_action='save_config' then
  -- Full validation happens in readDeviceConfig; SQL bounds shape and enforces optimistic concurrency.
  if jsonb_typeof(p_value) is distinct from 'object' or octet_length(p_value::text)>4096 or p_expected_version is null then raise exception 'Invalid config' using errcode='22023'; end if;
  if d.config_version<>p_expected_version then raise exception 'Config changed' using errcode='40001'; end if;
  update studio.studio_devices set desired_config=p_value,config_version=config_version+1,config_status='pending',config_report='{}' where id=d.id returning * into d;
  return jsonb_build_object('version',d.config_version);
 end if;
 insert into studio.studio_device_commands(location_id,device_id,kind,provider,created_by,request_id)
 values(p_location_id,d.id,case p_action when 'provider_login' then 'provider_login' else 'provider_logout' end,p_provider,p_clerk_user_id,p_request_id)
 on conflict(location_id,request_id) do nothing returning * into c;
 if c.id is null then
  select * into c from studio.studio_device_commands where location_id=p_location_id and request_id=p_request_id;
  if c.device_id<>d.id or c.provider<>p_provider or c.kind<>p_action then raise exception 'Command already issued' using errcode='23505'; end if;
 end if;
 return jsonb_build_object('commandId',c.id);
end $_$;

--
-- Name: studio_member_job_action(text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_member_job_action(p_location_id text, p_actor_app text, p_clerk_user_id text, p_job_id uuid, p_action text) RETURNS studio.studio_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_app text;
  v_job studio.studio_jobs%rowtype;
  v_target text;
  v_device_id uuid;
begin
  if p_action is null or p_action not in ('retry','cancel') or p_clerk_user_id is null or pg_catalog.btrim(p_clerk_user_id) = '' then
    raise exception 'Invalid job action' using errcode = '22023';
  end if;
  select execution_target,device_id into v_target,v_device_id from studio.studio_jobs
    where id=p_job_id and location_id=p_location_id;
  if p_action = 'retry' and v_target = 'device' then
    perform studio.studio_lock_ai_manager(p_location_id,p_actor_app,p_clerk_user_id);
    perform 1 from studio.studio_devices where id=v_device_id and location_id=p_location_id
      and app=p_actor_app and revoked_at is null for update;
    if not found then raise exception 'Device unavailable' using errcode = '42501'; end if;
  end if;
  select app into v_app from studio.studio_locations where location_id=p_location_id;
  if v_app is null or v_app <> p_actor_app then raise exception 'Job access denied' using errcode = '42501'; end if;
  if v_app = 'substo' then
    perform 1 from studio.studio_location_members where location_id=p_location_id and location_app='substo' and clerk_user_id=p_clerk_user_id for share;
    if not found then raise exception 'Job access denied' using errcode = '42501'; end if;
  end if;
  select * into v_job from studio.studio_jobs where id=p_job_id and location_id=p_location_id for update;
  if not found then raise exception 'Job not found' using errcode = '22023'; end if;
  if p_action = 'retry' and (v_job.execution_target is distinct from v_target or v_job.device_id is distinct from v_device_id) then
    raise exception 'Job routing changed; retry the request' using errcode = '40001';
  end if;
  if p_action = 'retry' and v_job.status = 'failed' then
    update studio.studio_jobs set status='queued', attempts=0, run_after=pg_catalog.now(), finished_at=null, updated_at=pg_catalog.now()
      where id=p_job_id returning * into v_job;
    insert into studio.studio_job_events(job_id,location_id,attempt,event,actor_clerk_user_id) values(v_job.id,v_job.location_id,0,'requeued',p_clerk_user_id);
  elsif p_action = 'cancel' and v_job.status = 'queued' then
    update studio.studio_jobs set status='cancelled', finished_at=pg_catalog.now(), updated_at=pg_catalog.now() where id=p_job_id returning * into v_job;
    insert into studio.studio_job_events(job_id,location_id,attempt,event,actor_clerk_user_id) values(v_job.id,v_job.location_id,v_job.attempts,'cancelled',p_clerk_user_id);
  else
    raise exception 'Job is not in a state that allows this action' using errcode = '40001';
  end if;
  return v_job;
end;
$$;

--
-- Name: studio_mutate_knowledge_insight(text, text, text, uuid, uuid, bigint, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_mutate_knowledge_insight(p_location text, p_app text, p_user text, p_insight uuid, p_request uuid, p_version bigint, p_action text, p_statement text, p_topic jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare old studio.studio_knowledge_insights%rowtype; prior studio.studio_knowledge_commands%rowtype;
 command jsonb; v_result jsonb; v_statement text; v_status text; v_topic uuid; v_topic_name text; old_topic_name text;
 v_source uuid; v_review uuid:=gen_random_uuid(); at_iso text;
begin
 perform studio.studio_lock_location_member(p_location,p_app,p_user);
 if p_insight is null or p_request is null or p_version is null or p_version<1 or p_action is null or p_action not in ('edit','approve','reject','reopen')
 or p_reason is null or char_length(p_reason)>2000 or jsonb_typeof(p_topic) is distinct from 'object'
 or p_topic->>'mode' is null or p_topic->>'mode' not in ('keep','existing','create')
 or (p_action<>'approve' and p_topic<>'{"mode":"keep"}'::jsonb)
 or (p_statement is not null and (char_length(p_statement) not between 1 and 4000 or p_statement ~ '^[[:space:]]*$'))
 or (p_action='edit' and p_statement is null) then raise exception 'Invalid knowledge command' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('knowledge-command:'||p_location::text||':'||p_request::text,0));
 command:=jsonb_build_object('insightId',p_insight,'actor',p_user,'app',p_app,'version',p_version,'action',p_action,'statement',p_statement,'topic',p_topic,'reason',p_reason);
 select * into prior from studio.studio_knowledge_commands where location_id=p_location and request_id=p_request;
 if found then
  if prior.request is distinct from command then raise exception 'Knowledge request reused' using errcode='23505'; end if;
  return prior.result;
 end if;
 select source_id into v_source from studio.studio_knowledge_insights where location_id=p_location and id=p_insight;
 if not found then raise exception 'Finding unavailable' using errcode='P0002'; end if;
 -- Shares extraction's source fence: edits cannot race exact-match application.
 perform pg_advisory_xact_lock(hashtextextended('knowledge-apply:'||p_location::text||':'||v_source::text,0));
 select * into old from studio.studio_knowledge_insights where location_id=p_location and id=p_insight for update;
 if old.id is null then raise exception 'Finding unavailable' using errcode='P0002'; end if;
 if old.version<>p_version then raise exception 'Finding changed' using errcode='40001'; end if;
 if (p_action in ('approve','reject') and old.status<>'pending') or (p_action='reopen' and old.status='pending') then raise exception 'Invalid status transition' using errcode='22023'; end if;
 v_statement:=coalesce(p_statement,old.statement);
 if v_statement ~ '^[[:space:]]*$' then raise exception 'Enter a nonempty statement' using errcode='22023'; end if;
 if p_action='edit' and v_statement=old.statement then raise exception 'Statement is unchanged' using errcode='22023'; end if;
 if v_statement<>old.statement and exists(select 1 from studio.studio_knowledge_insights i where i.location_id=p_location and i.source_id=old.source_id
  and i.id<>old.id and i.statement=v_statement and i.payload->>'kind' is not distinct from old.payload->>'kind') then raise exception 'Duplicate finding statement' using errcode='23505'; end if;
 v_status:=case p_action when 'approve' then 'approved' when 'reject' then 'rejected' else 'pending' end;
 v_topic:=old.topic_id;
 if p_action='approve' then
  if p_topic->>'mode'='existing' then
   if jsonb_typeof(p_topic->'id') is distinct from 'string' then raise exception 'Choose a topic ID' using errcode='22023'; end if;
   v_topic:=(p_topic->>'id')::uuid;
  elsif p_topic->>'mode'='create' then
   if jsonb_typeof(p_topic->'name') is distinct from 'string' then raise exception 'Enter a topic name' using errcode='22023'; end if;
   v_topic:=studio.studio_resolve_knowledge_topic(p_location,p_topic->>'name',p_app,p_user);
  end if;
  select payload->>'name' into v_topic_name from studio.studio_knowledge_topics where location_id=p_location and id=v_topic and jsonb_typeof(payload->'name')='string' for share;
  if not found or btrim(coalesce(v_topic_name,''))='' then raise exception 'Choose a location topic before approval' using errcode='22023'; end if;
 end if;
 select payload->>'name' into old_topic_name from studio.studio_knowledge_topics where location_id=p_location and id=old.topic_id;
 if p_action<>'approve' then v_topic_name:=old_topic_name; end if;
 at_iso:=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 update studio.studio_knowledge_insights set statement=v_statement,status=v_status,topic_id=v_topic,version=version+1 where location_id=p_location and id=p_insight;
 insert into studio.studio_knowledge_reviews(location_id,id,insight_id,payload) values(p_location,v_review,p_insight,jsonb_build_object(
  'id',v_review,'insight_id',p_insight,'action',p_action,'previous_status',old.status,'new_status',v_status,
  'previous_statement',old.statement,'new_statement',v_statement,'previous_topic_id',old.topic_id,'new_topic_id',v_topic,
  'previous_topic_name',old_topic_name,'new_topic_name',v_topic_name,'at',at_iso,'actor_app',p_app,'actor_clerk_user_id',p_user,
  'version',old.version+1,'origin','hosted','reason',nullif(p_reason,''),'request_id',p_request));
 v_result:=jsonb_build_object('locationId',p_location,'insightId',p_insight,'reviewId',v_review,'previousStatus',old.status,
  'status',v_status,'version',old.version+1,'topicId',v_topic,'at',at_iso);
 insert into studio.studio_knowledge_commands(location_id,request_id,insight_id,request,result) values(p_location,p_request,p_insight,command,v_result);
 return v_result;
end; $_$;

--
-- Name: studio_next_schedule_due(timestamp with time zone, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_next_schedule_due(p_after timestamp with time zone, p_interval integer, p_time text, p_zone text) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare candidate timestamptz; d date;
begin
  if p_after is null or p_interval is null or p_interval not in (24,168) or p_zone is distinct from 'Asia/Nicosia'
    or p_time is null or p_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Invalid cadence' using errcode='22023'; end if;
  if p_interval=168 then return p_after+interval '168 hours'; end if;
  d := (p_after at time zone p_zone)::date;
  candidate := (d+p_time::time) at time zone p_zone;
  if candidate<=p_after then candidate := ((d+1)+p_time::time) at time zone p_zone; end if;
  return candidate;
end; $_$;

--
-- Name: studio_pause_edited_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_pause_edited_schedule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update studio.studio_schedule_recurring set enabled=false,next_run_at=null,version=version+1,last_outcome='definition_changed',updated_at=clock_timestamp()
    where location_id=new.location_id and schedule_id=new.id and enabled;
  return new;
end; $$;

--
-- Name: studio_prune_youtube_schedule_authorizations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_prune_youtube_schedule_authorizations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare g record; n integer:=0;
begin
 for g in select * from studio.platform_youtube_schedule_authorizations where expires_at<=clock_timestamp() order by app,clerk_user_id,location_id,schedule_id limit 100 loop
  perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||g.app||':'||g.clerk_user_id,0));
  update studio.studio_schedule_recurring set enabled=false,next_run_at=null,version=version+1,last_outcome='authorization_expired',updated_at=clock_timestamp()
  where location_id=g.location_id and schedule_id=g.schedule_id and activation_token=g.activation_token and enabled;
  delete from studio.platform_youtube_schedule_authorizations where location_id=g.location_id and schedule_id=g.schedule_id and activation_token=g.activation_token and expires_at<=clock_timestamp();
  n:=n+1;
 end loop;
 return n;
end; $$;

--
-- Name: studio_readiness_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_readiness_snapshot() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select pg_catalog.jsonb_build_object('schema',29,'protocol',1,'checkedAt',pg_catalog.statement_timestamp(),
  'keyIds',coalesce((select jsonb_agg(k) from (
   select key_id k from studio.studio_location_ai_credentials union
   select refresh_cipher->>'keyId' from studio.platform_google_youtube_connections
  ) keys),'[]'::jsonb),
  'queue',pg_catalog.jsonb_build_object(
   'due',(select count(*) from studio.studio_jobs where status='queued' and run_after<=pg_catalog.statement_timestamp()),
   'oldestDueAt',(select min(run_after) from studio.studio_jobs where status='queued' and run_after<=pg_catalog.statement_timestamp()),
   'expiredLeases',(select count(*) from studio.studio_jobs where status='running' and lease_expires_at<=pg_catalog.statement_timestamp()),
   'uncertainAttempts',(select count(*) from studio.studio_ai_attempts where status='uncertain')),
  'workers',coalesce((select jsonb_agg(row_to_json(w)) from (
   select release,instance_id,protocol,handlers,healthy,draining,seen_at,started_at
   from studio.studio_worker_heartbeats where seen_at>pg_catalog.statement_timestamp()-interval '5 minutes'
   order by seen_at desc limit 100
  ) w),'[]'::jsonb));
$$;

--
-- Name: studio_recover_ai_attempts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_recover_ai_attempts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j studio.studio_jobs%rowtype; n integer := 0; changed integer;
begin
  for j in select * from studio.studio_jobs q where exists
    (select 1 from studio.studio_ai_attempts a where a.job_id=q.id and a.status='started'
      and (q.status <> 'running' or q.lease_token is distinct from a.lease_token or q.lease_expires_at <= pg_catalog.clock_timestamp()))
    order by q.id limit 100 for update skip locked loop
    update studio.studio_ai_attempts set status='uncertain',updated_at=pg_catalog.clock_timestamp()
      where job_id=j.id and status='started' and (j.status <> 'running' or j.lease_token is distinct from lease_token
        or j.lease_expires_at <= pg_catalog.clock_timestamp());
    get diagnostics changed = row_count; n := n + changed;
  end loop;
  return n;
end;
$$;

--
-- Name: studio_recover_transcription_attempts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_recover_transcription_attempts() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$ select studio.studio_recover_ai_attempts(); $$;

--
-- Name: studio_release_ai_spend(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_release_ai_spend(p_location_id text, p_usage_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update studio.studio_ai_usage set status='released' where id=p_usage_id and location_id=p_location_id and status='reserved';
  return found;
end;
$$;

--
-- Name: studio_report_worker(text, text, timestamp with time zone, text, text[], boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_report_worker(p_worker_id text, p_release text, p_started_at timestamp with time zone, p_instance_id text, p_handlers text[], p_healthy boolean, p_draining boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
 if p_instance_id is null or p_instance_id !~ '^[A-Za-z0-9._:-]{1,100}$'
 or p_release is null or char_length(p_release) not between 1 and 100
 or p_started_at is null or not pg_catalog.isfinite(p_started_at)
 or p_started_at > pg_catalog.clock_timestamp()+interval '5 minutes'
 or p_handlers is null or cardinality(p_handlers) not between 1 and 20
 or exists(select 1 from unnest(p_handlers) h where h is null or h !~ '^studio\.[a-z_]{1,50}$')
 or p_healthy is null or p_draining is null then raise exception 'Invalid worker report' using errcode='22023'; end if;
 insert into studio.studio_worker_heartbeats(worker_id,release,started_at,seen_at,instance_id,protocol,handlers,healthy,draining)
 values(p_worker_id,p_release,p_started_at,pg_catalog.clock_timestamp(),p_instance_id,1,p_handlers,p_healthy and not p_draining,p_draining)
 on conflict(worker_id) do update set release=excluded.release,started_at=excluded.started_at,seen_at=excluded.seen_at,
 instance_id=excluded.instance_id,protocol=excluded.protocol,handlers=excluded.handlers,
 healthy=excluded.healthy and not studio_worker_heartbeats.draining,
 draining=studio_worker_heartbeats.draining or excluded.draining
 -- An ID identifies one process lifetime. Do not let a late different process impersonate it.
 where studio_worker_heartbeats.instance_id is null or
 (studio_worker_heartbeats.instance_id=excluded.instance_id and studio_worker_heartbeats.started_at=excluded.started_at
  and studio_worker_heartbeats.release=excluded.release);
 if not found then raise exception 'Worker identity changed' using errcode='23505'; end if;
 delete from studio.studio_worker_heartbeats where seen_at < pg_catalog.clock_timestamp()-interval '7 days';
end $_$;

--
-- Name: studio_reserve_ai_spend(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_reserve_ai_spend(p_location_id text, p_provider text, p_operation text, p_estimated_micros bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_budget bigint;
  v_month date := pg_catalog.date_trunc('month', pg_catalog.now() at time zone 'UTC')::date;
  v_used bigint;
  v_id uuid;
begin
  if p_estimated_micros is null or p_estimated_micros < 0 then raise exception 'Invalid estimate' using errcode = '22023'; end if;
  select monthly_budget_micros into v_budget from studio.studio_location_ai_settings where location_id=p_location_id for update;
  if v_budget is null or v_budget = 0 then return null; end if;
  if not exists(select 1 from studio.studio_location_ai_credentials where location_id=p_location_id and provider=p_provider) then return null; end if;
  select coalesce(pg_catalog.sum(case status when 'settled' then cost_micros when 'reserved' then reserved_micros else 0 end),0)
    into v_used from studio.studio_ai_usage where location_id=p_location_id and usage_month=v_month;
  if v_used + p_estimated_micros > v_budget then return null; end if;
  insert into studio.studio_ai_usage(location_id,provider,operation,status,reserved_micros,usage_month)
    values(p_location_id,p_provider,p_operation,'reserved',p_estimated_micros,v_month) returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: studio_reserve_knowledge_media(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_reserve_knowledge_media(p_location_id text, p_owner_clerk_user_id text, p_knowledge_source_digest text, p_media_source_digest text, p_bucket_id text, p_refs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_ref jsonb;
  v_link studio.studio_knowledge_media_links%rowtype;
  v_key text;
  v_result jsonb := '[]'::jsonb;
begin
  if p_knowledge_source_digest is null or p_knowledge_source_digest !~ '^[0-9a-f]{64}$'
    or p_media_source_digest is null or p_media_source_digest !~ '^[0-9a-f]{64}$'
    or p_bucket_id is null or p_bucket_id !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$'
    or pg_catalog.jsonb_typeof(p_refs) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_refs) > 10000 then
    raise exception 'Invalid knowledge media reservation' using errcode = '22023';
  end if;
  perform studio.studio_lock_legacy_media_owner(p_location_id, p_owner_clerk_user_id);
  if not exists(select 1 from studio.studio_knowledge_import_runs
    where location_id=p_location_id and source_digest=p_knowledge_source_digest) then
    raise exception 'Matching knowledge import is required before media reconciliation' using errcode = '22023';
  end if;
  if (select pg_catalog.count(distinct (value->>'refKind') || ':' || (value->>'refId')) from pg_catalog.jsonb_array_elements(p_refs)) <> pg_catalog.jsonb_array_length(p_refs) then
    raise exception 'Duplicate knowledge media reservation' using errcode = '22023';
  end if;

  for v_ref in select value from pg_catalog.jsonb_array_elements(p_refs) loop
    if pg_catalog.jsonb_typeof(v_ref) is distinct from 'object'
      or (v_ref->>'refKind') is null or (v_ref->>'refKind') not in ('evidence','unit')
      or (v_ref->>'refId') is null or (v_ref->>'refId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_ref->>'sha256') is null or (v_ref->>'sha256') !~ '^[0-9a-f]{64}$'
      or pg_catalog.jsonb_typeof(v_ref->'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_ref->'frameFile') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_ref->'contentType') is distinct from 'string' then
      raise exception 'Invalid knowledge media reservation row' using errcode = '22023';
    end if;
    if not studio.studio_knowledge_frame_matches(p_location_id, v_ref->>'refKind', (v_ref->>'refId')::uuid, v_ref->>'frameFile') then
      raise exception 'Frame does not match the imported knowledge row' using errcode = '22023';
    end if;
    v_key := p_location_id::text || '/legacy-knowledge/' || (v_ref->>'refKind') || '/' || (v_ref->>'refId') || '/' || (v_ref->>'sha256');
    select * into v_link from studio.studio_knowledge_media_links
      where location_id=p_location_id and ref_kind=v_ref->>'refKind' and ref_id=(v_ref->>'refId')::uuid for update;
    if found and v_link.status = 'verified' then
      if v_link.bucket_id <> p_bucket_id or v_link.sha256 <> v_ref->>'sha256' or v_link.byte_size <> (v_ref->>'byteSize')::bigint then
        raise exception 'Frame is already bound to different verified bytes' using errcode = '23505';
      end if;
    elsif found then
      update studio.studio_knowledge_media_links set frame_file=v_ref->>'frameFile', knowledge_source_digest=p_knowledge_source_digest,
        media_source_digest=p_media_source_digest, bucket_id=p_bucket_id, sha256=v_ref->>'sha256', byte_size=(v_ref->>'byteSize')::bigint,
        content_type=v_ref->>'contentType', object_key=v_key, reserved_by_clerk_user_id=p_owner_clerk_user_id, reserved_at=pg_catalog.now()
        where location_id=p_location_id and ref_kind=v_link.ref_kind and ref_id=v_link.ref_id returning * into v_link;
    else
      insert into studio.studio_knowledge_media_links(location_id,ref_kind,ref_id,frame_file,knowledge_source_digest,media_source_digest,
        bucket_id,sha256,byte_size,content_type,object_key,status,reserved_by_clerk_user_id)
        values(p_location_id,v_ref->>'refKind',(v_ref->>'refId')::uuid,v_ref->>'frameFile',p_knowledge_source_digest,p_media_source_digest,
        p_bucket_id,v_ref->>'sha256',(v_ref->>'byteSize')::bigint,v_ref->>'contentType',v_key,'pending',p_owner_clerk_user_id)
        returning * into v_link;
    end if;
    v_result := v_result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('refKind',v_link.ref_kind,'refId',v_link.ref_id,
      'bucketId',v_link.bucket_id,'objectKey',v_link.object_key,'status',v_link.status,'mediaObjectId',v_link.media_object_id));
  end loop;
  return pg_catalog.jsonb_build_object('locationId',p_location_id,'mediaSourceDigest',p_media_source_digest,'references',v_result);
end;
$_$;

--
-- Name: studio_reserve_legacy_media(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_reserve_legacy_media(p_location_id text, p_owner_clerk_user_id text, p_library_source_digest text, p_media_source_digest text, p_bucket_id text, p_files jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_file jsonb;
  v_legacy studio.studio_legacy_files%rowtype;
  v_transfer studio.studio_legacy_media_transfers%rowtype;
  v_key text;
  v_result jsonb := '[]'::jsonb;
begin
  if p_library_source_digest is null or p_library_source_digest !~ '^[0-9a-f]{64}$'
    or p_media_source_digest is null or p_media_source_digest !~ '^[0-9a-f]{64}$'
    or p_bucket_id is null or p_bucket_id !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$'
    or pg_catalog.jsonb_typeof(p_files) is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_files) > 10000 then
    raise exception 'Invalid media reservation' using errcode = '22023';
  end if;
  perform studio.studio_lock_legacy_media_owner(p_location_id, p_owner_clerk_user_id);
  if not exists(select 1 from studio.studio_library_import_runs
    where location_id=p_location_id and source_digest=p_library_source_digest) then
    raise exception 'Matching library import is required before media reconciliation' using errcode = '22023';
  end if;
  if (select pg_catalog.count(distinct value->>'id') from pg_catalog.jsonb_array_elements(p_files)) <> pg_catalog.jsonb_array_length(p_files) then
    raise exception 'Duplicate media reservation' using errcode = '22023';
  end if;

  for v_file in select value from pg_catalog.jsonb_array_elements(p_files) loop
    if pg_catalog.jsonb_typeof(v_file) is distinct from 'object'
      or (v_file->>'id') is null or (v_file->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_file->>'recordId') is null or (v_file->>'recordId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or (v_file->>'sha256') is null or (v_file->>'sha256') !~ '^[0-9a-f]{64}$'
      or pg_catalog.jsonb_typeof(v_file->'byteSize') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_file->'originalFilename') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_file->'contentType') is distinct from 'string' then
      raise exception 'Invalid media reservation row' using errcode = '22023';
    end if;
    select * into v_legacy from studio.studio_legacy_files
      where location_id=p_location_id and id=(v_file->>'id')::uuid for update;
    if not found or v_legacy.record_id <> (v_file->>'recordId')::uuid
      or v_legacy.payload->'size' is distinct from v_file->'byteSize'
      or v_legacy.payload->'name' is distinct from v_file->'originalFilename'
      or v_legacy.payload->'type' is distinct from v_file->'contentType' then
      raise exception 'Media row does not match the imported original attachment' using errcode = '22023';
    end if;
    v_key := p_location_id::text || '/legacy-library/' || v_legacy.id::text || '/' || (v_file->>'sha256');
    select * into v_transfer from studio.studio_legacy_media_transfers
      where location_id=p_location_id and file_id=v_legacy.id for update;
    if found and v_transfer.status = 'verified' then
      if v_transfer.bucket_id <> p_bucket_id or v_transfer.sha256 <> v_file->>'sha256' or v_transfer.byte_size <> (v_file->>'byteSize')::bigint then
        raise exception 'Attachment is already bound to different verified bytes' using errcode = '23505';
      end if;
    elsif found then
      -- A pending reservation has no binding; reviewed new evidence may replace it.
      update studio.studio_legacy_media_transfers set bucket_id=p_bucket_id, library_source_digest=p_library_source_digest,
        media_source_digest=p_media_source_digest, sha256=v_file->>'sha256', byte_size=(v_file->>'byteSize')::bigint,
        object_key=v_key, reserved_by_clerk_user_id=p_owner_clerk_user_id, reserved_at=pg_catalog.now()
        where location_id=p_location_id and file_id=v_legacy.id returning * into v_transfer;
    else
      if v_legacy.media_object_id is not null then
        raise exception 'Attachment already has media outside this reconciliation' using errcode = '23505';
      end if;
      insert into studio.studio_legacy_media_transfers(location_id,file_id,record_id,bucket_id,library_source_digest,media_source_digest,
        sha256,byte_size,object_key,status,reserved_by_clerk_user_id)
        values(p_location_id,v_legacy.id,v_legacy.record_id,p_bucket_id,p_library_source_digest,p_media_source_digest,
        v_file->>'sha256',(v_file->>'byteSize')::bigint,v_key,'pending',p_owner_clerk_user_id)
        returning * into v_transfer;
    end if;
    v_result := v_result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('fileId',v_transfer.file_id,
      'bucketId',v_transfer.bucket_id,'objectKey',v_transfer.object_key,'status',v_transfer.status,'mediaObjectId',v_transfer.media_object_id));
  end loop;
  return pg_catalog.jsonb_build_object('locationId',p_location_id,'mediaSourceDigest',p_media_source_digest,'files',v_result);
end;
$_$;

--
-- Name: studio_resolve_knowledge_topic(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_resolve_knowledge_topic(p_location text, p_name text, p_app text, p_user text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare k text; topic uuid; matches uuid[]; at_iso text;
begin
 if p_name is null or char_length(btrim(p_name)) not between 1 and 120 or p_name ~ '[[:cntrl:]]' then raise exception 'Topic name required' using errcode='22023'; end if;
 k:=studio.studio_knowledge_topic_key(p_name);
 perform pg_advisory_xact_lock(hashtextextended('knowledge-topic:'||p_location::text||':'||k,0));
 select topic_id into topic from studio.studio_knowledge_topic_names where location_id=p_location and name_key=k;
 if found then return topic; end if;
 select array_agg(id order by id) into matches from studio.studio_knowledge_topics where location_id=p_location
  and jsonb_typeof(payload->'name')='string' and studio.studio_knowledge_topic_key(payload->>'name')=k;
 if cardinality(matches)>1 then raise exception 'Multiple existing topics match; select an existing ID' using errcode='22023'; end if;
 topic:=matches[1];
 if topic is null then
  topic:=gen_random_uuid();at_iso:=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  insert into studio.studio_knowledge_topics(location_id,id,payload) values(p_location,topic,jsonb_build_object('id',topic,'name',btrim(p_name),
   'created_at',at_iso,'origin','hosted','created_by_clerk_user_id',p_user,'actor_app',p_app));
 end if;
 insert into studio.studio_knowledge_topic_names(location_id,name_key,topic_id) values(p_location,k,topic);
 return topic;
end; $$;

--
-- Name: studio_review_ai_attempt(text, text, text, uuid, uuid, bigint, text, text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_review_ai_attempt(p_location_id text, p_actor_app text, p_clerk_user_id text, p_attempt_id uuid, p_request_id uuid, p_expected_version bigint, p_action text, p_evidence text, p_cost_micros bigint, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  a studio.studio_ai_attempts%rowtype;
  j studio.studio_jobs%rowtype;
  prior studio.studio_ai_attempt_reviews%rowtype;
  v_job_id uuid; v_request jsonb; v_result jsonb; v_review uuid := gen_random_uuid();
  v_evidence text := pg_catalog.btrim(p_evidence);
begin
  if p_request_id is null or p_attempt_id is null or p_expected_version is null or p_expected_version < 1
    or p_action is null or p_action not in ('no_charge','billed','authorize_replacement')
    or v_evidence is null or char_length(v_evidence) not between 20 and 2000
    or v_evidence ~ '[\x01-\x08\x0b\x0c\x0e-\x1f]' or v_evidence ~ 'sk-[A-Za-z0-9_-]{16,}' then
    raise exception 'Invalid reconciliation review' using errcode='22023';
  end if;
  if p_action='authorize_replacement' then
    if p_confirm_paid is distinct from true or p_cost_micros is not null then raise exception 'Explicit paid authorization required' using errcode='22023'; end if;
  elsif p_confirm_paid is distinct from false or p_cost_micros is null or p_cost_micros not between 0 and 100000000000
    or (p_action='no_charge' and p_cost_micros <> 0) or (p_action='billed' and p_cost_micros=0) then
    raise exception 'Confirmed cost required' using errcode='22023';
  end if;
  -- Member helper locks the membership through this transaction; role changes
  -- and revocation cannot race review. Estio location ADMIN is checked by app.
  perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
  if p_actor_app='substo' and not exists(select 1 from studio.studio_location_members
    where location_id=p_location_id and clerk_user_id=p_clerk_user_id and role in ('owner','admin')) then
    raise exception 'AI manager required' using errcode='42501';
  end if;
  v_request := pg_catalog.jsonb_build_object('attempt',p_attempt_id,'version',p_expected_version,'action',p_action,
    'evidence',v_evidence,'cost',p_cost_micros,'confirm',p_confirm_paid,'app',p_actor_app,'actor',p_clerk_user_id);
  -- Lock in the same order as worker writes and reclaim: job, then attempt.
  select job_id into v_job_id from studio.studio_ai_attempts where id=p_attempt_id and location_id=p_location_id;
  if not found then raise exception 'Attempt not found' using errcode='22023'; end if;
  select * into j from studio.studio_jobs where id=v_job_id and location_id=p_location_id for update;
  select * into a from studio.studio_ai_attempts where id=p_attempt_id and location_id=p_location_id for update;
  select * into prior from studio.studio_ai_attempt_reviews where location_id=p_location_id and request_id=p_request_id;
  if found then
    if prior.request is distinct from v_request then raise exception 'Review request already used' using errcode='23505'; end if;
    return prior.result;
  end if;
  if a.review_version <> p_expected_version then raise exception 'Review changed; reload' using errcode='40001'; end if;
  if j.status='running' and j.lease_expires_at > pg_catalog.clock_timestamp() then
    raise exception 'Wait for the active worker to finish' using errcode='40001';
  end if;
  if a.status not in ('started','uncertain') or a.replacement_authorized or exists
    (select 1 from studio.studio_transcript_chunks where upload_id=a.upload_id and chunk_index=a.chunk_index) then
    raise exception 'Attempt does not need review' using errcode='40001';
  end if;
  if p_action='authorize_replacement' and (a.billing_outcome is null or j.status='succeeded'
    or exists(select 1 from studio.studio_transcripts where upload_id=a.upload_id)
    or exists(select 1 from studio.studio_idea_reviews where id=a.idea_review_id and result is not null)) then
    raise exception 'Reconcile billing before replacement' using errcode='40001';
  end if;
  if p_action <> 'authorize_replacement' and a.billing_outcome is not null then
    raise exception 'Billing already reconciled' using errcode='40001';
  end if;
  -- Expired executions are fenced and stopped in the same transaction. Never
  -- let an old claim write after a manager releases/settles its reservation.
  if j.status='running' then
    update studio.studio_jobs set status='failed',lease_owner=null,lease_expires_at=null,
      last_error_code='ai_outcome_uncertain',last_error_message='AI processing outcome requires review.',
      finished_at=pg_catalog.clock_timestamp(),updated_at=pg_catalog.clock_timestamp() where id=j.id;
    insert into studio.studio_job_events(job_id,location_id,attempt,event,worker_id,error_code)
      values(j.id,p_location_id,j.attempts,'lease_expired',j.lease_owner,'worker_lease_expired'),
        (j.id,p_location_id,j.attempts,'failed',null,'ai_outcome_uncertain');
  end if;
  if p_action='authorize_replacement' then
    update studio.studio_ai_attempts set status='uncertain',replacement_authorized=true,
      review_version=review_version+1,updated_at=pg_catalog.clock_timestamp() where id=a.id;
    update studio.studio_jobs set status='queued',attempts=0,lease_owner=null,lease_expires_at=null,run_after=pg_catalog.clock_timestamp(),
      finished_at=null,last_error_code=null,last_error_message=null,updated_at=pg_catalog.clock_timestamp() where id=j.id;
    insert into studio.studio_job_events(job_id,location_id,attempt,event,actor_clerk_user_id)
      values(j.id,p_location_id,0,'requeued',p_clerk_user_id);
  else
    if not exists(select 1 from studio.studio_ai_usage where id=a.usage_id and location_id=p_location_id and status='reserved') then
      raise exception 'Reservation no longer available' using errcode='40001'; end if;
    if p_action='no_charge' then
      perform studio.studio_release_ai_spend(p_location_id,a.usage_id);
    else
      perform studio.studio_settle_ai_spend(p_location_id,a.usage_id,p_cost_micros,a.model,null,null,a.duration_seconds);
    end if;
    update studio.studio_ai_attempts set status='uncertain',billing_outcome=p_action,
      review_version=review_version+1,updated_at=pg_catalog.clock_timestamp() where id=a.id;
  end if;
  v_result := pg_catalog.jsonb_build_object('reviewId',v_review,'version',a.review_version+1,'action',p_action,'jobId',j.id);
  insert into studio.studio_ai_attempt_reviews(id,location_id,attempt_id,request_id,actor_app,actor_clerk_user_id,
    action,evidence,cost_micros,previous_version,version,request,result)
    values(v_review,p_location_id,a.id,p_request_id,p_actor_app,p_clerk_user_id,p_action,v_evidence,p_cost_micros,a.review_version,a.review_version+1,v_request,v_result);
  return v_result;
end;
$$;

--
-- Name: studio_review_knowledge_insight(text, uuid, text, bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_review_knowledge_insight(p_location_id text, p_insight_id uuid, p_action text, p_expected_version bigint, p_actor_app text, p_clerk_user_id text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare i studio.studio_knowledge_insights%rowtype; topic jsonb:='{"mode":"keep"}';
begin
 perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
 select * into i from studio.studio_knowledge_insights where location_id=p_location_id and id=p_insight_id;
 if p_action='approve' and i.topic_id is null then topic:=jsonb_build_object('mode','create','name',i.payload->>'suggested_topic'); end if;
 return studio.studio_mutate_knowledge_insight(p_location_id,p_actor_app,p_clerk_user_id,p_insight_id,gen_random_uuid(),p_expected_version,p_action,null,topic,coalesce(p_reason,''));
end; $$;

--
-- Name: studio_review_transcription_attempt(text, text, text, uuid, uuid, bigint, text, text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_review_transcription_attempt(p_location_id text, p_actor_app text, p_clerk_user_id text, p_attempt_id uuid, p_request_id uuid, p_expected_version bigint, p_action text, p_evidence text, p_cost_micros bigint, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select studio.studio_review_ai_attempt(p_location_id,p_actor_app,p_clerk_user_id,p_attempt_id,p_request_id,p_expected_version,p_action,p_evidence,p_cost_micros,p_confirm_paid);
$$;

--
-- Name: studio_run_schedule_now(text, text, text, uuid, bigint, uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_run_schedule_now(p_location_id text, p_actor_app text, p_clerk_user_id text, p_schedule_id uuid, p_expected_version bigint, p_request_id uuid, p_selection jsonb, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s studio.studio_schedules%rowtype; prior studio.studio_schedule_executions%rowtype;
  v_request jsonb; v_workflow text; v_result jsonb; v_execution uuid := gen_random_uuid();
begin
  perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
  if p_schedule_id is null or p_request_id is null or p_expected_version is null or p_expected_version<1
    or p_confirm_paid is distinct from true or p_selection is null or jsonb_typeof(p_selection)<>'array'
    or jsonb_array_length(p_selection) not between 1 and 5 then
    raise exception 'Select current ideas and explicitly authorize this paid run' using errcode='22023'; end if;
  -- Shared across schedules so one request UUID cannot race into two ledgers.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('schedule-command:'||p_location_id::text||':'||p_request_id::text,0));
  v_request := jsonb_build_object('scheduleId',p_schedule_id,'version',p_expected_version,'selection',p_selection,
    'actor',p_clerk_user_id,'app',p_actor_app);
  if exists(select 1 from studio.studio_schedule_commands where location_id=p_location_id and request_id=p_request_id) then raise exception 'Activation request reused' using errcode='23505'; end if;
  select * into prior from studio.studio_schedule_executions where location_id=p_location_id and request_id=p_request_id;
  if found then
    if prior.request is distinct from v_request then raise exception 'Schedule request reused' using errcode='23505'; end if;
    return jsonb_build_object('executionId',prior.id,'reviewId',prior.review_id,'jobId',prior.job_id,'workflow',prior.workflow);
  end if;
  -- Serializes different request IDs with one another and with draft edits.
  select * into s from studio.studio_schedules where location_id=p_location_id and id=p_schedule_id for update;
  if s.id is null or s.version<>p_expected_version then raise exception 'Schedule changed; reload' using errcode='40001'; end if;
  if s.preset_id not in ('idea-review','script-brief') then
    raise exception 'Scheduled YouTube discovery needs a separately selected personal grant' using errcode='22023'; end if;
  if exists(select 1 from studio.studio_schedule_executions e join studio.studio_jobs j on j.id=e.job_id
      where e.location_id=p_location_id and e.schedule_id=p_schedule_id and j.status in ('queued','running'))
    or exists(select 1 from studio.studio_schedule_executions e join studio.studio_ai_attempts a on a.job_id=e.job_id
      where e.location_id=p_location_id and e.schedule_id=p_schedule_id and a.status in ('started','uncertain') and not a.replacement_authorized) then
    raise exception 'A schedule run is active or needs charge reconciliation; use its existing job' using errcode='40001'; end if;
  v_workflow := case when s.preset_id='idea-review' then 'idea_review' else 'script_brief' end;
  -- A private child request UUID prevents cross-feature command identity reuse.
  -- Existing enqueue owns current version/stage/source validation and snapshots.
  v_result := studio.studio_enqueue_text_run(p_location_id,p_actor_app,p_clerk_user_id,gen_random_uuid(),p_selection,s.focus,true,v_workflow);
  insert into studio.studio_schedule_executions(id,location_id,schedule_id,request_id,actor_app,created_by_clerk_user_id,
    request,definition,workflow,review_id,job_id) values(v_execution,p_location_id,p_schedule_id,p_request_id,p_actor_app,p_clerk_user_id,
    v_request,jsonb_build_object('version',s.version,'presetId',s.preset_id,'focus',s.focus,'intervalHours',s.interval_hours,
      'dailyTime',s.daily_time,'timeZone',s.time_zone),v_workflow,(v_result->>'reviewId')::uuid,(v_result->>'jobId')::uuid);
  return v_result||jsonb_build_object('executionId',v_execution,'workflow',v_workflow);
end; $$;

--
-- Name: studio_run_youtube_schedule_now(text, text, text, uuid, bigint, uuid, uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_run_youtube_schedule_now(p_location text, p_app text, p_user text, p_schedule uuid, p_version bigint, p_request uuid, p_connection_version uuid, p_source text, p_channel text, p_title text, p_confirm_share boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s studio.studio_schedules%rowtype; prior studio.studio_schedule_executions%rowtype; request jsonb;
 run uuid:=gen_random_uuid(); execution uuid:=gen_random_uuid(); j studio.studio_jobs%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||p_app||':'||p_user,0));
 perform studio.studio_lock_location_member(p_location,p_app,p_user);
 if p_schedule is null or p_version is null or p_version<1 or p_request is null
 or p_connection_version is null or p_source is null or p_source not in ('approved_channel','search','subscription')
 or p_channel is null or (p_source='search' and p_channel<>'') or (p_source<>'search' and p_channel !~ '^UC[A-Za-z0-9_-]{22}$')
 or p_title is null or char_length(btrim(p_title)) not between 1 and 100 or p_title ~ '[[:cntrl:]]' or p_confirm_share is distinct from true then
 raise exception 'Explicit profile-bound link sharing consent required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('schedule-command:'||p_location::text||':'||p_request::text,0));
 -- Like activation, the audit keeps only a digest of the private source choice.
 request:=jsonb_build_object('action','run_youtube_now','actor',p_user,'app',p_app,'scheduleId',p_schedule,'version',p_version,
 'connectionVersion',p_connection_version,'sourceDigest',encode(sha256(convert_to(jsonb_build_array(p_source,p_channel,btrim(p_title))::text,'UTF8')),'hex'));
 if exists(select 1 from studio.studio_schedule_commands where location_id=p_location and request_id=p_request) then raise exception 'Request reused' using errcode='23505'; end if;
 select * into prior from studio.studio_schedule_executions where location_id=p_location and request_id=p_request;
 if found then
  if prior.request is distinct from request then raise exception 'Run request reused' using errcode='23505'; end if;
  return jsonb_build_object('executionId',prior.id,'discoveryRunId',prior.youtube_run_id,'jobId',prior.job_id,'workflow',prior.workflow);
 end if;
 perform 1 from studio.platform_google_youtube_connections where app=p_app and clerk_user_id=p_user and version=p_connection_version
 and 'https://www.googleapis.com/auth/youtube.readonly'=any(granted_scopes) for share;
 if not found then raise exception 'Current profile grant required' using errcode='42501'; end if;
 select * into s from studio.studio_schedules where location_id=p_location and id=p_schedule for update;
 if s.id is null or s.version<>p_version or s.preset_id<>'youtube-discovery' then raise exception 'YouTube definition changed' using errcode='40001'; end if;
 if p_source='search' and btrim(s.focus)='' then raise exception 'Save a public search focus first' using errcode='22023'; end if;
 if p_source='approved_channel' then
  perform 1 from studio.studio_youtube_channels where location_id=p_location and channel_id=p_channel for share;
  if not found then raise exception 'Channel not approved' using errcode='42501'; end if;
 end if;
 if exists(select 1 from studio.studio_schedule_executions e join studio.studio_jobs x on x.id=e.job_id
  where e.location_id=p_location and e.schedule_id=p_schedule and x.status in ('queued','running')) then
  raise exception 'A run for this schedule is already queued or running' using errcode='40001'; end if;
 perform pg_advisory_xact_lock(hashtextextended('youtube-schedule-enqueue:'||p_location::text,0));
 if (select count(*) from studio.studio_jobs where location_id=p_location and kind='studio.youtube_discovery' and status in ('queued','running'))>=5 then raise exception 'Too many active discovery runs' using errcode='40001'; end if;
 j:=studio.studio_enqueue_job(p_location,'studio.youtube_discovery',jsonb_build_object('discoveryRunId',run),'youtube-discovery:'||run::text,p_user,3);
 insert into studio.studio_youtube_schedule_runs(id,location_id,schedule_id,activation_token,job_id,actor_app,created_by_clerk_user_id,
  manual,source_mode,channel_id,title_prefix,connection_version,schedule_version)
 values(run,p_location,p_schedule,gen_random_uuid(),j.id,p_app,p_user,true,p_source,p_channel,btrim(p_title),p_connection_version,s.version);
 insert into studio.studio_schedule_executions(id,location_id,schedule_id,request_id,actor_app,created_by_clerk_user_id,request,definition,workflow,youtube_run_id,job_id)
 values(execution,p_location,p_schedule,p_request,p_app,p_user,request,
 jsonb_build_object('version',s.version,'presetId',s.preset_id,'focus',s.focus,'intervalHours',s.interval_hours,'dailyTime',s.daily_time,'timeZone',s.time_zone),'youtube_discovery',run,j.id);
 return jsonb_build_object('executionId',execution,'discoveryRunId',run,'jobId',j.id,'workflow','youtube_discovery');
end; $_$;

--
-- Name: studio_save_record(text, uuid, text, text, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_save_record(p_location_id text, p_record_id uuid, p_kind text, p_title text, p_payload_patch jsonb, p_expected_version bigint, p_clerk_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_payload_patch ? 'linkedIds' then raise exception 'Use the record link operation' using errcode = '22023'; end if;
  return studio.studio_save_record_fields(p_location_id,p_record_id,p_kind,p_title,p_payload_patch,p_expected_version,p_clerk_user_id);
end;
$$;

--
-- Name: studio_save_record_fields(text, uuid, text, text, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_save_record_fields(p_location_id text, p_record_id uuid, p_kind text, p_title text, p_payload_patch jsonb, p_expected_version bigint, p_clerk_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_record studio.studio_records%rowtype;
begin
  if p_location_id is null or p_record_id is null or p_kind is null or p_kind not in ('reference','channel','content')
    or p_title is null or pg_catalog.btrim(p_title) = '' or pg_catalog.length(p_title) > 180
    or p_payload_patch is null or pg_catalog.jsonb_typeof(p_payload_patch) <> 'object'
    or p_expected_version is null or p_expected_version < 0
    or p_clerk_user_id is null or pg_catalog.btrim(p_clerk_user_id) = '' then
    raise exception 'Invalid Studio record' using errcode = '22023';
  end if;

  if p_expected_version = 0 then
    insert into studio.studio_records(location_id,id,kind,title,payload,created_by_clerk_user_id)
    values(p_location_id,p_record_id,p_kind,pg_catalog.btrim(p_title),p_payload_patch,p_clerk_user_id)
    on conflict (location_id,id) do nothing;
    select * into v_record from studio.studio_records where location_id=p_location_id and id=p_record_id for update;
    if v_record.kind <> p_kind or v_record.title <> pg_catalog.btrim(p_title)
      or v_record.payload <> p_payload_patch or v_record.created_by_clerk_user_id is distinct from p_clerk_user_id then
      raise exception 'Record already exists' using errcode = '23505';
    end if;
  else
    update studio.studio_records set title=pg_catalog.btrim(p_title), payload=payload || p_payload_patch,
      version=version+1, updated_at=pg_catalog.now()
    where location_id=p_location_id and id=p_record_id and kind=p_kind and version=p_expected_version
    returning * into v_record;
    if not found then raise exception 'Record changed; reload before saving' using errcode = '40001'; end if;
  end if;
  return pg_catalog.to_jsonb(v_record);
end;
$$;

--
-- Name: studio_schedules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE studio.studio_schedules (
    location_id text NOT NULL,
    id uuid NOT NULL,
    preset_id text NOT NULL,
    focus text NOT NULL,
    interval_hours integer NOT NULL,
    daily_time text NOT NULL,
    time_zone text DEFAULT 'Asia/Nicosia'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text NOT NULL,
    CONSTRAINT studio_schedules_daily_time_check CHECK ((daily_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'::text)),
    CONSTRAINT studio_schedules_focus_check CHECK (((char_length(focus) <= 160) AND (focus !~ '[[:cntrl:]]'::text))),
    CONSTRAINT studio_schedules_interval_hours_check CHECK ((interval_hours = ANY (ARRAY[24, 168]))),
    CONSTRAINT studio_schedules_preset_id_check CHECK ((preset_id = ANY (ARRAY['youtube-discovery'::text, 'idea-review'::text, 'script-brief'::text]))),
    CONSTRAINT studio_schedules_time_zone_check CHECK ((time_zone = 'Asia/Nicosia'::text)),
    CONSTRAINT studio_schedules_version_check CHECK ((version > 0))
);

--
-- Name: studio_save_schedule(text, uuid, bigint, text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_save_schedule(p_location_id text, p_id uuid, p_expected_version bigint, p_actor_app text, p_clerk_user_id text, p_preset_id text, p_focus text, p_interval_hours integer, p_daily_time text) RETURNS studio.studio_schedules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_app text;
  v_row studio.studio_schedules%rowtype;
begin
  perform studio.platform_require_active_profile(p_actor_app,p_clerk_user_id);
  if p_location_id is null or p_id is null or p_expected_version is null or p_expected_version < 0
    or p_actor_app is null or p_actor_app not in ('estio','substo')
    or p_clerk_user_id is null or btrim(p_clerk_user_id) = ''
    or p_preset_id is null or p_preset_id not in ('youtube-discovery','idea-review','script-brief')
    or p_focus is null or char_length(p_focus) > 160 or p_focus ~ '[[:cntrl:]]'
    or p_interval_hours is null or p_interval_hours not in (24,168)
    or p_daily_time is null or p_daily_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
    raise exception 'Invalid schedule definition' using errcode = '22023';
  end if;
  select app into v_app from studio.studio_locations where location_id = p_location_id;
  if v_app is null or v_app <> p_actor_app then
    raise exception 'Schedule location access denied' using errcode = '42501';
  end if;
  -- Estio authority resides in Business and must be checked by the server.
  -- Lock Substo membership so revocation cannot race the write.
  if v_app = 'substo' then
    perform 1 from studio.studio_location_members
      where location_id = p_location_id and location_app = 'substo' and clerk_user_id = p_clerk_user_id for share;
    if not found then
      raise exception 'Schedule membership denied' using errcode = '42501';
    end if;
  end if;
  if p_expected_version = 0 then
    insert into studio.studio_schedules(location_id,id,preset_id,focus,interval_hours,daily_time,updated_by)
      values(p_location_id,p_id,p_preset_id,p_focus,p_interval_hours,p_daily_time,p_clerk_user_id)
      on conflict (location_id,id) do nothing returning * into v_row;
  else
    update studio.studio_schedules set preset_id = p_preset_id, focus = p_focus,
      interval_hours = p_interval_hours, daily_time = p_daily_time,
      version = version + 1, updated_at = clock_timestamp(), updated_by = p_clerk_user_id
      where location_id = p_location_id and id = p_id and version = p_expected_version
      returning * into v_row;
  end if;
  if v_row.id is null then
    raise exception 'Schedule changed or is no longer available' using errcode = '40001';
  end if;
  return v_row;
end;
$_$;

--
-- Name: studio_save_transcript(text, uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_save_transcript(p_location_id text, p_upload_id uuid, p_model text, p_language text, p_duration_seconds numeric) RETURNS studio.studio_transcripts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row studio.studio_transcripts%rowtype;
begin
  if not exists(select 1 from studio.studio_uploads where id=p_upload_id and location_id=p_location_id and status='uploaded') then
    raise exception 'Upload not ready' using errcode = '22023';
  end if;
  -- Assemble from the saved chunks so the transcript always equals what was billed.
  insert into studio.studio_transcripts(upload_id,location_id,model,language,duration_seconds,text,segments)
    select p_upload_id,p_location_id,p_model,p_language,p_duration_seconds,
      coalesce(pg_catalog.string_agg(pg_catalog.btrim(text),' ' order by chunk_index) filter (where pg_catalog.btrim(text) <> ''),''),
      coalesce((select pg_catalog.jsonb_agg(s order by c.chunk_index, o) from studio.studio_transcript_chunks c,
        pg_catalog.jsonb_array_elements(c.segments) with ordinality as e(s,o) where c.upload_id=p_upload_id),'[]'::jsonb)
    from studio.studio_transcript_chunks where upload_id=p_upload_id
    on conflict (upload_id) do nothing returning * into v_row;
  if v_row.upload_id is null then select * into v_row from studio.studio_transcripts where upload_id=p_upload_id; end if;
  return v_row;
end;
$$;

--
-- Name: studio_save_transcript_chunk(text, uuid, integer, numeric, numeric, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_save_transcript_chunk(p_location_id text, p_upload_id uuid, p_chunk_index integer, p_start_seconds numeric, p_duration_seconds numeric, p_model text, p_text text, p_segments jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists(select 1 from studio.studio_uploads where id=p_upload_id and location_id=p_location_id and status='uploaded') then
    raise exception 'Upload not ready' using errcode = '22023';
  end if;
  insert into studio.studio_transcript_chunks(location_id,upload_id,chunk_index,start_seconds,duration_seconds,model,text,segments)
    values(p_location_id,p_upload_id,p_chunk_index,p_start_seconds,p_duration_seconds,p_model,p_text,p_segments)
    on conflict (upload_id,chunk_index) do nothing;
  return found;
end;
$$;

--
-- Name: studio_save_youtube_bookmark(text, text, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_save_youtube_bookmark(p_location text, p_app text, p_user text, p_record uuid, p_video text, p_title text, p_provenance jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_record uuid;
begin
  perform studio.studio_lock_youtube_member(p_location,p_app,p_user);
  if p_record is null or p_video is null or p_video !~ '^[A-Za-z0-9_-]{11}$' or p_title is null or char_length(btrim(p_title)) not between 1 and 180
    or jsonb_typeof(p_provenance) is distinct from 'object' or p_provenance->>'kind' is null
    or p_provenance->>'kind' not in ('public_search','approved_channel','subscription','saved_url')
    or octet_length(p_provenance::text)>4096 then raise exception 'Invalid research link' using errcode='22023'; end if;
  select record_id into v_record from studio.studio_youtube_bookmarks where location_id=p_location and video_id=p_video;
  if v_record is not null then return v_record; end if;
  select id into v_record from studio.studio_records where location_id=p_location and kind='reference'
    and source_url='https://www.youtube.com/watch?v='||p_video order by created_at,id limit 1;
  if v_record is not null then
    insert into studio.studio_youtube_bookmarks(location_id,video_id,record_id) values(p_location,p_video,v_record);
    return v_record;
  end if;
  insert into studio.studio_records(location_id,id,kind,title,payload,created_by_clerk_user_id)
    values(p_location,p_record,'reference',btrim(p_title),jsonb_build_object('title',btrim(p_title),'url','https://www.youtube.com/watch?v='||p_video,
      'platform','YouTube','discovery',p_provenance,'approved',false,'archived',false),p_user);
  insert into studio.studio_youtube_bookmarks(location_id,video_id,record_id) values(p_location,p_video,p_record);
  return p_record;
end;
$_$;

--
-- Name: studio_schedule_import_timestamp_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_schedule_import_timestamp_valid(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare v_text text; v_time timestamptz;
begin
  if jsonb_typeof(p_value) is distinct from 'string' then return false; end if;
  v_text := p_value #>> '{}';
  if v_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{3})?Z$' then return false; end if;
  v_time := v_text::timestamptz;
  return replace(to_char(v_time at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'.000Z','Z') = replace(v_text,'.000Z','Z');
exception when others then return false;
end;
$_$;

--
-- Name: studio_set_ai_budget(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_set_ai_budget(p_location_id text, p_actor_app text, p_clerk_user_id text, p_monthly_budget_micros bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row studio.studio_location_ai_settings%rowtype;
begin
  if p_monthly_budget_micros is null then raise exception 'Invalid budget' using errcode = '22023'; end if;
  perform studio.studio_lock_ai_manager(p_location_id, p_actor_app, p_clerk_user_id);
  insert into studio.studio_location_ai_settings(location_id,monthly_budget_micros,updated_by_clerk_user_id)
    values(p_location_id,p_monthly_budget_micros,p_clerk_user_id)
    on conflict (location_id) do update set monthly_budget_micros=excluded.monthly_budget_micros,
      version=studio.studio_location_ai_settings.version+1, updated_by_clerk_user_id=excluded.updated_by_clerk_user_id, updated_at=pg_catalog.clock_timestamp()
    returning * into v_row;
  return pg_catalog.jsonb_build_object('monthlyBudgetMicros',v_row.monthly_budget_micros,'version',v_row.version);
end;
$$;

--
-- Name: studio_set_ai_credential(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_set_ai_credential(p_location_id text, p_actor_app text, p_clerk_user_id text, p_provider text, p_ciphertext text, p_iv text, p_auth_tag text, p_key_id text, p_key_hint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row studio.studio_location_ai_credentials%rowtype;
begin
  perform studio.studio_lock_ai_manager(p_location_id, p_actor_app, p_clerk_user_id);
  insert into studio.studio_location_ai_credentials(location_id,provider,ciphertext,iv,auth_tag,key_id,key_hint,set_by_clerk_user_id)
    values(p_location_id,p_provider,p_ciphertext,p_iv,p_auth_tag,p_key_id,p_key_hint,p_clerk_user_id)
    on conflict (location_id,provider) do update set ciphertext=excluded.ciphertext, iv=excluded.iv, auth_tag=excluded.auth_tag,
      key_id=excluded.key_id, key_hint=excluded.key_hint, version=studio.studio_location_ai_credentials.version+1,
      set_by_clerk_user_id=excluded.set_by_clerk_user_id, set_at=pg_catalog.clock_timestamp()
    returning * into v_row;
  return pg_catalog.jsonb_build_object('provider',v_row.provider,'keyHint',v_row.key_hint,'version',v_row.version);
end;
$$;

--
-- Name: studio_set_schedule_recurring(text, text, text, uuid, bigint, bigint, uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_set_schedule_recurring(p_location_id text, p_actor_app text, p_clerk_user_id text, p_schedule_id uuid, p_expected_version bigint, p_state_version bigint, p_request_id uuid, p_action text, p_selection jsonb, p_confirm_paid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s studio.studio_schedules%rowtype; r studio.studio_schedule_recurring%rowtype; prior studio.studio_schedule_commands%rowtype;
  command jsonb; result jsonb; v_snapshot jsonb; v_workflow text;
begin
  perform studio.studio_lock_location_member(p_location_id,p_actor_app,p_clerk_user_id);
  if p_schedule_id is null or p_request_id is null or p_expected_version is null or p_expected_version<1
    or p_state_version is null or p_state_version<0 or p_action is null or p_action not in ('enable','pause') then
    raise exception 'Invalid schedule command' using errcode='22023'; end if;
  if p_action='enable' and p_confirm_paid is distinct from true then raise exception 'Explicit recurring spend authorization required' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('schedule-command:'||p_location_id::text||':'||p_request_id::text,0));
  command := jsonb_build_object('action',p_action,'scheduleId',p_schedule_id,'version',p_expected_version,'stateVersion',p_state_version,
    'actor',p_clerk_user_id,'app',p_actor_app,'selection',p_selection,'confirmPaid',p_confirm_paid);
  select * into prior from studio.studio_schedule_commands where location_id=p_location_id and request_id=p_request_id;
  if found then
    if prior.request is distinct from command then raise exception 'Command request reused' using errcode='23505'; end if;
    return prior.result;
  end if;
  if exists(select 1 from studio.studio_schedule_executions where location_id=p_location_id and request_id=p_request_id) then raise exception 'Run request reused' using errcode='23505'; end if;
  select * into s from studio.studio_schedules where location_id=p_location_id and id=p_schedule_id for update;
  if s.id is null or s.version<>p_expected_version then raise exception 'Schedule changed' using errcode='40001'; end if;
  select * into r from studio.studio_schedule_recurring where location_id=p_location_id and schedule_id=p_schedule_id for update;
  if coalesce(r.version,0)<>p_state_version then raise exception 'Activation changed' using errcode='40001'; end if;
  if p_action='enable' then
    if s.preset_id not in ('idea-review','script-brief') then raise exception 'YouTube needs a personal grant design' using errcode='22023'; end if;
    v_workflow := case when s.preset_id='idea-review' then 'idea_review' else 'script_brief' end;
    v_snapshot := studio.studio_build_selected_text_snapshot(p_location_id,p_selection,s.focus,v_workflow);
    insert into studio.studio_schedule_recurring(location_id,schedule_id,actor_app,authorized_by,schedule_version,selection,snapshot,enabled,next_run_at,last_outcome)
      values(p_location_id,p_schedule_id,p_actor_app,p_clerk_user_id,s.version,p_selection,v_snapshot,true,
        studio.studio_next_schedule_due(clock_timestamp(),s.interval_hours,s.daily_time,s.time_zone),'enabled')
      on conflict(location_id,schedule_id) do update set version=studio_schedule_recurring.version+1,
        actor_app=excluded.actor_app,authorized_by=excluded.authorized_by,schedule_version=excluded.schedule_version,
        selection=excluded.selection,snapshot=excluded.snapshot,enabled=true,activation_token=gen_random_uuid(),
        next_run_at=excluded.next_run_at,last_outcome='enabled',updated_at=clock_timestamp() returning * into r;
  else
    if r.schedule_id is null then raise exception 'No activation to pause' using errcode='40001'; end if;
    update studio.studio_schedule_recurring set enabled=false,next_run_at=null,version=version+1,last_outcome='paused',updated_at=clock_timestamp()
      where location_id=p_location_id and schedule_id=p_schedule_id returning * into r;
  end if;
  result:=jsonb_build_object('enabled',r.enabled,'stateVersion',r.version,'nextRunAt',r.next_run_at);
  insert into studio.studio_schedule_commands(location_id,request_id,request,result,snapshot) values(p_location_id,p_request_id,command,result,v_snapshot);
  return result;
end; $$;

--
-- Name: studio_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

--
-- Name: studio_settle_ai_spend(text, uuid, bigint, text, bigint, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_settle_ai_spend(p_location_id text, p_usage_id uuid, p_cost_micros bigint, p_model text, p_input_tokens bigint, p_output_tokens bigint, p_audio_seconds numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row studio.studio_ai_usage%rowtype;
begin
  if p_cost_micros is null or p_cost_micros < 0 then raise exception 'Invalid cost' using errcode = '22023'; end if;
  select * into v_row from studio.studio_ai_usage where id=p_usage_id and location_id=p_location_id for update;
  if not found then raise exception 'Unknown AI usage reservation' using errcode = '22023'; end if;
  if v_row.status = 'settled' then
    if v_row.cost_micros <> p_cost_micros then raise exception 'AI usage already settled differently' using errcode = '23505'; end if;
    return pg_catalog.jsonb_build_object('id',v_row.id,'replayed',true);
  end if;
  update studio.studio_ai_usage set status='settled', cost_micros=p_cost_micros, model=p_model, input_tokens=p_input_tokens,
    output_tokens=p_output_tokens, audio_seconds=p_audio_seconds, settled_at=pg_catalog.clock_timestamp()
    where id=p_usage_id returning * into v_row;
  return pg_catalog.jsonb_build_object('id',v_row.id,'replayed',false);
end;
$$;

--
-- Name: studio_stop_youtube_discovery(text, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_stop_youtube_discovery(p_location text, p_run uuid, p_job uuid, p_worker text, p_lease uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare run studio.studio_youtube_schedule_runs%rowtype; j studio.studio_jobs%rowtype;
begin
 select * into run from studio.studio_youtube_schedule_runs where location_id=p_location and id=p_run and job_id=p_job;
 if run.id is null or p_reason is null or p_reason not in ('profile_grant_changed','source_unavailable','authority_revoked') then raise exception 'Invalid stop request' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('platform-youtube:'||run.actor_app||':'||run.created_by_clerk_user_id,0));
 perform 1 from studio.studio_schedules where location_id=p_location and id=run.schedule_id for share;
 perform 1 from studio.studio_schedule_recurring where location_id=p_location and schedule_id=run.schedule_id for update;
 select * into j from studio.studio_jobs where id=p_job for update;
 if j.status<>'running' or j.lease_owner is distinct from p_worker or j.lease_token is distinct from p_lease or j.lease_expires_at<=clock_timestamp() then raise exception 'Current lease required' using errcode='40001'; end if;
 update studio.studio_schedule_recurring set enabled=false,next_run_at=null,version=version+1,last_outcome=p_reason,updated_at=clock_timestamp()
 where location_id=p_location and schedule_id=run.schedule_id and activation_token=run.activation_token and enabled;
end; $$;

--
-- Name: studio_validate_text_run_result(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_validate_text_run_result(p_workflow text, p_result jsonb, snapshot jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare f jsonb; unit jsonb; key text;
begin
 if p_workflow<>'knowledge_extract' then perform studio.studio_validate_text_run_result_v19(p_workflow,p_result,snapshot);return; end if;
 if p_result is null or jsonb_typeof(p_result)<>'object' or octet_length(p_result::text)>24000 or jsonb_typeof(p_result->'findings') is distinct from 'array' then raise exception 'Invalid extraction result' using errcode='22023'; end if;
 if jsonb_array_length(p_result->'findings')>10 or (select count(distinct jsonb_build_array(x->>'kind',x->>'statement')) from jsonb_array_elements(p_result->'findings') x)<>jsonb_array_length(p_result->'findings') then raise exception 'Duplicate or excessive findings' using errcode='22023'; end if;
 for f in select * from jsonb_array_elements(p_result->'findings') loop
  if f->>'kind' is null or f->>'kind' not in ('claim','method','example','question','objection','content_pattern') then raise exception 'Invalid finding kind' using errcode='22023'; end if;
  foreach key in array array['unitId','statement','suggestedTopic','quote'] loop
   if jsonb_typeof(f->key) is distinct from 'string' or coalesce(char_length(btrim(f->>key)),0) not between 1 and
    (case key when 'statement' then 1000 when 'suggestedTopic' then 120 when 'quote' then 600 else 300 end) then raise exception 'Invalid finding text' using errcode='22023'; end if;
  end loop;
  select u into unit from jsonb_array_elements(snapshot->'units') u where u->>'id'=f->>'unitId';
  if not found or strpos(unit->>'text',f->>'quote')=0 then raise exception 'Quote must match its selected source unit exactly' using errcode='22023'; end if;
 end loop;
end; $$;

--
-- Name: studio_validate_text_run_result_v19(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_validate_text_run_result_v19(p_workflow text, p_result jsonb, snapshot jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare score jsonb; source jsonb; item jsonb; v_field text;
begin
  if p_result is null or jsonb_typeof(p_result)<>'object' then raise exception 'Invalid text result' using errcode='22023'; end if;
  if p_workflow='idea_review' then
    if octet_length(p_result::text)>20000 or jsonb_typeof(p_result->'scores') is distinct from 'array'
      or jsonb_typeof(p_result->'reason') is distinct from 'string' or coalesce(length(p_result->>'reason'),0) not between 1 and 2000
      or jsonb_typeof(p_result->'verificationGap') is distinct from 'string' or coalesce(length(p_result->>'verificationGap'),0) not between 1 and 2000 then
      raise exception 'Invalid idea review' using errcode='22023'; end if;
  if jsonb_array_length(p_result->'scores')<>jsonb_array_length(snapshot->'ideas')
    or not exists(select 1 from jsonb_array_elements(snapshot->'ideas') i where i->>'id'=p_result->>'recommendation')
    or (select count(distinct s->>'ideaId') from jsonb_array_elements(p_result->'scores') s)<>jsonb_array_length(snapshot->'ideas') then
    raise exception 'Review does not cover selected ideas' using errcode='22023'; end if;
  for score in select * from jsonb_array_elements(p_result->'scores') loop
    if not exists(select 1 from jsonb_array_elements(snapshot->'ideas') i where i->>'id'=score->>'ideaId')
      or coalesce(length(score->>'rationale'),0) not between 1 and 1200 or jsonb_typeof(score->'sourceIds') is distinct from 'array'
      or exists(select 1 from unnest(array['relevance','evidence','timeliness','differentiation','ease']) k where (score->>k) is null or (score->>k) !~ '^[1-5]$') then
      raise exception 'Invalid idea score' using errcode='22023'; end if;
    for source in select * from jsonb_array_elements(score->'sourceIds') loop
      if not exists(select 1 from jsonb_array_elements(snapshot->'ideas') i,jsonb_array_elements(i->'sources') s
        where i->>'id'=score->>'ideaId' and s->'id'=source) then raise exception 'Unsupported source citation' using errcode='22023'; end if;
    end loop;
  end loop;

  elsif p_workflow='script_brief' then
    if jsonb_array_length(snapshot->'ideas')<>1 or octet_length(p_result::text)>64000 then raise exception 'Invalid script brief' using errcode='22023'; end if;
    foreach v_field in array array['audiencePromise','angle','hook','script'] loop
      if jsonb_typeof(p_result->v_field) is distinct from 'string' or coalesce(length(btrim(p_result->>v_field)),0) not between 1 and
        (case when v_field='script' then 16000 else 1000 end) then raise exception 'Invalid brief text' using errcode='22023'; end if;
    end loop;
    foreach v_field in array array['outline','verificationGaps'] loop
      if jsonb_typeof(p_result->v_field) is distinct from 'array' then raise exception 'Invalid brief list' using errcode='22023'; end if;
      if jsonb_array_length(p_result->v_field) not between 1 and 8 then raise exception 'Invalid brief list length' using errcode='22023'; end if;
      for item in select * from jsonb_array_elements(p_result->v_field) loop
        if jsonb_typeof(item)<>'string' or coalesce(length(btrim(item#>>'{}')),0) not between 1 and 500 then
          raise exception 'Invalid brief list item' using errcode='22023'; end if;
      end loop;
    end loop;
    if jsonb_typeof(p_result->'claims') is distinct from 'array' then raise exception 'Invalid brief claims' using errcode='22023'; end if;
    if jsonb_array_length(p_result->'claims') not between 1 and 8 then raise exception 'Invalid brief claim count' using errcode='22023'; end if;
    for score in select * from jsonb_array_elements(p_result->'claims') loop
      if jsonb_typeof(score->'claim') is distinct from 'string' or coalesce(length(btrim(score->>'claim')),0) not between 1 and 500
        or jsonb_typeof(score->'sourceIds') is distinct from 'array' or jsonb_typeof(score->'verificationNeeded') is distinct from 'boolean' then
        raise exception 'Invalid brief claim' using errcode='22023'; end if;
      if jsonb_array_length(score->'sourceIds')>3 or (jsonb_array_length(score->'sourceIds')=0 and score->'verificationNeeded'<>'true'::jsonb)
        or (select count(distinct s) from jsonb_array_elements(score->'sourceIds') s)<>jsonb_array_length(score->'sourceIds') then
        raise exception 'Unsupported claim must be marked for verification' using errcode='22023'; end if;
      for source in select * from jsonb_array_elements(score->'sourceIds') loop
        if not exists(select 1 from jsonb_array_elements(snapshot->'ideas'->0->'sources') s where s->'id'=source) then
          raise exception 'Unsupported brief citation' using errcode='22023'; end if;
      end loop;
    end loop;
  else raise exception 'Unsupported text workflow' using errcode='22023'; end if;
end; $_$;

--
-- Name: studio_worker_heartbeat(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_worker_heartbeat(p_worker_id text, p_release text, p_started_at timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 insert into studio.studio_worker_heartbeats(worker_id,release,started_at,seen_at)
 values(p_worker_id,p_release,p_started_at,pg_catalog.clock_timestamp())
 on conflict(worker_id) do update set release=excluded.release,started_at=excluded.started_at,seen_at=excluded.seen_at,
 instance_id=null,protocol=null,handlers='{}',healthy=false,draining=false;
 delete from studio.studio_worker_heartbeats where seen_at<pg_catalog.clock_timestamp()-interval '7 days';
$$;

--
-- Name: studio_youtube_channel(text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_youtube_channel(p_location text, p_app text, p_user text, p_channel text, p_label text, p_remove boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  perform studio.studio_lock_ai_manager(p_location,p_app,p_user);
  if p_channel is null or p_channel !~ '^UC[A-Za-z0-9_-]{22}$' or p_remove is null then raise exception 'Invalid channel' using errcode='22023'; end if;
  if p_remove then delete from studio.studio_youtube_channels where location_id=p_location and channel_id=p_channel;
  else
    if p_label is null or char_length(btrim(p_label)) not between 1 and 180 then raise exception 'Channel label required' using errcode='22023'; end if;
    if (select count(*) from studio.studio_youtube_channels where location_id=p_location)>=100 and not exists(select 1 from studio.studio_youtube_channels where location_id=p_location and channel_id=p_channel) then raise exception 'Too many approved channels' using errcode='22023'; end if;
    insert into studio.studio_youtube_channels(location_id,channel_id,label,approved_by) values(p_location,p_channel,btrim(p_label),p_user)
      on conflict(location_id,channel_id) do update set label=excluded.label,approved_by=excluded.approved_by;
  end if;
end;
$_$;

--
-- Name: studio_youtube_request_slot(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION studio.studio_youtube_request_slot(p_location text, p_app text, p_user text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform studio.studio_lock_youtube_member(p_location,p_app,p_user);
  insert into studio.studio_youtube_usage(location_id,day,requests) values(p_location,(now() at time zone 'UTC')::date,1)
    on conflict(location_id,day) do update set requests=studio.studio_youtube_usage.requests+1 where studio.studio_youtube_usage.requests<50;
  return found;
end;
$$;

