--

CREATE TABLE studio.studio_ai_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    location_id text NOT NULL,
    upload_id uuid,
    job_id uuid NOT NULL,
    lease_token uuid NOT NULL,
    job_attempt integer NOT NULL,
    worker_id text NOT NULL,
    chunk_index integer,
    duration_seconds numeric,
    usage_id uuid NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    review_version bigint DEFAULT 1 NOT NULL,
    billing_outcome text,
    replacement_authorized boolean DEFAULT false NOT NULL,
    operation text DEFAULT 'transcribe_upload'::text NOT NULL,
    idea_review_id uuid,
    model text DEFAULT 'whisper-1'::text NOT NULL,
    provider_response_id text,
    rate_version text,
    CONSTRAINT studio_ai_attempt_subject CHECK ((((operation = 'transcribe_upload'::text) AND (upload_id IS NOT NULL) AND (chunk_index IS NOT NULL) AND (duration_seconds IS NOT NULL) AND (idea_review_id IS NULL) AND (model = 'whisper-1'::text)) OR ((operation = ANY (ARRAY['idea_review'::text, 'script_brief'::text, 'knowledge_extract'::text])) AND (upload_id IS NULL) AND (chunk_index IS NULL) AND (duration_seconds IS NULL) AND (idea_review_id IS NOT NULL) AND (model = 'gpt-6-luna'::text)))),
    CONSTRAINT studio_attempt_review_state CHECK ((((billing_outcome IS NULL) OR (status = 'uncertain'::text)) AND ((NOT replacement_authorized) OR (billing_outcome IS NOT NULL)))),
    CONSTRAINT studio_transcription_attempts_billing_outcome_check CHECK ((billing_outcome = ANY (ARRAY['no_charge'::text, 'billed'::text]))),
    CONSTRAINT studio_transcription_attempts_chunk_index_check CHECK (((chunk_index >= 0) AND (chunk_index <= 35))),
    CONSTRAINT studio_transcription_attempts_duration_seconds_check CHECK (((duration_seconds > (0)::numeric) AND (duration_seconds <= (600)::numeric))),
    CONSTRAINT studio_transcription_attempts_review_version_check CHECK ((review_version > 0)),
    CONSTRAINT studio_transcription_attempts_status_check CHECK ((status = ANY (ARRAY['started'::text, 'succeeded'::text, 'rejected'::text, 'uncertain'::text])))
);

