    seen_at timestamp with time zone DEFAULT now() NOT NULL,
    instance_id text,
    protocol integer,
    handlers text[] DEFAULT '{}'::text[] NOT NULL,
    healthy boolean DEFAULT false NOT NULL,
    draining boolean DEFAULT false NOT NULL,
    CONSTRAINT studio_worker_heartbeats_release_check CHECK (((release IS NULL) OR (char_length(release) <= 100))),
    CONSTRAINT studio_worker_heartbeats_worker_id_check CHECK ((worker_id ~ '^[A-Za-z0-9:._-]{1,100}$'::text))
);

